def allocate_medical_shipments(orders, warehouses, carrier_service):
    results = []
    for order in orders:
        allocations, shortages = [], []
        if order.get("approved"):
            if order.get("destination"):
                if order.get("items"):
                    for item in order["items"]:
                        remaining = item["quantity"]
                        if remaining > 0:
                            for warehouse in warehouses:
                                if warehouse["region"] == order["region"]:
                                    if not item.get("controlled") or warehouse.get("licensed"):
                                        for batch in warehouse["batches"]:
                                            if batch["sku"] == item["sku"] and batch["expires_on"] > order["deliver_by"]:
                                                if not item.get("cold_chain") or warehouse.get("refrigerated"):
                                                    if batch["available"] > 0 and remaining > 0:
                                                        quantity = min(remaining, batch["available"])
                                                        batch["available"] -= quantity
                                                        remaining -= quantity
                                                        allocations.append((warehouse["id"], batch, quantity))
                            if remaining:
                                shortages.append({"sku": item["sku"], "quantity": remaining})
                        else:
                            shortages.append({"sku": item["sku"], "error": "Invalid quantity"})
                    if shortages and not order.get("allow_partial"):
                        for _, batch, quantity in allocations:
                            batch["available"] += quantity
                        results.append({"id": order["id"], "status": "blocked", "shortages": shortages})
                    elif allocations:
                        try:
                            shipment = carrier_service.book(
                                order_id=order["id"], destination=order["destination"],
                                parcels=[{"warehouse": wid, "sku": batch["sku"], "quantity": qty}
                                         for wid, batch, qty in allocations],
                                refrigerated=any(item.get("cold_chain") for item in order["items"]),
                            )
                        except Exception as exc:
                            results.append({"id": order["id"], "status": "booking_uncertain",
                                            "error": str(exc), "inventory_held": True})
                        else:
                            results.append({"id": order["id"], "status": "booked",
                                            "shipment": shipment, "shortages": shortages})
                    else:
                        results.append({"id": order["id"], "status": "out_of_stock"})
                else:
                    results.append({"id": order["id"], "status": "empty"})
            else:
                results.append({"id": order["id"], "status": "missing_destination"})
        else:
            results.append({"id": order["id"], "status": "awaiting_approval"})
    return results

