def allocate_shipments(order, warehouses, carrier_service):
    allocations, shortages, errors = [], [], []
    if order.get("status") != "paid":
        return {"status": "rejected", "reason": "Payment required"}
    for item in order.get("items", []):
        remaining = item["quantity"]
        if remaining <= 0:
            errors.append({"sku": item["sku"], "reason": "Invalid quantity"})
            continue
        for warehouse in warehouses:
            if remaining > 0:
                if warehouse.get("active"):
                    if order["country"] in warehouse.get("destinations", []):
                        if not item.get("cold_chain") or warehouse.get("refrigerated"):
                            available = warehouse["stock"].get(item["sku"], 0)
                            if available > 0:
                                quantity = min(available, remaining)
                                if not order.get("allow_split") and quantity < remaining:
                                    continue
                                try:
                                    quotes = carrier_service.quote(
                                        warehouse["id"], order["address"], item, quantity
                                    )
                                    eligible = []
                                    for quote in quotes:
                                        if quote["capacity"] >= quantity:
                                            if not item.get("hazardous") or quote.get("hazmat"):
                                                if order.get("express"):
                                                    if quote["transit_days"] <= 2:
                                                        eligible.append(quote)
                                                elif quote["cost"] <= order["shipping_limit"]:
                                                    eligible.append(quote)
                                    if eligible:
                                        chosen = min(eligible, key=lambda quote: quote["cost"])
                                        allocations.append({"sku": item["sku"], "quantity": quantity,
                                                            "warehouse": warehouse["id"], "quote": chosen})
                                        warehouse["stock"][item["sku"]] -= quantity
                                        remaining -= quantity
                                    else:
                                        errors.append({"sku": item["sku"], "reason": "No eligible carrier"})
                                except (TimeoutError, ConnectionError) as exc:
                                    errors.append({"warehouse": warehouse["id"], "reason": str(exc)})
                                except (KeyError, TypeError, ValueError) as exc:
                                    errors.append({"sku": item["sku"], "reason": str(exc)})
        if remaining > 0:
            shortages.append({"sku": item["sku"], "quantity": remaining})
    if shortages:
        status = "partial" if allocations else "unfulfilled"
    else:
        status = "allocated" if allocations and not errors else "review"
    return {"status": status, "allocations": allocations, "shortages": shortages, "errors": errors}

