            total += 5
    else:
        errors.append("Unknown shipping method")

    coupon = order.get("coupon")
    if coupon:
        if coupon == "SAVE10":
            if total >= 100:
                total *= 0.90
            else:
                errors.append("Coupon requires minimum total of 100")
        elif coupon == "WELCOME":
            if customer.get("previous_orders", 0) == 0:
                total = max(0, total - 15)
            else:
                errors.append("Coupon restricted to first order")
