            errors.append("Insufficient customer credit")
    elif payment_method == "cash":
        if method != "pickup":
            errors.append("Cash requires pickup")
    else:
        errors.append("Unsupported payment method")

    if customer.get("blocked", False):
        errors.append("Customer blocked")
    if order.get("gift", False) and not order.get("gift_message"):
        warnings.append("Gift message missing")

