def classify_http_response(status, method="GET", headers=None, retries=0):
    headers = {key.lower(): value for key, value in (headers or {}).items()}
    method = method.upper()

    if status == 100:
        return "continue"
    elif status == 101:
        return "switch_protocol"
    elif status == 102:
        return "processing"
    elif status == 103:
        return "early_hints"
    elif status == 200:
        if method == "HEAD":
            return "headers_only"
        elif "application/json" in headers.get("content-type", ""):
            return "parse_json"
        elif "text/" in headers.get("content-type", ""):
            return "read_text"
        else:
            return "read_bytes"
    elif status == 201:
        if "location" in headers:
            return "created_with_location"
        return "created"
    elif status == 202:
        if "location" in headers:
            return "poll_location"
        return "accepted"
    elif status == 203:
        return "non_authoritative"
    elif status == 204:
        return "no_content"
    elif status == 205:
        return "reset_content"
    elif status == 206:
        if "content-range" in headers:
