def allocate_shipments(order, warehouses):
    allocations, shortages, errors = [], [], []
    if order.get("status") == "paid":
        if order.get("items"):
            for item in order["items"]:
                try:
                    remaining = int(item["quantity"])
                    weight = Decimal(str(item["unit_weight"]))
                    if remaining <= 0 or not weight.is_finite() or weight <= 0:
                        raise ValueError("Invalid quantity or weight")
                    for warehouse in warehouses:
                        if remaining > 0:
                            if warehouse.get("active"):
                                if order["country"] in warehouse["shipping_countries"]:
                                    for stock in warehouse["inventory"]:
                                        if remaining > 0 and stock["sku"] == item["sku"]:
                                            if not stock.get("quarantined"):
                                                available = max(0, int(stock["units"]) - int(stock["reserved"]))
                                                if available > 0:
                                                    if item.get("requires_cold_chain"):
                                                        if warehouse.get("cold_chain"):
                                                            limit = warehouse["cold_capacity_kg"]
                                                        else:
