                                                    else:
                                                        limit = warehouse["parcel_capacity_kg"]
                                                    capacity = Decimal(str(limit))
                                                    if not capacity.is_finite() or capacity < 0:
                                                        raise ValueError("Invalid shipping capacity")
                                                    units = min(remaining, available, int(capacity / weight))
                                                    if units > 0:
                                                        stock["reserved"] += units
                                                        remaining -= units
                                                        allocations.append({"sku": item["sku"], "warehouse": warehouse["id"], "units": units})
