def calculate_order_total(
    items,
    customer_type="standard",
    coupon_code=None,
    discount_rate=0.0,
    tax_rate=0.0,
    shipping_method="standard",
    destination_country="US",
    free_shipping_threshold=100.0,
    loyalty_points=0,
    redeem_points=False,
    gift_wrap=False,
    expedited_processing=False,
    insurance=False,
    currency="USD",
    exchange_rate=1.0,
    max_discount_rate=0.5,
):
    from decimal import Decimal, ROUND_HALF_UP

    def decimal(value):
        result = Decimal(str(value))
        if not result.is_finite():
            raise ValueError("Numeric values must be finite")
        return result

    def money(value):
        return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    discount_rate = decimal(discount_rate)
    tax_rate = decimal(tax_rate)
    exchange_rate = decimal(exchange_rate)
    max_discount_rate = decimal(max_discount_rate)
    free_shipping_threshold = decimal(free_shipping_threshold)

    if not 0 <= discount_rate <= 1 or not 0 <= max_discount_rate <= 1:
        raise ValueError("Discount rates must be between 0 and 1")
    if tax_rate < 0 or exchange_rate <= 0 or free_shipping_threshold < 0:
        raise ValueError("Invalid tax rate, exchange rate, or shipping threshold")
    if isinstance(loyalty_points, bool) or not isinstance(loyalty_points, int):
        raise ValueError("Loyalty points must be an integer")
    if loyalty_points < 0:
        raise ValueError("Loyalty points cannot be negative")

    customer_discounts = {
        "standard": Decimal("0"),
        "premium": Decimal("0.10"),
        "wholesale": Decimal("0.15"),
    }
    shipping_rates = {
        "standard": Decimal("5.00"),
        "express": Decimal("15.00"),
        "overnight": Decimal("30.00"),
    }
    if customer_type not in customer_discounts:
        raise ValueError("Unknown customer type")
    if shipping_method not in shipping_rates:
        raise ValueError("Unknown shipping method")

    subtotal = Decimal("0")
    eligible_subtotal = Decimal("0")
    taxable_subtotal = Decimal("0")
    taxable_eligible_subtotal = Decimal("0")
    total_weight = Decimal("0")
    quantity_total = 0

    for item in items:
        quantity = item.get("quantity", 1)
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("Item quantity must be a positive integer")
        price = decimal(item["price"])
        weight = decimal(item.get("weight", 0))
        if price < 0 or weight < 0:
            raise ValueError("Item price and weight cannot be negative")

        line_total = money(price * quantity)
        eligible = not item.get("exclude_from_discount", False)
        taxable = item.get("taxable", True)
        subtotal += line_total
        total_weight += weight * quantity
        quantity_total += quantity
        if eligible:
            eligible_subtotal += line_total
        if taxable:
            taxable_subtotal += line_total
            if eligible:
                taxable_eligible_subtotal += line_total

    coupon_discount = Decimal("0")
    free_shipping = False
    if coupon_code:
        coupon = coupon_code.strip().upper()
        if coupon == "SAVE10":
            coupon_discount = Decimal("0.10")
        elif coupon == "SAVE20" and subtotal >= 200:
            coupon_discount = Decimal("0.20")
        elif coupon == "FREESHIP":
            free_shipping = True
        else:
            raise ValueError("Coupon invalid or minimum subtotal unmet")

    combined_rate = min(
        discount_rate + customer_discounts[customer_type] + coupon_discount,
        max_discount_rate,
    )
    discount = money(eligible_subtotal * combined_rate)
    discounted_subtotal = subtotal - discount
    taxable_discount = (
        discount * taxable_eligible_subtotal / eligible_subtotal
        if eligible_subtotal
        else Decimal("0")
    )

    points_used = 0
    points_credit = Decimal("0")
    if redeem_points and discounted_subtotal > 0:
        points_used = min(loyalty_points, int(discounted_subtotal * 100))
        points_credit = Decimal(points_used) / 100

    taxable_amount = taxable_subtotal - taxable_discount
    if discounted_subtotal:
        taxable_amount *= (discounted_subtotal - points_credit) / discounted_subtotal
    tax = money(taxable_amount * tax_rate)

    shipping = Decimal("0")
    fees = Decimal("0")
    if quantity_total:
        shipping = shipping_rates[shipping_method]
        if destination_country.upper() != "US":
            shipping += Decimal("20.00")
        if total_weight > 10:
            shipping += (total_weight - 10) * Decimal("1.50")
        if free_shipping or (
            shipping_method == "standard"
            and discounted_subtotal >= free_shipping_threshold
        ):
            shipping = Decimal("0")
        if gift_wrap:
            fees += Decimal("3.00") * quantity_total
        if expedited_processing:
            fees += Decimal("10.00")
        if insurance:
            fees += max(Decimal("2.00"), money(discounted_subtotal * Decimal("0.01")))

    amounts = {
        "subtotal": subtotal,
        "discount": -discount,
        "points_credit": -points_credit,
        "tax": tax,
        "shipping": money(shipping),
        "fees": fees,
    }
    converted = {key: money(value * exchange_rate) for key, value in amounts.items()}
    return {
        "currency": currency,
        **converted,
        "total": sum(converted.values(), Decimal("0.00")),
        "points_used": points_used,
        "quantity": quantity_total,
    }

