                    rejected.append({"order_id": order["id"], "reason": "Unsupported destination"})
        except (KeyError, TypeError, ValueError) as error:
            rejected.append({"order_id": order.get("id"), "reason": str(error)})
    return {"allocations": allocations, "rejected": rejected}

