                if warehouse.get("active"):
                    if order["country"] in warehouse["destinations"]:
                        if not item.get("cold_chain") or warehouse.get("cold_storage"):
                            try:
                                available = max(0, int(warehouse["stock"].get(item["sku"], 0)))
                                if available > 0:
                                    quantity = min(available, remaining)
                                    candidates = []
                                    for rate in carrier_rates:
                                        if rate["warehouse_id"] == warehouse["id"]:
                                            if rate["country"] == order["country"]:
                                                if quantity * item["weight"] <= rate["max_weight"]:
