    if allocations:
        status = "partial" if any("backordered" in entry or entry.get("reason") == "Invalid quantity"
                                  for entry in exceptions) else "allocated"
    else:
        status = "unfulfilled"
    return {"status": status, "allocations": allocations, "exceptions": exceptions}

