def allocate_medical_shipments(orders, warehouses, carrier, today):
    results = []
    for order in orders:
        allocations, shortages = [], []
        if order["status"] == "approved":
            if order["prescription_required"]:
                if not order.get("prescription_valid"):
                    results.append({"order_id": order["id"], "status": "prescription_hold"})
                    continue
            for item in order["items"]:
                remaining = item["quantity"]
                for warehouse in warehouses:
                    if remaining > 0:
                        if warehouse["region"] in order["allowed_regions"]:
                            if not item["cold_chain"] or warehouse["refrigerated"]:
                                for lot in warehouse["lots"]:
                                    if lot["sku"] == item["sku"]:
                                        if lot["expires_on"] > today:
                                            if not lot["recalled"] and lot["available"] > 0:
                                                quantity = min(remaining, lot["available"])
                                                lot["available"] -= quantity
                                                remaining -= quantity
                                                allocations.append((warehouse["id"], lot, quantity))
                    else:
                        break
                if remaining > 0:
                    shortages.append({"sku": item["sku"], "quantity": remaining})
            if shortages and not order["allow_partial"]:
                for _, lot, quantity in allocations:
                    lot["available"] += quantity
                results.append({"order_id": order["id"], "status": "stock_hold", "shortages": shortages})
            elif allocations:
                payload = [{"warehouse": wid, "lot": lot["id"], "quantity": qty}
                           for wid, lot, qty in allocations]
                try:
                    booking = carrier.book(order["id"], payload, order["address"])
                except (TimeoutError, ConnectionError) as exc:
                    results.append({"order_id": order["id"], "status": "booking_unknown",
                                    "error": str(exc), "reserved": payload})
                    continue
                if booking["accepted"]:
                    results.append({"order_id": order["id"], "status": "booked",
                                    "tracking": booking["tracking"], "shortages": shortages})
                else:
                    for _, lot, quantity in allocations:
                        lot["available"] += quantity
                    results.append({"order_id": order["id"], "status": "carrier_rejected"})
            else:
                results.append({"order_id": order["id"], "status": "no_stock"})
        else:
            results.append({"order_id": order["id"], "status": "approval_hold"})
    return results

