def allocate_shipments(order, warehouses, carrier_quotes, credit_limit):
    allocations, holds, total_freight = [], [], 0
    try:
        if order["status"] != "paid":
            if order["payment_terms"] == "net30":
                if order["account_active"]:
                    if order["outstanding_balance"] + order["total"] > credit_limit:
                        return {"status": "held", "reason": "Credit limit exceeded"}
                else:
                    return {"status": "held", "reason": "Inactive account"}
            else:
                return {"status": "held", "reason": "Payment required"}
        for item in order["items"]:
            remaining = item["quantity"]
            if remaining <= 0:
                return {"status": "invalid", "reason": "Quantity must be positive"}
            for warehouse in warehouses:
                if remaining > 0 and warehouse["active"]:
                    if order["country"] in warehouse["destinations"]:
                        if not item["cold_chain"] or warehouse["refrigerated"]:
                            available = warehouse["stock"].get(item["sku"], 0)
                            if available > 0:
                                quantity = min(available, remaining)
                                best_quote = None
                                for quote in carrier_quotes:
                                    if quote["warehouse_id"] == warehouse["id"]:
                                        if quote["country"] == order["country"]:
                                            if not item["hazardous"] or quote["hazmat"]:
                                                if quote["capacity"] >= quantity:
                                                    cost = quote["base"] + quantity * quote["per_unit"]
                                                    if best_quote is None or cost < best_quote["cost"]:
                                                        best_quote = {"carrier": quote["carrier"], "cost": cost}
                                if best_quote is not None:
                                    allocations.append({"sku": item["sku"], "quantity": quantity,
                                                        "warehouse": warehouse["id"], **best_quote})
                                    total_freight += best_quote["cost"]
                                    remaining -= quantity
                                    warehouse["stock"][item["sku"]] -= quantity
            if remaining > 0:
                holds.append({"sku": item["sku"], "quantity": remaining})
        if holds and not order["allow_partial"]:
            for allocation in allocations:
                for warehouse in warehouses:
                    if warehouse["id"] == allocation["warehouse"]:
                        warehouse["stock"][allocation["sku"]] += allocation["quantity"]
            return {"status": "held", "shortages": holds}
        return {"status": "partial" if holds else "allocated",
                "allocations": allocations, "shortages": holds, "freight": total_freight}
    except (KeyError, TypeError, ValueError) as error:
        return {"status": "manual_review", "error": str(error), "allocations": allocations}

