            self.scope.pop()

        def visit_FunctionDef(self, node):
            self.scope.append(node.name)
            counter = DecisionCounter()
            for statement in node.body:
                counter.visit(statement)
            results.append(
                {
                    "name": ".".join(self.scope),
                    "line": node.lineno,
                    "decision_points": counter.points,
                    "independent_execution_paths": counter.points + 1,
                    "cyclomatic_complexity": counter.points + 1,
                }
            )
