import ast


def rank_function_complexity(source: str, limit: int | None = None) -> list[dict]:
    """Rank functions by cyclomatic complexity: independent execution paths."""
    tree = ast.parse(source)

    class ComplexityVisitor(ast.NodeVisitor):
        def __init__(self):
            self.decision_points = 0

        def visit_FunctionDef(self, node):
            pass

        visit_AsyncFunctionDef = visit_FunctionDef

        def visit_ClassDef(self, node):
            pass

        def visit_Lambda(self, node):
            pass

        def visit_If(self, node):
            self.decision_points += 1
            self.generic_visit(node)

        visit_IfExp = visit_If
        visit_For = visit_If
        visit_AsyncFor = visit_If
        visit_While = visit_If
        visit_ExceptHandler = visit_If
        visit_Assert = visit_If

        def visit_BoolOp(self, node):
            self.decision_points += len(node.values) - 1
            self.generic_visit(node)

        def visit_Compare(self, node):
            self.decision_points += max(0, len(node.ops) - 1)
            self.generic_visit(node)

        def visit_comprehension(self, node):
            self.decision_points += 1 + len(node.ifs)
            self.generic_visit(node)

        def visit_Match(self, node):
            for case in node.cases:
                # Unguarded wildcard/capture case adds no decision.
                if not (
                    isinstance(case.pattern, ast.MatchAs)
                    and case.pattern.pattern is None
                ):
                    self.decision_points += 1
                if case.guard is not None:
                    self.decision_points += 1
            self.generic_visit(node)

        def visit_MatchOr(self, node):
            self.decision_points += len(node.patterns) - 1
            self.generic_visit(node)

    results = []

    class FunctionCollector(ast.NodeVisitor):
        def __init__(self):
            self.scope = []

        def visit_ClassDef(self, node):
            self.scope.append(node.name)
            for statement in node.body:
                self.visit(statement)
            self.scope.pop()

        def visit_FunctionDef(self, node):
            name = ".".join((*self.scope, node.name))
            visitor = ComplexityVisitor()
            for statement in node.body:
                visitor.visit(statement)

            results.append({
                "name": name,
                "line": node.lineno,
                "decision_points": visitor.decision_points,
                "cyclomatic_complexity": visitor.decision_points + 1,
            })

            self.scope.append(node.name)
            for statement in node.body:
                self.visit(statement)
            self.scope.pop()

        visit_AsyncFunctionDef = visit_FunctionDef

    FunctionCollector().visit(tree)
    results.sort(key=lambda item: (-item["cyclomatic_complexity"], item["line"]))

    if limit is not None:
        if limit < 0:
            raise ValueError("limit must be nonnegative")
        return results[:limit]
    return results

