import ast
from pathlib import Path


def find_hard_to_test_functions(source, min_complexity=10, filename="<string>"):
    """Find functions with many independent paths using cyclomatic complexity."""

    class ComplexityVisitor(ast.NodeVisitor):
        def __init__(self):
            self.complexity = 1

        def visit_If(self, node):
            self.complexity += 1
            self.generic_visit(node)

        visit_IfExp = visit_If
        visit_For = visit_If
        visit_AsyncFor = visit_If
        visit_While = visit_If
        visit_ExceptHandler = visit_If
        visit_Assert = visit_If

        def visit_BoolOp(self, node):
            self.complexity += len(node.values) - 1
            self.generic_visit(node)

        def visit_comprehension(self, node):
            self.complexity += 1 + len(node.ifs)
            self.generic_visit(node)

        def visit_Match(self, node):
            # Unguarded wildcard/capture case adds no decision.
            for case in node.cases:
                if case.guard is not None or not (
                    isinstance(case.pattern, ast.MatchAs)
                    and case.pattern.pattern is None
                ):
                    self.complexity += 1
                if case.guard is not None:
                    self.visit(case.guard)
                for statement in case.body:
                    self.visit(statement)

        def visit_FunctionDef(self, node):
            pass

        visit_AsyncFunctionDef = visit_FunctionDef
        visit_ClassDef = visit_FunctionDef
        visit_Lambda = visit_FunctionDef

    class FunctionVisitor(ast.NodeVisitor):
        def __init__(self):
            self.scope = []
            self.results = []

        def visit_ClassDef(self, node):
            self.scope.append(node.name)
            for statement in node.body:
                self.visit(statement)
            self.scope.pop()

        def visit_FunctionDef(self, node):
            self.scope.append(node.name)
            visitor = ComplexityVisitor()
            for statement in node.body:
                visitor.visit(statement)

            if visitor.complexity >= min_complexity:
                self.results.append({
                    "name": ".".join(self.scope),
                    "filename": str(filename),
                    "line": node.lineno,
                    "end_line": node.end_lineno,
                    "cyclomatic_complexity": visitor.complexity,
                })

            for statement in node.body:
                self.visit(statement)
            self.scope.pop()

        visit_AsyncFunctionDef = visit_FunctionDef

    if isinstance(source, Path):
        import tokenize

        filename = str(source)
        with tokenize.open(source) as file:
            source = file.read()

    tree = ast.parse(source, filename=str(filename))
    visitor = FunctionVisitor()
    visitor.visit(tree)
    return sorted(
        visitor.results,
        key=lambda result: (-result["cyclomatic_complexity"], result["line"]),
    )

