def allocate_shipments(order, warehouses, carrier_api):
    shipments, shortages, errors = [], [], []
    if order["status"] == "paid":
        if order["address"].get("postal_code"):
            if order["items"]:
                for item in order["items"]:
                    remaining = item["quantity"]
                    if remaining > 0:
                        for warehouse in warehouses:
                            if remaining > 0:
                                if warehouse["active"]:
                                    if order["address"]["country"] in warehouse["countries"]:
                                        if not item.get("refrigerated") or warehouse["cold_storage"]:
                                            available = max(0, warehouse["stock"].get(item["sku"], 0))
                                            if available > 0:
                                                quantity = min(remaining, available)
                                                offers = []
                                                try:
                                                    rates = carrier_api.quote(
                                                        warehouse["id"], order["address"], item["sku"], quantity
                                                    )
                                                    for rate in rates:
                                                        if rate["capacity"] >= quantity:
                                                            if not item.get("refrigerated") or rate["refrigerated"]:
                                                                if rate["days"] <= order["max_transit_days"]:
                                                                    offers.append(rate)
                                                    if offers:
                                                        chosen = min(offers, key=lambda rate: rate["cost"])
                                                        shipments.append({
                                                            "warehouse": warehouse["id"], "sku": item["sku"],
                                                            "quantity": quantity, "rate": chosen,
                                                        })
                                                        warehouse["stock"][item["sku"]] -= quantity
                                                        remaining -= quantity
                                                except (TimeoutError, ConnectionError) as exc:
                                                    errors.append({"warehouse": warehouse["id"], "error": str(exc)})
                                        else:
                                            errors.append({"warehouse": warehouse["id"], "error": "Cold storage required"})
                        if remaining:
                            shortages.append({"sku": item["sku"], "quantity": remaining})
                    else:
                        errors.append({"sku": item["sku"], "error": "Invalid quantity"})
            else:
                return {"status": "rejected", "error": "Empty order"}
        else:
            return {"status": "rejected", "error": "Missing postal code"}
    else:
        return {"status": "rejected", "error": "Payment required"}
    status = "partial" if shortages or errors else "allocated"
    return {"status": status, "shipments": shipments, "shortages": shortages, "errors": errors}

