                        results.append({"id": order.get("id"), "status": error})
                        continue

                    coupon = order.get("coupon")
                    if coupon:
                        if coupon == "SAVE10":
                            if total >= 100:
                                total *= 0.90
                            else:
                                results.append({
                                    "id": order.get("id"),
                                    "status": "coupon_minimum_not_met",
                                })
                                continue
                        elif coupon == "FREESHIP":
                            if customer.get("country") != "US":
                                results.append({
                                    "id": order.get("id"),
                                    "status": "coupon_region_mismatch",
                                })
                                continue
                        else:
                            results.append({
                                "id": order.get("id"),
                                "status": "invalid_coupon",
                            })
                            continue

                    if order.get("shipping") == "express":
                        shipping = 15 if customer.get("country") == "US" else 40
                    elif total >= 100 or coupon == "FREESHIP":
                        shipping = 0
                    else:
                        shipping = 5 if customer.get("country") == "US" else 20

                    total = round(total + shipping, 2)
                    if order.get("payment_method") == "credit":
                        if customer.get("credit_available", 0) < total:
                            results.append({
                                "id": order.get("id"),
                                "status": "credit_limit_exceeded",
                            })
                            continue
                        customer["credit_available"] -= total
                    elif order.get("payment_method") == "prepaid":
                        if order.get("amount_paid", 0) < total:
                            results.append({
                                "id": order.get("id"),
                                "status": "insufficient_payment",
                            })
                            continue
                    else:
                        results.append({
                            "id": order.get("id"),
                            "status": "unsupported_payment",
                        })
                        continue

                    for sku, quantity in reserved.items():
                        inventory[sku]["stock"] -= quantity
                    results.append({
                        "id": order.get("id"),
