            continue

        customer = customers.get(order.get("customer_id"))
        if customer is None:
            results.append({"id": order["id"], "status": "unknown_customer"})
            continue

        if customer.get("blocked"):
            if not order.get("admin_override"):
                results.append({"id": order["id"], "status": "blocked"})
                continue

        total = 0
        reserved = {}
        backordered = []
        errors = []

        for item in order.get("items", []):
            sku = item.get("sku")
            quantity = item.get("quantity", 0)

            if sku not in inventory:
                errors.append(f"Unknown SKU: {sku}")
            elif not isinstance(quantity, int) or isinstance(quantity, bool):
                errors.append(f"Invalid quantity: {sku}")
            elif quantity <= 0:
                errors.append(f"Invalid quantity: {sku}")
            else:
                product = inventory[sku]
                available = product["stock"] - reserved.get(sku, 0)

                if available >= quantity:
                    reserved[sku] = reserved.get(sku, 0) + quantity
                elif allow_backorders and product.get("backorderable"):
                    reserved[sku] = reserved.get(sku, 0) + max(available, 0)
                    backordered.append(
                        {"sku": sku, "quantity": quantity - max(available, 0)}
                    )
                else:
