                    continue

                price = product["price"]
                if customer.get("tier") == "gold":
                    if quantity >= 10:
                        price *= 0.80
                    else:
                        price *= 0.90
                elif customer.get("tier") == "silver":
                    if quantity >= 10:
                        price *= 0.90
                    elif not product.get("sale"):
                        price *= 0.95

                total += price * quantity

        if errors:
            results.append(
                {"id": order["id"], "status": "rejected", "errors": errors}
            )
            continue

        if not reserved:
            results.append({"id": order["id"], "status": "empty"})
            continue

        coupon = order.get("coupon")
        if coupon:
            if coupon == "SAVE10":
                if total >= 100:
                    total *= 0.90
                else:
                    errors.append("Coupon minimum not met")
            elif coupon == "VIP":
                if customer.get("tier") == "gold":
                    total *= 0.85
                else:
                    errors.append("Coupon requires gold tier")
            else:
                errors.append("Unknown coupon")

        if errors:
            results.append(
                {"id": order["id"], "status": "rejected", "errors": errors}
            )
            continue

        if order.get("shipping") == "express":
            total += 15 if customer.get("tier") == "gold" else 25
        elif total < 75:
            total += 8

        if order.get("payment_method") == "credit":
            if customer.get("credit_limit", 0) < total:
                results.append({"id": order["id"], "status": "credit_declined"})
                continue
            customer["credit_limit"] -= total
        elif order.get("payment_method") == "prepaid":
            if order.get("paid_amount", 0) < total:
                results.append({"id": order["id"], "status": "payment_required"})
                continue
        else:
            results.append({"id": order["id"], "status": "unsupported_payment"})
            continue

        for sku, quantity in reserved.items():
            inventory[sku]["stock"] -= quantity

        results.append(
            {
                "id": order["id"],
                "status": "backordered" if backordered else "ready",
                "total": round(total, 2),
                "backordered": backordered,
            }
        )

    return results

