                                    break
                            else:
                                failures.append(("invalid_quantity", item["sku"]))
                        if not failures:
                            for carrier in carriers:
                                if carrier.supports(order["address"]["country"]):
                                    try:
                                        quote = carrier.quote(order, reservations)
                                        if quote["amount"] <= order["shipping_budget"]:
                                            return {"status": "reserved", "carrier": carrier.name,
