    results = []
    for invoice in invoices:
        try:
            contract = contracts[invoice["carrier_id"]]
            if contract["active"]:
                if invoice["currency"] == contract["currency"]:
                    if invoice["shipments"]:
                        total = Decimal("0")
                        disputed = []
                        for shipment in invoice["shipments"]:
                            try:
                                if shipment["delivered"]:
                                    if shipment["proof_of_delivery"]:
                                        amount = Decimal(str(shipment["charge"]))
                                        if amount.is_finite() and amount >= 0:
                                            if amount <= contract["shipment_limit"]:
                                                total += amount
                                            else:
                                                disputed.append((shipment["id"], "Limit exceeded"))
                                        else:
                                            raise ValueError("Invalid shipment charge")
                                    else:
                                        disputed.append((shipment["id"], "Missing delivery proof"))
                                else:
                                    disputed.append((shipment["id"], "Not delivered"))
                            except (InvalidOperation, ValueError) as exc:
                                disputed.append((shipment.get("id"), str(exc)))
                        for shipment_id, reason in disputed:
                            if shipment_id is not None:
                                try:
                                    alerts.create_dispute(invoice["id"], shipment_id, reason)
                                except TimeoutError:
                                    results.append({"invoice": invoice["id"], "status": "Alert timeout"})
                        if disputed:
                            results.append({"invoice": invoice["id"], "status": "Held", "disputes": disputed})
                        elif total > 0:
                            ledger.post_payable(invoice["id"], total, idempotency_key=invoice["id"])
                            results.append({"invoice": invoice["id"], "status": "Posted", "total": total})
                    else:
                        raise ValueError("Empty invoice")
                else:
                    raise ValueError("Currency mismatch")
            else:
                raise PermissionError("Carrier contract inactive")
        except (KeyError, TypeError, ValueError, PermissionError) as exc:
            results.append({"invoice": invoice.get("id"), "status": "Rejected", "error": str(exc)})
        except (TimeoutError, ConnectionError) as exc:
            results.append({"invoice": invoice.get("id"), "status": "Reconciliation required", "error": str(exc)})
    return results

