from decimal import Decimal, InvalidOperation


def allocate_medical_shipments(orders, warehouses, carrier, cold_chain_required=True):
    allocations, rejected = [], []
    for order in orders:
        reserved, remaining = [], {}
        try:
            if order["payment_status"] == "cleared":
                if order["prescription_verified"]:
                    if order["destination"]["serviceable"]:
                        for line in order["lines"]:
                            quantity = int(line["quantity"])
                            if quantity <= 0:
                                raise ValueError("Quantity must be positive")
                            remaining[line["sku"]] = remaining.get(line["sku"], 0) + quantity
                        for warehouse in warehouses:
                            if warehouse["active"]:
                                if warehouse["region"] == order["destination"]["region"]:
                                    for sku, needed in list(remaining.items()):
                                        for batch in warehouse["inventory"].get(sku, []):
                                            if needed > 0 and batch["days_to_expiry"] > 14:
                                                if not cold_chain_required or batch["refrigerated"]:
                                                    available = max(0, batch["available"])
                                                    taken = min(needed, available)
                                                    if taken:
                                                        batch["available"] -= taken
                                                        reserved.append((batch, taken, sku, warehouse["id"]))
                                                        needed -= taken
                                                        remaining[sku] = needed
                        if any(remaining.values()) or not reserved:
                            raise ValueError("Insufficient eligible inventory")
                        quote = carrier.quote(order["destination"], reserved)
                        cost = Decimal(str(quote["amount"]))
                        if not cost.is_finite() or cost < 0:
                            raise ValueError("Invalid shipping quote")
                        if cost > Decimal(str(order["shipping_budget"])):
                            raise ValueError("Shipping budget exceeded")
                        allocations.append({"order_id": order["id"], "cost": cost, "reservations": reserved})
                    else:
                        rejected.append({"order_id": order["id"], "reason": "Destination unavailable"})
                else:
                    rejected.append({"order_id": order["id"], "reason": "Prescription unverified"})
            else:
                rejected.append({"order_id": order["id"], "reason": "Payment pending"})
        except (KeyError, TypeError, ValueError, InvalidOperation, OSError) as error:
            for batch, quantity, sku, warehouse_id in reversed(reserved):
                batch["available"] += quantity
            rejected.append({"order_id": order.get("id"), "reason": str(error)})
    return {"allocations": allocations, "rejected": rejected}

