def find_most_complex_functions(root=".", limit=20, min_complexity=1):
    """Rank functions by cyclomatic complexity. Nested scopes scored separately."""
    if limit < 0:
        raise ValueError("limit must be nonnegative")

    class ComplexityVisitor(ast.NodeVisitor):
        def __init__(self):
            self.score = 1

        def visit_If(self, node):
            self.score += 1
            self.generic_visit(node)

        visit_For = visit_If
        visit_AsyncFor = visit_If
        visit_While = visit_If
        visit_IfExp = visit_If
