def allocate_medical_shipments(orders, warehouses, carriers, cold_chain_required=True):
    allocations, rejected = [], []
    for order in orders:
        remaining = order["quantity"]
        if remaining <= 0:
            rejected.append((order["id"], "Invalid quantity"))
            continue
        if order["prescription_required"]:
            if order.get("prescription"):
                if order["prescription"]["verified"]:
                    if order["prescription"]["expires_on"] < order["ship_date"]:
                        rejected.append((order["id"], "Expired prescription"))
                        continue
                else:
                    rejected.append((order["id"], "Unverified prescription"))
                    continue
            else:
                rejected.append((order["id"], "Missing prescription"))
                continue
        for warehouse in warehouses:
            if remaining > 0 and warehouse.region == order["region"]:
                try:
                    with warehouse.reservation_transaction() as reservation:
                        lots = reservation.available_lots(order["sku"])
                        for lot in sorted(lots, key=lambda entry: entry.expires_on):
                            if remaining > 0 and lot.expires_on > order["deliver_by"]:
                                if not lot.quarantined:
                                    if not order["refrigerated"] or warehouse.has_cold_storage:
                                        for carrier in carriers:
                                            if carrier.serves(warehouse.postcode, order["postcode"]):
                                                if not order["refrigerated"] or carrier.has_cold_chain:
                                                    if not cold_chain_required or not order["refrigerated"] or carrier.temperature_tracking:
                                                        quantity = min(remaining, lot.available)
                                                        if quantity > 0:
                                                            quote = carrier.quote(order, quantity)
                                                            if quote <= order["remaining_shipping_budget"]:
                                                                reservation.reserve(lot.id, quantity)
                                                                reservation.enqueue_shipment(order["id"], carrier.id, lot.id, quantity, quote)
                                                                reservation.commit()
                                                                allocations.append((order["id"], warehouse.id, lot.id, quantity, quote))
                                                                remaining -= quantity
                                                                order["remaining_shipping_budget"] -= quote
                                                                break
                except (TimeoutError, ConnectionError) as error:
                    rejected.append((order["id"], warehouse.id, str(error)))
                    continue
        if remaining > 0:
            rejected.append((order["id"], "Unallocated quantity", remaining))
    return {"allocations": allocations, "exceptions": rejected}

