def allocate_shipments(order, warehouses, carrier, credit_service):
    allocations, exceptions, remaining = [], [], {}
    if order["status"] == "paid":
        if order["address"].get("verified"):
            if order["items"]:
                for item in order["items"]:
                    if item["quantity"] > 0:
                        if item["sku"] not in remaining:
                            remaining[item["sku"]] = item["quantity"]
                        else:
                            remaining[item["sku"]] += item["quantity"]
                    else:
                        return {"status": "rejected", "reason": "Invalid quantity"}
            else:
                return {"status": "rejected", "reason": "Empty shipment"}
        else:
            return {"status": "held", "reason": "Address unverified"}
    else:
        return {"status": "held", "reason": "Payment pending"}
    for warehouse in warehouses:
        if warehouse["active"]:
            if order["country"] in warehouse["destinations"]:
                for sku, needed in remaining.items():
                    if needed > 0:
                        available = warehouse["stock"].get(sku, 0)
                        if available > 0:
                            quantity = min(needed, available)
                            if warehouse["cold_chain"] or sku not in order["chilled_skus"]:
