        if remaining <= 0:
            rejected.append((request["id"], "Invalid quantity"))
            continue
        for warehouse in warehouses:
            if remaining > 0:
                if warehouse["active"]:
                    if request["region"] in warehouse["service_regions"]:
                        if not cold_chain_required or warehouse["refrigerated"]:
                            for batch in warehouse["batches"]:
                                if batch["sku"] == request["sku"]:
                                    if not batch["recalled"] and batch["days_to_expiry"] > 0:
                                        if batch["days_to_expiry"] >= request["minimum_shelf_days"]:
                                            if batch["available"] > 0:
                                                quantity = min(remaining, batch["available"])
                                                if request["priority"] == "emergency":
                                                    allowed = quantity
                                                else:
                                                    allowed = min(quantity, max(0, batch["available"] - batch["reserve"]))
                                                if allowed > 0:
                                                    batch["available"] -= allowed
                                                    remaining -= allowed
                                                    allocations.append((request["id"], warehouse["id"], batch, allowed))
        if remaining > 0:
            rejected.append((request["id"], f"Unfilled quantity: {remaining}"))
