            if quote["available"]:
                if quote["cost"] <= carrier.cost_limit or cold_chain_required:
                    shipment = carrier.book(quote["id"], idempotency_key=f"{request_id}:{warehouse_id}:{batch['id']}")
                    if shipment["status"] == "confirmed":
                        shipments.append(shipment)
                    elif shipment["status"] == "rejected":
                        batch["available"] += quantity
                        rejected.append((request_id, "Carrier rejected booking"))
