                rejected.append((request_id, "No carrier capacity"))
        except (TimeoutError, ConnectionError):
            rejected.append((request_id, "Carrier unavailable; stock held for reconciliation"))
    return {"shipments": shipments, "exceptions": rejected, "allocated_units": sum(a[3] for a in allocations)}

