def find_high_complexity_functions(source, threshold=10, filename="<string>"):
    """Return functions with McCabe complexity greater than threshold.

    Requires package: mccabe.
    """
    import ast
    from mccabe import PathGraphingAstVisitor

    if threshold < 0:
        raise ValueError("threshold must be nonnegative")

    tree = ast.parse(source, filename=filename)
    function_locations = {
        (node.lineno, node.col_offset)
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    visitor = PathGraphingAstVisitor()
    visitor.preorder(tree, visitor)

    results = []
    for name, graph in visitor.graphs.items():
        if (graph.lineno, graph.column) not in function_locations:
            continue

        complexity = graph.complexity()
        if complexity > threshold:
            results.append(
                {
                    "name": name,
                    "filename": filename,
                    "line": graph.lineno,
                    "complexity": complexity,
                }
            )

    return sorted(results, key=lambda result: (-result["complexity"], result["line"]))

