def handle_command(command, *args, **kwargs):
    """Handle text, numeric, collection, and lookup commands."""
    if not isinstance(command, str):
        raise TypeError("command must be str")

    command = command.strip().lower()

    if command == "help":
        return (
            "help", "upper", "lower", "reverse", "join", "sum",
            "average", "min", "max", "sort", "unique", "count", "get",
        )

    if command in {"upper", "lower", "reverse"}:
        if len(args) != 1:
            raise ValueError(f"{command} requires one argument")
        value = args[0]
        if command == "reverse":
            return value[::-1]
        if not isinstance(value, str):
            raise TypeError(f"{command} requires str")
        return value.upper() if command == "upper" else value.lower()

    if command == "join":
        separator = kwargs.get("separator", " ")
        return separator.join(str(value) for value in args)

    if command in {"sum", "average", "min", "max"}:
        if not args and command != "sum":
            raise ValueError(f"{command} requires at least one number")
        if command == "sum":
            return sum(args)
        if command == "average":
            return sum(args) / len(args)
        if command == "min":
            return min(args)
        return max(args)

    if command == "sort":
        return sorted(
            args,
            key=kwargs.get("key"),
            reverse=kwargs.get("reverse", False),
        )

    if command == "unique":
        result = []
        for value in args:
            if value not in result:
                result.append(value)
        return result

    if command == "count":
        if len(args) != 2:
            raise ValueError("count requires collection and value")
        collection, target = args
        return sum(1 for value in collection if value == target)

    if command == "get":
        if len(args) != 2:
            raise ValueError("get requires mapping and key")
        mapping, key = args
        return mapping.get(key, kwargs.get("default"))

    raise ValueError(f"Unknown command: {command!r}")

