def handle_event(event, state):
    """Handle common event cases; return updated state and result."""
    if not isinstance(event, dict):
        raise TypeError("event must be dict")
    if not isinstance(state, dict):
        raise TypeError("state must be dict")

    updated = state.copy()
    action = event.get("action")
    key = event.get("key")

    if action == "set":
        if "key" not in event or "value" not in event:
            raise ValueError("set requires key and value")
        updated[key] = event["value"]
        result = updated[key]

    elif action == "get":
        result = updated.get(key, event.get("default"))

    elif action == "delete":
        result = updated.pop(key, event.get("default"))

    elif action == "increment":
        amount = event.get("amount", 1)
        current = updated.get(key, 0)
        if (
            isinstance(current, bool)
            or isinstance(amount, bool)
            or not isinstance(current, (int, float))
            or not isinstance(amount, (int, float))
        ):
            raise TypeError("increment requires numeric value and amount")
        updated[key] = current + amount
        result = updated[key]

    elif action == "append":
        current = updated.get(key, [])
        if not isinstance(current, list):
            raise TypeError("append requires list value")
        if "value" not in event:
            raise ValueError("append requires value")
        updated[key] = [*current, event["value"]]
        result = updated[key].copy()

    elif action == "toggle":
        current = updated.get(key, False)
        if not isinstance(current, bool):
            raise TypeError("toggle requires boolean value")
        updated[key] = not current
        result = updated[key]

    elif action == "merge":
        values = event.get("values")
        if not isinstance(values, dict):
            raise TypeError("merge requires dict values")
        updated.update(values)
        result = len(values)

    elif action == "contains":
        result = key in updated

    elif action == "keys":
        result = list(updated)

    elif action == "clear":
        result = len(updated)
        updated.clear()

    elif action == "count":
        result = len(updated)

    elif action == "noop":
        result = None

    else:
        raise ValueError(f"Unknown action: {action!r}")

    return updated, result

