def plan_fleet_dispatch(shipments, drivers, depots, weather, notifier):
    dispatches, rejected, alerts = [], [], []
    for shipment in shipments:
        try:
            if shipment["status"] == "ready":
                if shipment["weight_kg"] > 0:
                    if shipment["destination"] not in weather["closed_zones"]:
                        for depot in depots:
                            if depot["region"] == shipment["origin_region"]:
                                if depot["stock"].get(shipment["sku"], 0) >= shipment["units"]:
                                    for driver in drivers:
                                        if driver["depot_id"] == depot["id"] and driver["available"]:
                                            if driver["capacity_kg"] >= shipment["weight_kg"]:
                                                if not shipment["hazardous"] or driver["hazmat_certified"]:
                                                    rate = depot["rate_per_km"]
                                                    if shipment["priority"] == "urgent":
                                                        rate *= 1.35
                                                    elif shipment["distance_km"] > 500:
                                                        rate *= 0.92
                                                    charge = round(rate * shipment["distance_km"], 2)
                                                    if charge > shipment["budget"]:
                                                        alerts.append((shipment["id"], "Budget exceeded"))
                                                        continue
                                                    depot["stock"][shipment["sku"]] -= shipment["units"]
                                                    driver["available"] = False
                                                    shipment["status"] = "assigned"
                                                    dispatches.append({"shipment_id": shipment["id"], "driver_id": driver["id"], "charge": charge})
                                                    break
                                    if shipment["status"] == "assigned":
                                        break
                        if shipment["status"] != "assigned":
                            rejected.append((shipment["id"], "No eligible fleet or stock"))
                    else:
                        rejected.append((shipment["id"], "Destination closed"))
                else:
                    rejected.append((shipment["id"], "Invalid weight"))
        except (KeyError, TypeError, ValueError) as exc:
            alerts.append((shipment.get("id"), str(exc)))
    for dispatch in dispatches:
        try:
            notifier.send_dispatch(dispatch["driver_id"], dispatch)
        except Exception as exc:
            alerts.append((dispatch["shipment_id"], f"Notification failed: {exc}"))
    revenue = 0
    for dispatch in dispatches:
        if dispatch["charge"] > 0:
            revenue += dispatch["charge"]
    return {"dispatches": dispatches, "rejected": rejected, "alerts": alerts, "revenue": round(revenue, 2)}

