    paths = [root] if root.is_file() else root.rglob("*.py")
    excluded = {".git", ".venv", "venv", "__pycache__", "site-packages"}
    hotspots = []

    for path in sorted(paths):
        if excluded.intersection(path.parts):
            continue
        try:
            with tokenize.open(path) as source_file:
                source = source_file.read()
            tree = ast.parse(source, filename=str(path))
        except (OSError, SyntaxError, UnicodeError):
            continue

        lines = source.splitlines()
        for node in ast.walk(tree):
            if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue

            visitor = ComplexityVisitor()
            for statement in node.body:
                visitor.visit(statement)

            if visitor.complexity < min_complexity:
                continue

            end_line = node.end_lineno or node.lineno
            function_source = "\n".join(lines[node.lineno - 1:end_line]).upper()
            markers = {
                marker: function_source.count(marker)
                for marker in ("TODO", "FIXME", "HACK", "XXX")
            }
            hotspots.append({
                "path": str(path),
                "function": node.name,
                "line": node.lineno,
                "end_line": end_line,
                "lines": end_line - node.lineno + 1,
                "complexity": visitor.complexity,
                "debt_markers": markers,
            })

    hotspots.sort(
        key=lambda item: (
            -item["complexity"],
            -sum(item["debt_markers"].values()),
            -item["lines"],
            item["path"],
            item["line"],
        )
    )
    return hotspots if limit is None else hotspots[:max(0, limit)]

