                            if item.category in policy.covered_categories:
                                if item.value > policy.min_item_value:
                                    adjustment_factor = adjuster.get_adjustment_factor(item.category)
                                    adjusted_value = item.value * adjustment_factor
                                    claim.payout += adjusted_value
                                    claim.adjustments.append((item.category, adjusted_value))
                                else:
                                    claim.rejections.append((item.category, 'Below minimum item value'))
