                        total_damage = sum(item.value for item in claim.items if item.damaged)
                        if total_damage < policy.minimum_claim_value:
                            return {'status': 'denied', 'reason': 'Claim value below minimum threshold'}
                        else:
                            for item in claim.items:
                                if item.damaged:
                                    item.approved = True
                                    item.adjustment = item.value * policy.deductible_rate
