                    adjustments.append(('make_discount', discount))
                else:
                    final_amount = claim.damage_amount
            else:
                final_amount = claim.damage_amount
        else:
            final_amount = claim.damage_amount
    elif claim.policy_type == 'home':
        if claim.damage_type == 'flood':
            if claim.claim_history.count('flood') == 0:
                if claim.home.square_footage > 2000:
                    discount = claim.damage_amount * 0.15
                    final_amount = claim.damage_amount - discount
                    adjustments.append(('size_discount', discount))
                else:
                    final_amount = claim.damage_amount
            else:
                final_amount = claim.damage_amount * 1.10
                adjustments.append(('repeated_flood_surcharge', final_amount - claim.damage_amount))
        else:
            final_amount = claim.damage_amount
    else:
        return {'error': 'Unsupported policy type'}

    if claim.document_attachments:
