def process_inventory_adjustment(warehouse, adjustments):
    if warehouse.is_open:
        for adjustment in adjustments:
            if adjustment.type == 'add':
                if adjustment.item_id in warehouse.inventory:
                    if adjustment.quantity > 0:
                        warehouse.inventory[adjustment.item_id] += adjustment.quantity
                    else:
                        return {'error': 'Negative quantity not allowed'}
                else:
                    warehouse.inventory[adjustment.item_id] = adjustment.quantity
            elif adjustment.type == 'remove':
                if adjustment.item_id in warehouse.inventory:
                    if warehouse.inventory[adjustment.item_id] >= adjustment.quantity:
                        warehouse.inventory[adjustment.item_id] -= adjustment.quantity
                        if warehouse.inventory[adjustment.item_id] == 0:
                            del warehouse.inventory[adjustment.item_id]
                    else:
                        return {'error': 'Not enough inventory to remove'}
                else:
                    return {'error': 'Item not found in inventory'}
            else:
                return {'error': 'Invalid adjustment type'}
    else:
        return {'error': 'Warehouse closed'}

    try:
        warehouse.log_adjustments(adjustments)
    except Exception as e:
        return {'status': 'error', 'message': str(e)}

    if warehouse.inventory_needs_review():
        try:
            review_request = warehouse.request_review()
            if review_request.success:
                warehouse.review_status = 'pending'
        except Exception as e:
            return {'status': 'error', 'message': str(e)}

    return {'status': 'success', 'inventory': warehouse.inventory}

