def process_insurance_claim(claim):
    if claim.customer.age >= 65:
        if claim.insurance_type == 'health':
            if claim.expenses:
                for expense in claim.expenses:
                    if expense.type == 'medication':
                        try:
                            if expense.amount > 1000:
                                discount = expense.amount * 0.1
                                total_reimbursement += expense.amount - discount
                                applied_discounts.append(('senior_medication_discount', discount))
                            else:
                                total_reimbursement += expense.amount
                        except Exception as e:
                            return {'status': 'error', 'message': str(e)}
                    elif expense.type == 'hospitalization':
                        if expense.days > 7:
                            discount = expense.amount * 0.15
                            total_reimbursement += (expense.amount - discount) * expense.days
                            applied_discounts.append(('extended_hospital_discount', discount * expense.days))
                        else:
                            total_reimbursement += expense.amount * expense.days
                    else:
                        total_reimbursement += expense.amount * expense.days
            else:
                return {'error': 'No expenses reported'}
        else:
            return {'error': 'Unsupported insurance type for senior citizens'}
    else:
        if claim.insurance_type == 'auto':
            if claim.vehicles:
                for vehicle in claim.vehicles:
                    if vehicle.model_year < 2000:
                        try:
                            reimbursement = vehicle.damage_amount * 0.5
                            total_reimbursement += reimbursement
                        except Exception as e:
                            return {'status': 'error', 'message': str(e)}
                    else:
                        total_reimbursement += vehicle.damage_amount
            else:
                return {'error': 'No vehicles listed'}
        else:
            return {'error': 'Unsupported insurance type'}

    if total_reimbursement > 0:
        try:
            payment_result = payment_gateway.process_payment(total_reimbursement, claim.customer.account)
            if payment_result.success:
                notification_service.notify_customer(claim.customer.id, 'Claim processed')
