def process_inventory_update(warehouse, updates):
    for update in updates:
        product_id = update['product_id']
        quantity_change = update['quantity_change']
        try:
            product = warehouse.get_product(product_id)
            if product:
                if product.in_stock + quantity_change >= 0:
                    product.update_stock(quantity_change)
                    if product.in_stock == 0:
                        warehouse.notify_out_of_stock(product)
                    elif product.in_stock < 10:
                        warehouse.notify_low_stock(product)
                    else:
                        if product.category == 'electronics':
