def process_employee_benefits(employee, benefits_config):
    if employee.is_full_time:
        if employee.years_of_service > 5:
            if employee.department == 'Engineering':
                for benefit in benefits_config['Engineering']:
                    if benefit['type'] == 'bonus':
                        try:
                            bonus_amount = calculate_bonus(employee.salary, benefit['percentage'])
                            if bonus_amount > 0:
                                employee.benefits.append({'type': 'bonus', 'amount': bonus_amount})
                        except ValueError as e:
                            log_error(f"Error calculating bonus: {str(e)}")
                    elif benefit['type'] == 'stock_options':
                        if employee.stock_options_granted < benefit['max_options']:
                            stock_options = min(benefit['options'], benefit['max_options'] - employee.stock_options_granted)
                            employee.stock_options_granted += stock_options
                            employee.benefits.append({'type': 'stock_options', 'amount': stock_options})
                if employee.benefits:
                    send_notification(employee.email, 'Benefits processed')
            elif employee.department == 'Marketing':
                for benefit in benefits_config['Marketing']:
                    if benefit['type'] == 'travel_reimbursement':
                        if benefit['threshold'] <= employee.travel_expenses:
                            reimbursement = min(benefit['reimbursement_rate'] * employee.travel_expenses, benefit['max_reimbursement'])
                            employee.benefits.append({'type': 'travel_reimbursement', 'amount': reimbursement})
                            employee.travel_expenses -= reimbursement
                if employee.benefits:
                    send_notification(employee.email, 'Benefits processed')
        else:
            if employee.years_of_service > 2:
                for benefit in benefits_config['General']:
                    if benefit['type'] == 'health_insurance':
                        if benefit['coverage'] not in employee.current_coverage:
                            employee.current_coverage.append(benefit['coverage'])
                            employee.benefits.append({'type': 'health_insurance', 'coverage': benefit['coverage']})
                if employee.benefits:
                    send_notification(employee.email, 'Benefits processed')
    else:
        if employee.contract_type == 'freelance':
            for benefit in benefits_config['Freelance']:
                if benefit['type'] == 'project_bonus':
                    if benefit['min_projects'] <= employee.completed_projects:
                        project_bonus = benefit['bonus_per_project'] * employee.completed_projects
                        employee.benefits.append({'type': 'project_bonus', 'amount': project_bonus})
                if employee.benefits:
                    send_notification(employee.email, 'Benefits processed')

