def process_insurance_claim(claim):
    if claim.policy_type == 'health':
        if claim.patient.age > 65:
            if claim.hospitalization_days > 10:
                for procedure in claim.procedures:
                    if procedure.code in HIGH_RISK_CODES:
                        try:
                            adjustment = adjust_for_risk_factor(procedure, claim.patient.risk_factors)
                            procedure.final_cost -= adjustment
                        except ValueError as e:
                            log_error(f"Error adjusting cost for procedure {procedure.code}: {str(e)}")
                            procedure.final_cost = 0
                    total_cost += procedure.final_cost
            else:
                total_cost = sum(procedure.final_cost for procedure in claim.procedures)
        else:
            if claim.has_pre_existing_conditions:
                for condition in claim.pre_existing_conditions:
                    if condition.severity == 'severe':
                        total_cost = 0
                        break
                else:
                    total_cost = sum(procedure.final_cost for procedure in claim.procedures)
            else:
                total_cost = sum(procedure.final_cost for procedure in claim.procedures)
    elif claim.policy_type == 'auto':
        if claim.accident_location == 'urban':
            if claim.vehicle.year < 2010:
                for damage in claim.damages:
                    if damage.type == 'structural':
                        total_cost += damage.estimate * 0.8
                    else:
                        total_cost += damage.estimate
            else:
                for damage in claim.damages:
                    if damage.type == 'structural':
                        total_cost += damage.estimate * 0.9
                    else:
                        total_cost += damage.estimate
        else:
            for damage in claim.damages:
                total_cost += damage.estimate
    else:
        return {'error': 'Unsupported policy type'}

    if total_cost > 0:
        try:
            payment = insurance_provider.process_payment(total_cost, claim.policy_id)
            if payment.status == 'success':
                return {'status': 'success', 'total_cost': total_cost}
            else:
                return {'status': 'failed', 'error': payment.message}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}
    else:
        return {'error': 'No cost to process'}

