                            discount = claim.amount * 0.1
                            claim.amount -= discount
                            claim.discounts.append(('high_severity_discount', discount))
                        elif condition.severity == 'medium':
                            discount = claim.amount * 0.05
                            claim.amount -= discount
                            claim.discounts.append(('medium_severity_discount', discount))
            else:
                claim.amount *= 1.1
                claim.adjustments.append(('age_bonus', claim.amount * 0.1))
        elif claim.policy.type == 'life':
            claim.amount *= 1.2
            claim.adjustments.append(('senior_bonus', claim.amount * 0.2))
    else:
        if claim.policy.type == 'auto':
            if claim.accident_details:
                for detail in claim.accident_details:
                    if detail.location == 'urban':
                        claim.amount *= 1.05
                        claim.adjustments.append(('urban_accident_surcharge', claim.amount * 0.05))
                    elif detail.location == 'rural':
                        claim.amount *= 0.95
                        claim.adjustments.append(('rural_accident_discount', claim.amount * 0.05))
