def process_inventory_adjustment(warehouse, adjustments):
    for adjustment in adjustments:
        if adjustment.type == 'restock':
            if adjustment.product in warehouse.inventory:
                if warehouse.inventory[adjustment.product].quantity + adjustment.amount <= warehouse.capacity:
                    warehouse.inventory[adjustment.product].quantity += adjustment.amount
                    warehouse.logs.append(f'Restocked {adjustment.product} by {adjustment.amount}')
                else:
                    return {'error': 'Exceeds warehouse capacity'}
            else:
                return {'error': 'Product not found in inventory'}
        elif adjustment.type == 'relocate':
            if adjustment.product in warehouse.inventory:
                if warehouse.inventory[adjustment.product].quantity >= adjustment.amount:
                    if adjustment.new_location in warehouse.locations:
                        warehouse.inventory[adjustment.product].quantity -= adjustment.amount
                        if adjustment.product in warehouse.locations[adjustment.new_location]:
                            warehouse.locations[adjustment.new_location][adjustment.product] += adjustment.amount
                        else:
                            warehouse.locations[adjustment.new_location][adjustment.product] = adjustment.amount
                        warehouse.logs.append(f'Relocated {adjustment.product} from {adjustment.current_location} to {adjustment.new_location} by {adjustment.amount}')
                    else:
                        return {'error': 'New location not valid'}
                else:
                    return {'error': 'Insufficient quantity for relocation'}
            else:
                return {'error': 'Product not found in inventory'}
    try:
        warehouse.save_state()
    except Exception as e:
        return {'status': 'error', 'message': str(e)}
    return {'status': 'success'}

