def process_insurance_claim(claim, customer, policy):
    if claim.is_valid:
        if policy.type == 'comprehensive':
            if customer.age > 65:
                if claim.amount > 5000:
                    try:
                        for item in claim.items:
                            if item.category == 'medical':
                                if item.cost > 1000:
                                    discount = item.cost * 0.3
                                    claim.payout += item.cost - discount
                                    policy.discounts.append(('elderly_medical', discount))
                                else:
                                    claim.payout += item.cost
                            elif item.category == 'rehabilitation':
                                if item.duration > 7:
                                    discount = item.cost * 0.25
                                    claim.payout += (item.cost - discount) * item.duration
                                    policy.discounts.append(('long_rehab', discount * item.duration))
                                else:
                                    claim.payout += item.cost * item.duration
                            else:
                                claim.payout += item.cost * item.duration
                    except Exception as e:
                        return {'status': 'error', 'message': str(e)}
