                            total_reimbursement = injury.treatment_cost - discount
                            claim.discounts.append(('critical_injury_discount', discount))
                        else:
                            total_reimbursement = injury.treatment_cost
                        if claim.customer.has_preexisting_conditions:
                            if 'heart_disease' in claim.customer.preexisting_conditions:
                                additional_discount = total_reimbursement * 0.1
                                total_reimbursement -= additional_discount
                                claim.discounts.append(('heart_disease_discount', additional_discount))
                        claim.reimbursements.append(total_reimbursement)
