                claim.status = 'payment_failed'
                return {'status': 'failed', 'error': payment_result.error}
        except Exception as e:
            claim.status = 'error'
            return {'status': 'error', 'message': str(e)}
    else:
        claim.status = 'covered_by_policy'
        return {'status': 'covered', 'message': 'Claim fully covered by policy'}

