def find_hotspots_with_high_branching_complexity(codebase):
    import ast
    from collections import defaultdict

    hotspots = defaultdict(int)

    def visit_branches(node):
        if isinstance(node, (ast.If, ast.For, ast.While, ast.With, ast.Try)):
            hotspots[node.lineno] += 1

    class ComplexityVisitor(ast.NodeVisitor):
        def visit(self, node):
            visit_branches(node)
            super().visit(node)

    for root, _, files in os.walk(codebase):
        for file in files:
            if file.endswith('.py'):
                filepath = os.path.join(root, file)
                with open(filepath, 'r', encoding='utf-8') as f:
                    tree = ast.parse(f.read(), filename=filepath)
                    visitor = ComplexityVisitor()
                    visitor.visit(tree)

    return {file: branches for file, branches in hotspots.items() if branches > 5}

