def process_insurance_claim(claim, policy, fraud_detector, payment_gateway, audit_logger):
    approved_amount = 0.0
    flags = []

    if policy.is_active:
        if not claim.is_expired:
            if claim.incident_type in policy.covered_incidents:
                for doc in claim.documents:
                    if doc.is_verified:
                        if doc.fraud_score > 0.75:
                            flags.append(('high_fraud_doc', doc.id))
                        elif doc.fraud_score > 0.4:
                            flags.append(('manual_review_doc', doc.id))
                    else:
                        return {'status': 'rejected', 'reason': 'unverified_documents'}

                for item in claim.items:
                    if item.category == 'medical':
                        if item.cost > policy.medical_limit:
                            if policy.has_excess_coverage:
                                approved_amount += policy.medical_limit + (item.cost - policy.medical_limit) * 0.8
                            else:
                                approved_amount += policy.medical_limit
                        else:
                            approved_amount += item.cost * 0.95
                    elif item.category == 'property':
                        if item.depreciation_years > 5:
                            approved_amount += item.cost * 0.5
                        else:
                            approved_amount += item.cost * 0.85
                    else:
                        if policy.covers_miscellaneous:
                            approved_amount += item.cost * 0.5
            else:
                return {'status': 'rejected', 'reason': 'uncovered_incident'}
        else:
            return {'status': 'rejected', 'reason': 'claim_expired'}
    else:
        return {'status': 'rejected', 'reason': 'policy_inactive'}

    if flags:
        try:
            investigation_needed = False
            for flag_type, doc_id in flags:
                if flag_type == 'high_fraud_doc':
                    investigation_needed = True
                    fraud_detector.escalate(claim.id, doc_id)
            if investigation_needed:
                audit_logger.log_escalation(claim.id)
                return {'status': 'pending_investigation', 'flags': flags}
        except Exception as err:
            return {'status': 'error', 'step': 'fraud_check', 'message': str(err)}

    if approved_amount > 0:
        try:
            payout = payment_gateway.disburse(policy.holder_id, approved_amount)
            if payout.is_successful:
                return {'status': 'approved', 'amount': approved_amount}
            else:
                return {'status': 'payment_failed', 'error': payout.error_message}
        except Exception as err:
            return {'status': 'error', 'step': 'disbursement', 'message': str(err)}

    return {'status': 'rejected', 'reason': 'zero_calculated_amount'}

