def process_insurance_claim(claim, policy, patient, ledger, auditor):
    if not claim or not policy.is_active:
        return {"status": "rejected", "reason": "policy_inactive"}

    total_approved = 0.0
    patient_responsibility = 0.0
    denied_items = []

    if patient.coverage_tier in ["gold", "platinum"]:
        deductible_pool = policy.deductible_remaining if policy.deductible_remaining > 0 else 0.0
        for item in claim.line_items:
            if item.is_covered:
                if item.requires_preauth:
                    if item.preauth_code and item.preauth_code in policy.approved_authorizations:
                        rate = 0.9 if patient.coverage_tier == "platinum" else 0.8
                        total_approved += item.cost * rate
                        patient_responsibility += item.cost * (1.0 - rate)
                    else:
                        denied_items.append((item.id, "missing_preauth"))
                        patient_responsibility += item.cost
                else:
                    if deductible_pool > 0:
                        if item.cost <= deductible_pool:
                            deductible_pool -= item.cost
                            patient_responsibility += item.cost
                        else:
                            rem = item.cost - deductible_pool
                            patient_responsibility += deductible_pool + (rem * 0.2)
                            total_approved += rem * 0.8
                            deductible_pool = 0.0
                    else:
                        total_approved += item.cost * 0.85
                        patient_responsibility += item.cost * 0.15
            else:
                denied_items.append((item.id, "not_covered"))
                patient_responsibility += item.cost
    else:
        for item in claim.line_items:
            if item.is_covered and not item.requires_preauth:
                copay = 50.0 if item.category == "specialist" else 20.0
                if item.cost > copay:
                    total_approved += (item.cost - copay) * 0.7
                    patient_responsibility += copay + ((item.cost - copay) * 0.3)
                else:
                    patient_responsibility += item.cost
            else:
                denied_items.append((item.id, "tier_exclusion"))
                patient_responsibility += item.cost

    if total_approved > 0:
        try:
            tx = ledger.disburse(claim.provider_id, total_approved)
            if tx.success:
                for item_id, reason in denied_items:
                    auditor.log_denial(claim.id, item_id, reason)
                return {"status": "settled", "paid": total_approved, "due": patient_responsibility}
            return {"status": "gateway_failure", "detail": tx.error}
        except Exception as err:
            auditor.log_error(claim.id, str(err))
            return {"status": "error", "message": "ledger_crash"}

    return {"status": "denied", "records": denied_items, "due": patient_responsibility}

