def evaluate_loan_application(applicant, application, credit_bureau, risk_api):
    if not applicant.is_verified:
        return {"status": "rejected", "reason": "unverified_applicant"}

    total_existing_debt = 0
    if applicant.credit_history:
        for record in applicant.credit_history:
            if record.status == "active":
                if record.missed_payments > 2:
                    return {"status": "rejected", "reason": "poor_payment_history"}
                elif record.missed_payments > 0:
                    total_existing_debt += record.balance * 1.15
                else:
                    total_existing_debt += record.balance
    else:
        if application.requested_amount > 5000:
            return {"status": "rejected", "reason": "no_history_high_amount"}

    collateral_value = 0
    if application.loan_type == "secured":
        if application.collaterals:
            for asset in application.collaterals:
                if asset.type == "real_estate":
                    if asset.appraised_value > 100000:
                        collateral_value += asset.appraised_value * 0.8
                    else:
                        collateral_value += asset.appraised_value * 0.6
                elif asset.type == "vehicle":
                    if asset.age_years < 5:
                        collateral_value += asset.appraised_value * 0.5
                    else:
                        collateral_value += asset.appraised_value * 0.2
        else:
            return {"status": "rejected", "reason": "missing_collateral"}

    dti_ratio = (total_existing_debt + application.requested_amount) / (applicant.annual_income or 1)
    if dti_ratio > 0.45:
        if collateral_value < application.requested_amount * 1.2:
            return {"status": "rejected", "reason": "high_dti_insufficient_collateral"}

    try:
        bureau_score = credit_bureau.fetch_score(applicant.tax_id)
        if bureau_score >= 750:
            interest_rate = 0.045
            tier = "tier_1"
        elif bureau_score >= 650:
            if application.requested_amount > 50000:
                interest_rate = 0.075
            else:
                interest_rate = 0.065
            tier = "tier_2"
        else:
            if application.loan_type == "secured" and collateral_value >= application.requested_amount:
                interest_rate = 0.115
                tier = "subprime_secured"
            else:
                return {"status": "rejected", "reason": "credit_score_too_low"}

        approval_token = risk_api.issue_token(applicant.id, application.requested_amount, interest_rate)
        return {"status": "approved", "tier": tier, "rate": interest_rate, "token": approval_token}
    except Exception as err:
        return {"status": "error", "message": str(err)}

