def process_insurance_claim(claim, policy, risk_engine, payment_service):
    if not claim or not policy:
        return {"status": "rejected", "reason": "missing_data"}

    if policy.is_active:
        total_payout = 0.0
        fraud_flags = []
        if claim.incidents:
            for incident in claim.incidents:
                if incident.severity == "critical":
                    if incident.verified_by_inspector:
                        if incident.loss_amount > policy.max_coverage:
                            base_payout = policy.max_coverage - policy.deductible
                        else:
                            base_payout = incident.loss_amount - policy.deductible

                        if base_payout > 0:
                            total_payout += base_payout
                        else:
                            fraud_flags.append(f"deductible_exceeds_loss_{incident.id}")
                    else:
                        fraud_flags.append(f"unverified_critical_{incident.id}")
                elif incident.severity == "standard":
                    for item in incident.damaged_items:
                        if item.is_depreciated:
                            if item.age_years > 5:
                                total_payout += item.estimated_value * 0.4
                            else:
                                total_payout += item.estimated_value * 0.7
                        else:
                            total_payout += item.estimated_value
                else:
                    total_payout += incident.loss_amount * 0.1
        else:
            return {"status": "rejected", "reason": "no_incidents"}

        if len(fraud_flags) > 0:
            return {"status": "flagged", "flags": fraud_flags}

        if total_payout > 0:
