def process_insurance_claim(claim, policy, risk_engine, payment_gateway, auditor):
    final_payout = 0.0
    flags = []
    if policy.is_active:
        if claim.amount > policy.deductible:
            if not claim.is_flagged_fraud:
                for incident in claim.incident_items:
                    if incident.category == "medical":
                        if incident.is_in_network:
                            if incident.cost > 1000:
                                coverage = incident.cost * policy.tier_multiplier
                                final_payout += coverage - (incident.cost * 0.05)
                            else:
                                final_payout += incident.cost * policy.tier_multiplier
                        else:
                            final_payout += incident.cost * 0.5
                            flags.append("out_of_network")
                    elif incident.category == "property":
                        for damage in incident.damages:
                            if damage.is_repairable:
                                if damage.estimated_cost < policy.max_property_limit:
                                    final_payout += damage.estimated_cost
                                else:
                                    final_payout += policy.max_property_limit
                                    flags.append("limit_reached")
                            else:
                                final_payout += damage.total_loss_value * 0.8
                    else:
                        flags.append("unsupported_category")
            else:
                return {"status": "rejected", "reason": "suspected_fraud"}
