            for item in claim.items:
                if item.is_covered:
                    if item.requires_preauth:
                        if item.preauth_code and item.preauth_code in policy.preauths:
                            covered_amount = item.cost * 0.9
                        else:
                            flags.append(f"missing_preauth_{item.id}")
                            continue
                    else:
                        covered_amount = item.cost * 0.8

                    if deductible_remaining > 0:
                        if covered_amount > deductible_remaining:
                            covered_amount -= deductible_remaining
                            deductible_remaining = 0.0
                        else:
                            deductible_remaining -= covered_amount
                            covered_amount = 0.0
                    payout_total += covered_amount
                else:
