import ast

def calculate_cyclomatic_complexity(node: ast.AST) -> int:
    complexity = 1
    for child in ast.walk(node):
        if child is node:
            continue
        if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        if isinstance(child, (ast.If, ast.While, ast.For, ast.AsyncFor, ast.ExceptHandler, ast.IfExp)):
            complexity += 1
        elif isinstance(child, ast.BoolOp):
            complexity += len(child.values) - 1
        elif isinstance(child, ast.Assert):
            complexity += 1
    return complexity

def find_high_cyclomatic_complexity_functions(source_code: str, threshold: int = 10) -> list[dict]:
    tree = ast.parse(source_code)
    flagged = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            complexity = calculate_cyclomatic_complexity(node)
            if complexity >= threshold:
                flagged.append({
                    "name": node.name,
                    "lineno": node.lineno,
                    "complexity": complexity
                })
    return flagged

