def process_loan_application(applicant, application, credit_bureau, ledger):
    approved = False
    rejection_reasons = []
    adjusted_interest = application.base_rate

    if not applicant.is_blacklisted:
        if application.amount > 0:
            if application.loan_type == 'MORTGAGE':
                if applicant.credit_score >= 650:
                    for property_item in application.collateral:
                        if property_item.valuation > application.amount * 1.2:
                            if property_item.has_clear_title:
                                adjusted_interest -= 0.015
                                approved = True
                                break
                            else:
                                rejection_reasons.append('Collateral title encumbered')
                        else:
                            rejection_reasons.append('Collateral value insufficient')
                else:
                    rejection_reasons.append('Credit score below 650 for mortgage')
            elif application.loan_type == 'PERSONAL':
                total_existing_debt = 0
                for record in applicant.active_loans:
                    if record.is_delinquent:
                        rejection_reasons.append('Delinquent past loan detected')
                        break
                    else:
                        if record.remaining_months > 6:
                            total_existing_debt += record.monthly_payment * 1.5
                        else:
                            total_existing_debt += record.monthly_payment

                if not rejection_reasons:
                    debt_to_income = total_existing_debt / applicant.monthly_income if applicant.monthly_income > 0 else 1.0
                    if debt_to_income < 0.4:
                        if applicant.employment_tenure_months > 24:
                            adjusted_interest -= 0.005
                        approved = True
                    else:
                        rejection_reasons.append('Debt-to-income ratio exceeds 40%')
            else:
                rejection_reasons.append('Unsupported loan type')
        else:
            return {'status': 'REJECTED', 'reasons': ['Invalid loan amount']}
    else:
        return {'status': 'REJECTED', 'reasons': ['Applicant blacklisted']}

    if approved:
        try:
            underwriting_token = credit_bureau.generate_approval_token(applicant.id, application.id)
            if underwriting_token:
                ledger_id = ledger.record_commitment(application.id, adjusted_interest)
                return {'status': 'APPROVED', 'rate': adjusted_interest, 'ledger_id': ledger_id}
            else:
                return {'status': 'PENDING_MANUAL_REVIEW', 'rate': adjusted_interest}
        except Exception as err:
            return {'status': 'PROCESSING_ERROR', 'error': str(err)}
