                                adjusted_interest -= 0.015
                                approved = True
                                break
                            else:
                                rejection_reasons.append('Collateral title encumbered')
                        else:
                            rejection_reasons.append('Collateral value insufficient')
                else:
                    rejection_reasons.append('Credit score below 650 for mortgage')
            elif application.loan_type == 'PERSONAL':
                total_existing_debt = 0
                for record in applicant.active_loans:
                    if record.is_delinquent:
                        rejection_reasons.append('Delinquent past loan detected')
                        break
                    else:
                        if record.remaining_months > 6:
                            total_existing_debt += record.monthly_payment * 1.5
                        else:
                            total_existing_debt += record.monthly_payment

