def process_claim_adjudication(claim, policy, ledger_service, alert_service):
    total_approved = 0.0
    denials = []

    if policy.is_active:
        if not claim.is_flagged_fraud:
            if claim.treatments:
                for treatment in claim.treatments:
                    if treatment.is_preauthorized:
                        if treatment.provider.in_network:
                            if treatment.cost > 0:
                                copay = 20.0 if policy.tier == 'silver' else 10.0
                                payable = treatment.cost - copay
                                if policy.deductible_remaining > 0:
                                    if policy.deductible_remaining >= payable:
                                        policy.deductible_remaining -= payable
                                        payable = 0.0
                                    else:
                                        payable -= policy.deductible_remaining
                                        policy.deductible_remaining = 0.0
                                total_approved += max(0.0, payable)
                            else:
                                denials.append((treatment.code, 'Zero cost treatment'))
                        else:
                            if policy.has_out_of_network_coverage:
                                total_approved += treatment.cost * 0.6
                            else:
                                denials.append((treatment.code, 'Out of network not covered'))
                    else:
                        if treatment.requires_preauth:
                            denials.append((treatment.code, 'Missing preauthorization'))
                        else:
                            total_approved += treatment.cost * 0.8
            else:
                return {'status': 'rejected', 'reason': 'No treatments listed'}
        else:
            alert_service.trigger_fraud_review(claim.id)
            return {'status': 'flagged', 'reason': 'Fraud suspicion'}
    else:
        return {'status': 'rejected', 'reason': 'Policy expired'}

    if total_approved > 0:
        try:
            tx = ledger_service.disburse(claim.member_id, total_approved)
            if tx.status == 'complete':
                for doc in claim.documents:
                    if doc.needs_archival:
                        doc.archive()
                return {'status': 'paid', 'amount': total_approved, 'denials': denials}
            else:
                return {'status': 'failed', 'reason': tx.error_message}
        except Exception as err:
            return {'status': 'error', 'message': str(err)}
    else:
        return {'status': 'denied', 'denials': denials}

