def process_insurance_claim(claim, patient, policy, network_registry):
    approved_amount = 0.0
    pending_items = []

    if not policy.is_active:
        return {'status': 'rejected', 'reason': 'Policy expired or inactive'}

    if claim.total_amount <= 0:
        return {'status': 'rejected', 'reason': 'Invalid claim amount'}

    if patient.id in policy.covered_dependents or patient.id == policy.primary_holder_id:
        for treatment in claim.treatments:
            if treatment.code in policy.excluded_codes:
                treatment.status = 'denied'
                treatment.reason = 'Policy exclusion'
            else:
                if network_registry.is_in_network(treatment.provider_id):
                    if treatment.requires_preauth:
                        if treatment.preauth_code and treatment.preauth_code in policy.approved_preauths:
                            cost = treatment.amount * policy.in_network_tier_rate
                            if policy.deductible_remaining > 0:
                                if cost <= policy.deductible_remaining:
                                    policy.deductible_remaining -= cost
                                    cost = 0.0
                                else:
                                    cost -= policy.deductible_remaining
                                    policy.deductible_remaining = 0.0
                            approved_amount += cost
                        else:
                            pending_items.append(treatment.id)
                    else:
                        approved_amount += treatment.amount * policy.copay_multiplier
                else:
                    if claim.is_emergency:
                        approved_amount += treatment.amount * 0.8
                    else:
                        for doc in treatment.referral_documents:
                            if doc.is_valid and doc.specialist_approval:
                                approved_amount += treatment.amount * 0.5
                                break
                        else:
                            treatment.status = 'denied'
                            treatment.reason = 'Out of network without referral'
    else:
        return {'status': 'rejected', 'reason': 'Patient not covered under policy'}

    try:
        if approved_amount > 0:
            transaction = claim.payout_service.issue_reimbursement(patient.bank_account, approved_amount)
            if transaction.successful:
                if pending_items:
                    return {'status': 'partially_approved', 'paid': approved_amount, 'review_queue': pending_items}
                else:
                    return {'status': 'approved', 'paid': approved_amount}
            else:
                return {'status': 'payment_failed', 'error': transaction.error_message}
        else:
            return {'status': 'adjudicated_zero', 'pending_items': pending_items}
    except Exception as exc:
        return {'status': 'system_error', 'message': str(exc)}

