                            if item.in_network:
                                if item.cost > policy.copay_limit:
                                    adjusted = (item.cost - policy.copay_limit) * 0.85
                                    settlement_total += adjusted
                                    audit_events.append(('copay_deducted', adjusted))
                                else:
                                    settlement_total += item.cost * 0.90
                            else:
                                settlement_total += item.cost * 0.50
                        elif item.category == 'property':
                            if item.depreciation_years > 5:
                                settlement_total += item.cost * 0.40
                            else:
                                settlement_total += item.cost * 0.75
                    else:
                        audit_events.append(('item_denied', item.id))
            else:
