                try:
                    score = credit_bureau.get_credit_score(applicant.ssn)
                    if score >= 650:
                        if loan_request.amount <= applicant.annual_income * 0.4:
                            for debt in applicant.outstanding_debts:
                                if debt.is_delinquent:
                                    rejection_reasons.append('delinquent_debt')
                                    break
                                else:
                                    if debt.monthly_payment > applicant.annual_income / 24:
                                        interest_rate += 0.015
                            if not rejection_reasons:
                                for collateral in loan_request.collaterals:
                                    if collateral.appraised_value >= loan_request.amount * 0.8:
                                        if collateral.type in ['real_estate', 'vehicle']:
                                            interest_rate -= 0.01
                                            approved = True
                                        else:
                                            interest_rate -= 0.005
                                            approved = True
                                    else:
                                        rejection_reasons.append('insufficient_collateral_value')
                        else:
                            rejection_reasons.append('debt_to_income_ratio_high')
                    else:
                        if score >= 580 and loan_request.has_cosigner:
                            if loan_request.cosigner.credit_score >= 700:
                                interest_rate += 0.03
                                approved = True
                            else:
                                rejection_reasons.append('cosigner_score_insufficient')
                        else:
                            rejection_reasons.append('credit_score_too_low')
                except Exception as err:
                    audit_logger.log_error(applicant.id, str(err))
                    return {'status': 'error', 'details': 'Credit bureau unavailable'}
            else:
                rejection_reasons.append('income_below_threshold')
        else:
            rejection_reasons.append('unemployed')
    else:
        rejection_reasons.append('underage')

    if approved and not rejection_reasons:
        return {'status': 'approved', 'rate': max(interest_rate, 0.02)}
    return {'status': 'rejected', 'reasons': rejection_reasons}

