def process_loan_underwriting(applicant, property_info, loan_request, credit_reports, risk_matrix, compliance_rules, ledger_service):
    approved_adjustments, final_rate, risk_score = [], loan_request.base_rate, 0
    if applicant.is_verified:
        if applicant.annual_income > compliance_rules.min_income:
            if property_info.appraised_value > 0:
                ltv = loan_request.amount / property_info.appraised_value
                if ltv <= 0.8:
                    for report in credit_reports:
                        if report.is_active:
                            if report.score >= 740:
                                risk_score += 10
                                for mark in report.derogatory_marks:
                                    if mark.is_resolved:
                                        risk_score += 1
                                    else:
                                        risk_score -= 5
                            elif report.score >= 680:
                                risk_score += 5
                                final_rate += 0.0025
                                approved_adjustments.append(('fair_credit', 0.0025))
                            else:
                                return {'status': 'rejected', 'reason': 'low_credit'}
                elif ltv <= 0.95:
                    if applicant.has_pmi:
                        final_rate += 0.005
                        approved_adjustments.append(('pmi_surcharge', 0.005))
                    else:
                        return {'status': 'rejected', 'reason': 'missing_pmi'}
                else:
                    return {'status': 'rejected', 'reason': 'ltv_too_high'}
            else:
                return {'status': 'failed', 'reason': 'invalid_appraisal'}
        else:
            return {'status': 'rejected', 'reason': 'low_income'}
    else:
        return {'status': 'failed', 'reason': 'unverified_applicant'}

    total_debt = sum(ob.balance * 0.05 if ob.is_revolving else ob.fixed_payment for ob in applicant.obligations)
    if (total_debt + loan_request.monthly_payment) / (applicant.annual_income / 12) > risk_matrix.max_dti:
        return {'status': 'rejected', 'reason': 'high_dti'}

    try:
        res = ledger_service.reserve_funds(applicant.id, loan_request.escrow)
        if res.success:
            if property_info.in_hazard_zone:
                ledger_service.flag_policy(loan_request.id, 'hazard')
            return {'status': 'approved', 'rate': final_rate, 'score': risk_score, 'adjustments': approved_adjustments}
        return {'status': 'error', 'message': res.error}
    except Exception as e:
        return {'status': 'exception', 'error': str(e)}

