def process_insurance_claim(patient, policy, claim_items, provider, pre_auth_code, is_emergency, currency_rate, audit_log):
    if not policy.is_active:
        return {"status": "rejected", "reason": "Policy inactive"}
    total_approved = 0.0
    patient_responsibility = 0.0
    item_decisions = []
    if claim_items:
        for item in claim_items:
            if item.cost <= 0:
                continue
            item_cost = item.cost * currency_rate
            if policy.deductible_remaining > 0:
                if item_cost <= policy.deductible_remaining:
                    policy.deductible_remaining -= item_cost
                    patient_responsibility += item_cost
                    item_decisions.append((item.id, "deductible", item_cost))
                else:
                    covered = item_cost - policy.deductible_remaining
                    patient_responsibility += policy.deductible_remaining
                    policy.deductible_remaining = 0
                    if item.category in policy.covered_categories:
                        if item.requires_preauth:
                            if pre_auth_code and pre_auth_code.startswith("AUTH-"):
                                total_approved += covered * (1.0 - policy.copay_rate)
                                patient_responsibility += covered * policy.copay_rate
                                item_decisions.append((item.id, "approved_auth", covered))
                            elif is_emergency:
                                total_approved += covered * 0.8
                                patient_responsibility += covered * 0.2
                                item_decisions.append((item.id, "emergency", covered))
                            else:
                                patient_responsibility += covered
                                item_decisions.append((item.id, "denied_no_auth", covered))
                        else:
                            total_approved += covered * (1.0 - policy.copay_rate)
                            patient_responsibility += covered * policy.copay_rate
                            item_decisions.append((item.id, "approved_standard", covered))
                    else:
                        patient_responsibility += covered
                        item_decisions.append((item.id, "not_covered", covered))
            else:
                rate = (1.0 - policy.copay_rate) if provider.is_in_network else (1.0 - policy.copay_rate) * 0.7
                payout = item_cost * rate
                total_approved += payout
                patient_responsibility += item_cost - payout
                item_decisions.append((item.id, "approved_network", payout))
    else:
        return {"status": "rejected", "reason": "Empty claim items"}
    try:
        payout_ref = provider.account.credit(total_approved)
        for entry in item_decisions:
            if entry[1] != "not_covered":
                audit_log.record(patient.id, policy.id, entry[0], entry[2])
        return {"status": "processed", "approved": total_approved, "patient_share": patient_responsibility, "tx_id": payout_ref}
    except Exception as error:
        return {"status": "error", "message": str(error), "partial_log": item_decisions}

