                    collateral_val = 0.0
                    for item in loan_request.collaterals:
                        if collateral_registry.is_valid(item.id):
                            if item.appraisal_value > 5000:
                                collateral_val += item.appraisal_value * 0.75
                                adjustments.append(('haircut_25', item.id))
                            else:
                                collateral_val += item.appraisal_value * 0.50
                        else:
