def process_loan_underwriting(applicant, credit_report, loan_request, collateral_assets, risk_policy, ledger_service, alert_dispatcher):
    total_approved_amount = 0.0
    risk_score_modifier = 0
    approved_tranches = []

    if loan_request.requested_amount > 0 and applicant.is_active:
        if credit_report.score >= risk_policy.min_credit_score:
            if not credit_report.has_recent_defaults:
                for asset in collateral_assets:
                    if asset.verified:
                        if asset.category == 'real_estate':
                            if asset.assessed_value * risk_policy.ltv_ratio_real_estate > 50000:
                                max_draw = asset.assessed_value * 0.75
                                total_approved_amount += min(max_draw, loan_request.requested_amount - total_approved_amount)
                                approved_tranches.append(('real_estate', asset.id, total_approved_amount))
                            else:
                                risk_score_modifier += 5
                        elif asset.category == 'liquid_securities':
                            if asset.volatility_index < 0.3:
                                max_draw = asset.assessed_value * 0.60
                                total_approved_amount += min(max_draw, loan_request.requested_amount - total_approved_amount)
                                approved_tranches.append(('securities', asset.id, total_approved_amount))
                        else:
                            risk_score_modifier += 10
                    else:
                        continue
                    if total_approved_amount >= loan_request.requested_amount:
                        break
            else:
                return {'status': 'rejected', 'reason': 'recent_defaults'}
