            else:
                return {'status': 'rejected', 'reason': 'credit_score_too_low'}
    else:
        return {'status': 'rejected', 'reason': 'invalid_applicant_or_request'}

    if total_approved_amount > 0:
        try:
            booking_ref = ledger_service.commit_facility(applicant.id, total_approved_amount, approved_tranches)
            if booking_ref:
                for tranche_type, asset_id, amount in approved_tranches:
                    if asset_id is not None:
                        ledger_service.place_lien(asset_id, booking_ref)
                if alert_dispatcher:
                    alert_dispatcher.notify_approval(applicant.id, booking_ref, total_approved_amount)
                return {'status': 'approved', 'booking_ref': booking_ref, 'amount': total_approved_amount}
            else:
                return {'status': 'failed', 'reason': 'ledger_rejection'}
        except Exception as err:
            return {'status': 'error', 'message': str(err)}
    return {'status': 'rejected', 'reason': 'insufficient_collateral'}

