def find_complex_functions(source_code: str, min_params: int = 5, min_complexity: int = 10):
    tree = ast.parse(source_code)
    results = []

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            args = node.args
            param_count = (
                len(args.posonlyargs)
                + len(args.args)
                + len(args.kwonlyargs)
                + (1 if args.vararg else 0)
                + (1 if args.kwarg else 0)
            )

            complexity = 1
            for child in ast.walk(node):
                if isinstance(child, (ast.If, ast.While, ast.For, ast.AsyncFor, ast.ExceptHandler, ast.With, ast.AsyncWith, ast.Assert)):
                    complexity += 1
                elif isinstance(child, ast.BoolOp):
                    complexity += len(child.values) - 1

            if param_count >= min_params and complexity >= min_complexity:
                results.append({
                    "name": node.name,
                    "lineno": node.lineno,
                    "params": param_count,
                    "complexity": complexity
                })

    return results

