def process_complex_transaction(
    user_id,
    account_type,
    base_amount,
    currency,
    target_currency,
    user_tier,
    risk_score,
    is_promo_eligible,
    override_limits,
    tax_rate,
    country_code,
    exchange_matrix,
    audit_log,
    batch_mode=False
):
    if base_amount <= 0:
        raise ValueError("Base amount must be positive")

    if currency != target_currency and (currency, target_currency) not in exchange_matrix:
        raise ValueError("Unsupported currency pair")

    rate = 1.0 if currency == target_currency else exchange_matrix[(currency, target_currency)]
    converted_amount = base_amount * rate

    tier_multipliers = {"bronze": 1.0, "silver": 0.95, "gold": 0.85, "platinum": 0.70}
    discount = tier_multipliers.get(user_tier.lower(), 1.0)

    fee_percentage = 0.03
    if account_type == "corporate":
        fee_percentage = 0.015 if converted_amount > 50000 else 0.02
    elif account_type == "individual":
        if is_promo_eligible and converted_amount < 1000:
            fee_percentage = 0.01
        elif user_tier in ("gold", "platinum"):
            fee_percentage = 0.018

    base_fee = converted_amount * fee_percentage * discount

    risk_penalty = 0.0
    if risk_score > 75:
        if not override_limits:
            if risk_score > 90:
                raise PermissionError("Risk score exceeds maximum limit")
            risk_penalty = converted_amount * 0.05
        else:
            risk_penalty = converted_amount * 0.02
    elif 50 < risk_score <= 75:
        risk_penalty = 15.0

    applicable_tax = (converted_amount + base_fee) * tax_rate
    if country_code in ("US", "CA"):
        if applicable_tax > 500:
            applicable_tax *= 0.98
    elif country_code in ("EU", "GB"):
        applicable_tax += 2.50

    total_cost = converted_amount + base_fee + risk_penalty + applicable_tax

    allocation = {}
    remaining_balance = total_cost
    steps = [0.4, 0.3, 0.2, 0.1]
    for idx, ratio in enumerate(steps):
        part = round(total_cost * ratio, 2)
        if idx == len(steps) - 1:
            part = round(remaining_balance, 2)
        allocation[f"bucket_{idx + 1}"] = part
        remaining_balance -= part

    status = "flagged" if risk_score > 60 and not override_limits else "approved"
    if batch_mode:
        status += "_queued"

    record = {
        "user_id": user_id,
        "status": status,
        "original_amount": base_amount,
        "converted_amount": converted_amount,
        "total_cost": total_cost,
        "fees": {"base": base_fee, "risk": risk_penalty, "tax": applicable_tax},
        "allocations": allocation
    }

    if audit_log is not None and hasattr(audit_log, "append"):
        audit_log.append(record)

    return record

