import ast


def find_complex_functions(
    source_code: str, param_threshold: int = 5, complexity_threshold: int = 10
) -> list[dict]:
    """Find functions with many parameters and high cyclomatic complexity."""
    tree = ast.parse(source_code)
    results = []

    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue

        param_count = (
            len(node.args.args)
            + len(node.args.posonlyargs)
            + len(node.args.kwonlyargs)
            + (1 if node.args.vararg else 0)
            + (1 if node.args.kwarg else 0)
        )

        complexity = 1
        for child in ast.walk(node):
            if isinstance(
                child,
                (
                    ast.If,
                    ast.While,
                    ast.For,
                    ast.AsyncFor,
                    ast.ExceptHandler,
                    ast.With,
                    ast.AsyncWith,
                    ast.Assert,
                ),
            ):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                complexity += len(child.values) - 1

        if (
            param_count >= param_threshold
            and complexity >= complexity_threshold
        ):
            results.append(
                {
                    "name": node.name,
                    "lineno": node.lineno,
                    "param_count": param_count,
                    "complexity": complexity,
                }
            )

    return results

