                                                bin.available_stock -= item.requested_quantity
                                                allocation_plan[warehouse.id].append({
                                                    'bin_id': bin.id,
                                                    'sku': item.sku,
                                                    'qty': item.requested_quantity
                                                })
                                                reservation_service.confirm(lock.token)
                                                item_allocated = True
                                                break
                                            else:
                                                continue
                                        except Exception as err:
                                            reservation_service.log_failure(bin.id, str(err))
