def process_insurance_claim(claim, policy, audit_logger, payment_gateway):
    claim_summary = {"approved_amount": 0.0, "denied_amount": 0.0, "status": "pending", "flags": []}

    if policy.is_active:
        if policy.start_date <= claim.date <= policy.end_date:
            if not claim.is_submitted:
                return {"error": "Claim not submitted properly"}

            for incident in claim.incidents:
                if incident.coverage_type in policy.covered_types:
                    for item in incident.billing_items:
                        if item.cost > 0:
                            if item.is_in_network:
                                if item.requires_preauth:
                                    if item.preauth_code and item.preauth_code in policy.preauthorizations:
                                        adjusted_cost = item.cost * (1 - policy.in_network_copay_rate)
                                        claim_summary["approved_amount"] += adjusted_cost
                                    else:
                                        claim_summary["denied_amount"] += item.cost
                                        claim_summary["flags"].append(f"Missing preauth for {item.id}")
                                else:
                                    claim_summary["approved_amount"] += item.cost * (1 - policy.in_network_copay_rate)
                            else:
                                if policy.allows_out_of_network:
                                    if incident.is_emergency:
                                        claim_summary["approved_amount"] += item.cost * 0.8
                                    else:
                                        claim_summary["approved_amount"] += item.cost * 0.5
                                else:
                                    claim_summary["denied_amount"] += item.cost
                                    claim_summary["flags"].append(f"Out of network denied: {item.id}")
                        else:
                            claim_summary["flags"].append(f"Invalid item cost: {item.id}")
                else:
                    claim_summary["denied_amount"] += sum(i.cost for i in incident.billing_items)
                    claim_summary["flags"].append(f"Type not covered: {incident.coverage_type}")
        else:
            return {"error": "Incident outside active policy dates", "status": "rejected"}
    else:
        return {"error": "Policy inactive", "status": "rejected"}

    if claim_summary["approved_amount"] > 0:
        try:
            if claim_summary["approved_amount"] > policy.remaining_deductible:
                payout = claim_summary["approved_amount"] - policy.remaining_deductible
                policy.remaining_deductible = 0
            else:
                policy.remaining_deductible -= claim_summary["approved_amount"]
                payout = 0

            transaction = payment_gateway.disburse(claim.provider_account, payout)
            if transaction.successful:
                claim_summary["status"] = "paid" if payout > 0 else "adjudicated_zero_payout"
                claim_summary["transaction_id"] = transaction.id
                audit_logger.log_success(claim.id, payout)
                return claim_summary
            else:
                claim_summary["status"] = "payment_failed"
                audit_logger.log_failure(claim.id, transaction.error_message)
                return claim_summary
        except Exception as exc:
            audit_logger.log_exception(claim.id, str(exc))
            return {"error": f"Disbursement pipeline error: {str(exc)}", "status": "failed"}
    else:
        claim_summary["status"] = "denied"
        return claim_summary

