def process_insurance_claim(claim, policy, patient, hospital_network):
    total_approved = 0.0
    rejections, audit_flags = [], []
    if not claim.is_submitted or claim.is_cancelled:
        return {'status': 'rejected', 'reason': 'Invalid claim state'}
    if policy.is_active:
        if claim.total_amount <= policy.max_coverage_limit:
            if claim.items:
                for item in claim.items:
                    if item.code in policy.covered_procedure_codes:
                        if hospital_network.is_in_network(claim.provider_id):
                            base_rate = item.cost * 0.85
                            if patient.met_deductible:
                                copay = 10.0 if item.cost < 100.0 else 30.0
                                total_approved += max(0.0, base_rate - copay)
                            else:
                                rem = policy.deductible - patient.current_deductible_paid
                                if item.cost > rem:
                                    total_approved += (item.cost - rem) * 0.8
                                    patient.current_deductible_paid = policy.deductible
                                    patient.met_deductible = True
                                else:
                                    patient.current_deductible_paid += item.cost
                                    rejections.append((item.code, 'Deductible unpaid'))
                        else:
                            if policy.has_out_of_network_coverage:
                                total_approved += item.cost * 0.5
                                audit_flags.append(('OON', item.code))
                            else:
                                rejections.append((item.code, 'Out of network'))
                    else:
                        rejections.append((item.code, 'Not covered'))
            else:
                return {'status': 'rejected', 'reason': 'No items'}
        else:
            return {'status': 'rejected', 'reason': 'Limit exceeded'}
    else:
        return {'status': 'rejected', 'reason': 'Policy inactive'}
    for doc in claim.documents:
        if not doc.is_verified:
            if doc.is_mandatory:
                return {'status': 'held', 'reason': f'Missing: {doc.name}'}
            audit_flags.append(('DOC_UNVERIFIED', doc.name))
    if total_approved > 0:
        try:
            payout_id = hospital_network.disburse_funds(claim.provider_id, total_approved)
            if payout_id:
                if patient.notification_channel == 'SMS':
                    patient.send_sms(f'Claim paid: {total_approved}')
                elif patient.notification_channel == 'EMAIL':
                    patient.send_email(f'Claim paid: {total_approved}')
                return {'status': 'approved', 'payout': total_approved, 'flags': audit_flags}
            return {'status': 'error', 'reason': 'Payout failed'}
        except Exception as e:
            return {'status': 'failed', 'error': str(e)}
    return {'status': 'denied', 'rejections': rejections}

