def calculate_freight_shipment_quote(shipment, carrier_pool, customs_rules, pricing_matrix):
    quote_results = []
    base_rate = 0.0
    surcharges = {}

    if shipment.is_international:
        if shipment.customs_declaration:
            if shipment.customs_declaration.declared_value > 50000:
                for item in shipment.manifest:
                    if item.is_hazardous:
                        if item.hazard_class in [1, 2, 7]:
                            return {'error': 'Prohibited dangerous goods for standard international route'}
                        else:
                            base_rate += item.weight_kg * pricing_matrix['hazardous_base']
                            surcharges['hazmat_handling'] = surcharges.get('hazmat_handling', 0) + 150.0
                    else:
                        if item.requires_refrigeration:
                            base_rate += item.weight_kg * pricing_matrix['reefer_base']
                            surcharges['cold_chain'] = surcharges.get('cold_chain', 0) + 75.0
                        else:
                            base_rate += item.weight_kg * pricing_matrix['standard_base']
            else:
                for item in shipment.manifest:
                    if item.weight_kg > 1000:
                        base_rate += item.weight_kg * pricing_matrix['heavy_freight']
                    else:
                        base_rate += item.weight_kg * pricing_matrix['standard_base']
        else:
            return {'error': 'Missing customs declaration'}
    else:
        for item in shipment.manifest:
            if item.is_oversized:
                base_rate += item.volume_cbm * pricing_matrix['volume_base']
            else:
                base_rate += item.weight_kg * pricing_matrix['domestic_base']

    for carrier in carrier_pool:
        if carrier.is_active:
            if carrier.supports_region(shipment.destination_region):
                final_carrier_rate = base_rate * carrier.contract_multiplier
                for charge_type, amount in surcharges.items():
                    if charge_type in carrier.waived_surcharges:
                        continue
                    final_carrier_rate += amount
                try:
                    capacity = carrier.query_capacity(shipment.pickup_date)
                    if capacity >= shipment.total_weight_kg:
                        quote_results.append({
                            'carrier_id': carrier.id,
                            'quoted_price': round(final_carrier_rate, 2),
                            'transit_days': carrier.estimate_transit_days(shipment.origin, shipment.destination)
                        })
                except Exception as err:
                    quote_results.append({'carrier_id': carrier.id, 'error': str(err)})

    if not quote_results:
        return {'error': 'No eligible carriers found'}
    return {'status': 'success', 'quotes': quote_results}

