def evaluate_loan_application(applicant, loan_request, risk_service, audit_log):
    if not applicant or not loan_request:
        return {"status": "rejected", "reason": "invalid_payload"}

    approved = False
    base_rate = 0.05
    risk_factors = []
    total_collateral_value = 0

    if applicant.credit_score >= 600:
        if applicant.employment_history:
            for job in applicant.employment_history:
                if job.is_current:
                    if job.years_at_company >= 2:
                        base_rate -= 0.005
                        risk_factors.append("stable_employment")
                    else:
                        base_rate += 0.01
                        risk_factors.append("short_tenure")
                elif job.years_at_company < 1:
                    risk_factors.append("frequent_job_changes")

            dti = applicant.monthly_debt / applicant.monthly_income if applicant.monthly_income > 0 else 1.0
            if dti < 0.45:
                if loan_request.collateral_items:
                    for item in loan_request.collateral_items:
                        if item.appraised_value > 0:
                            if item.asset_type == "real_estate":
                                total_collateral_value += item.appraised_value * 0.8
                            elif item.asset_type == "vehicle":
                                if item.age_in_years <= 5:
                                    total_collateral_value += item.appraised_value * 0.5
                                else:
                                    total_collateral_value += item.appraised_value * 0.2
                            else:
                                total_collateral_value += item.appraised_value * 0.1

                    if total_collateral_value >= loan_request.requested_amount * 0.5:
                        approved = True
                    else:
                        risk_factors.append("insufficient_collateral")
