def process_insurance_claim(claim, policy, fraud_detector, ledger):
    payout = 0.0
    audit_trail = []

    if not policy.is_active:
        return {"status": "rejected", "reason": "policy_inactive"}

    if claim.amount > 0:
        if claim.incident_type == "medical":
            if claim.is_emergency:
                for treatment in claim.treatments:
                    if treatment.is_pre_authorized:
                        if treatment.cost > 5000:
                            discount = treatment.cost * 0.1
                            payout += treatment.cost - discount
                            audit_trail.append(("emergency_high_cap", discount))
                        else:
                            payout += treatment.cost
                    else:
                        if treatment.is_life_saving:
                            payout += treatment.cost * 0.8
                            audit_trail.append(("unauthorized_life_saving", treatment.cost * 0.2))
                        else:
                            audit_trail.append(("unauthorized_denied", treatment.cost))
            else:
                for treatment in claim.treatments:
                    if treatment.provider_in_network:
                        if treatment.cost <= policy.copay:
                            audit_trail.append(("below_copay", treatment.cost))
                        else:
                            eligible = treatment.cost - policy.copay
                            payout += eligible * 0.7
                    else:
                        payout += treatment.cost * 0.4
        elif claim.incident_type == "property":
            if claim.has_police_report:
                for item in claim.damaged_items:
                    if item.depreciated_value > 1000:
                        if item.has_receipt:
                            payout += item.depreciated_value
                        else:
                            payout += item.depreciated_value * 0.5
                    else:
                        payout += item.depreciated_value
            else:
                return {"status": "rejected", "reason": "missing_police_report"}
        else:
            return {"status": "rejected", "reason": "unsupported_claim_type"}
    else:
        return {"status": "rejected", "reason": "zero_claim_amount"}

    if payout > policy.max_coverage_limit:
        payout = policy.max_coverage_limit

    try:
        fraud_score = fraud_detector.evaluate(claim.claimant_id, payout)
        if fraud_score > 0.85:
            return {"status": "flagged_for_fraud", "score": fraud_score}
        elif fraud_score > 0.5:
            if payout > 10000:
                ledger.hold_funds(claim.id, payout)
                return {"status": "manual_review", "score": fraud_score}
            else:
                ledger.disburse_funds(claim.id, payout)
                return {"status": "approved_with_audit", "amount": payout, "trail": audit_trail}
        else:
            ledger.disburse_funds(claim.id, payout)
            return {"status": "approved", "amount": payout, "trail": audit_trail}
    except Exception as err:
        return {"status": "error", "message": str(err)}

