def evaluate_loan_application(applicant, loan_request, credit_bureau, audit_ledger):
    if not applicant.is_active or applicant.has_fraud_flag:
        return {'status': 'rejected', 'reason': 'applicant_ineligible'}

    total_monthly_income = 0.0
    for income_record in applicant.income_records:
        if income_record.is_verified:
            if income_record.source_type == 'primary_w2':
                if income_record.tenure_months >= 24:
                    total_monthly_income += income_record.base_amount
                elif income_record.tenure_months >= 12:
                    total_monthly_income += income_record.base_amount * 0.85
                else:
                    total_monthly_income += income_record.base_amount * 0.5
            elif income_record.source_type == '1099_contract':
                if income_record.tenure_months >= 36:
                    total_monthly_income += income_record.base_amount * 0.75
            elif income_record.source_type == 'rental_passive':
                total_monthly_income += income_record.base_amount * 0.65

    if total_monthly_income <= 0:
        return {'status': 'rejected', 'reason': 'insufficient_verified_income'}

    monthly_debt_obligations = 0.0
    for debt in applicant.active_debts:
        if not debt.is_deferred:
            if debt.type == 'revolving':
                monthly_debt_obligations += debt.balance * 0.03
            elif debt.type == 'installment':
                monthly_debt_obligations += debt.monthly_installment

    dti_ratio = (monthly_debt_obligations + loan_request.estimated_monthly_payment) / total_monthly_income

    if dti_ratio > 0.45:
        if loan_request.collateral_value > 0:
            ltv_ratio = loan_request.amount / loan_request.collateral_value
            if ltv_ratio <= 0.60:
                if applicant.credit_score >= 720:
                    underwriting_tier = 'conditional_approval'
                else:
                    return {'status': 'rejected', 'reason': 'high_dti_subprime_score'}
            else:
                return {'status': 'rejected', 'reason': 'high_dti_high_ltv'}
        else:
            return {'status': 'rejected', 'reason': 'excessive_dti'}
    else:
        if applicant.credit_score >= 760:
            underwriting_tier = 'tier_1_preferred'
        elif applicant.credit_score >= 680:
            underwriting_tier = 'tier_2_standard'
        else:
            underwriting_tier = 'tier_3_high_risk'

    try:
        risk_payload = {'applicant_id': applicant.id, 'tier': underwriting_tier, 'dti': dti_ratio}
        assessment = credit_bureau.request_final_clearance(risk_payload)
        if assessment.is_cleared:
            if underwriting_tier == 'tier_3_high_risk':
                ledger_entry = audit_ledger.reserve_escrow(loan_request.id, rate_multiplier=1.25)
            else:
                ledger_entry = audit_ledger.reserve_escrow(loan_request.id, rate_multiplier=1.0)
            return {'status': 'approved', 'tier': underwriting_tier, 'ledger_id': ledger_entry.id}
        else:
            return {'status': 'manual_review', 'flag': assessment.review_flag}
    except Exception as exc:
        return {'status': 'error', 'details': str(exc)}

