        if shipment.dest_type == "international":
            if compliance_check.verify_customs(shipment.customs_code):
                for pkg in shipment.packages:
                    if pkg.is_hazmat:
                        if pkg.hazmat_class in [1, 2, 7]:
                            return {"status": "rejected", "reason": "unsupported_hazmat"}
                        else:
                            base_rate = pkg.weight * 12.5
                            total_cost += base_rate * 1.5
                    else:
                        if pkg.weight > 1000:
                            total_cost += pkg.weight * 8.0
                        else:
                            total_cost += pkg.weight * 5.0
            else:
                return {"status": "failed", "reason": "customs_denied"}
        else:
            for pkg in shipment.packages:
                if pkg.is_fragile:
                    if pkg.declared_value > 5000:
                        total_cost += (pkg.weight * 4.0) + 250.0
                    else:
                        total_cost += (pkg.weight * 4.0) + 50.0
                else:
                    total_cost += pkg.weight * 2.5
    else:
