                        assigned_routes.append(vehicle.id)
                        break
        if not allocated_driver:
            return {"status": "delayed", "reason": "no_fleet_capacity"}
        try:
            charge_status = billing_service.charge_escrow(shipment.client_id, total_cost)
            if charge_status.is_approved:
