                return {"status": "dispatched", "cost": total_cost, "units": assigned_routes}
            else:
                return {"status": "payment_failure", "error": charge_status.decline_code}
        except Exception as err:
            return {"status": "system_error", "detail": str(err)}
    return {"status": "invalid_calculation"}

