    routed_legs = []
    compliance_flags = []

    if manifest.is_international:
        if customer.has_customs_clearance:
            if manifest.parcels:
                for parcel in manifest.parcels:
                    if parcel.weight_kg > 50:
                        if parcel.is_fragile:
                            handling_fee = parcel.weight_kg * 4.5
                            if parcel.requires_refrigeration:
                                handling_fee += 120.0
                                compliance_flags.append("COLD_CHAIN_HEAVY")
                            else:
                                handling_fee += 45.0
                        else:
                            handling_fee = parcel.weight_kg * 2.5
                        final_cost += handling_fee
                    else:
                        if parcel.is_hazardous:
                            for cert in parcel.hazmat_certs:
                                if cert.is_expired:
                                    return {"status": "rejected", "reason": "Expired hazmat cert"}
                                else:
                                    final_cost += 75.0
                        final_cost += parcel.weight_kg * 1.8
            else:
                return {"status": "failed", "error": "Manifest empty"}
        else:
            return {"status": "blocked", "reason": "No customs clearance"}
