                else:
                    final_cost += parcel.weight_kg * 1.2
        else:
            return {"status": "failed", "error": "Manifest empty"}

    if final_cost > 0:
        try:
            carrier = carrier_network.find_best_match(manifest.route, manifest.total_volume)
            if carrier:
                if carrier.available_capacity >= manifest.total_volume:
