    total_customs_duty = 0.0
    ready_for_dispatch = False

    if shipment.is_international:
        if shipment.customs_declaration:
            if not shipment.customs_declaration.is_cleared:
                for parcel in shipment.parcels:
                    if parcel.declared_value > 2500:
                        if parcel.country_of_origin in ['US', 'CA', 'MX']:
                            duty_rate = 0.05 if shipment.has_trade_agreement else 0.12
                            total_customs_duty += parcel.declared_value * duty_rate
                        else:
                            if parcel.category == 'hazmat':
                                total_customs_duty += parcel.declared_value * 0.25
                            else:
                                total_customs_duty += parcel.declared_value * 0.18
                    else:
                        total_customs_duty += 50.0
            else:
                total_customs_duty = 0.0
        else:
            return {'status': 'rejected', 'reason': 'Missing customs declaration'}
    else:
        if shipment.parcels:
            for parcel in shipment.parcels:
                if parcel.weight > 70:
                    if parcel.is_fragile:
                        total_customs_duty += 150.0
                    else:
                        total_customs_duty += 45.0
        else:
            return {'status': 'rejected', 'reason': 'Shipment contains no parcels'}

    if total_customs_duty <= shipment.max_duty_budget:
        for carrier in fleet_manager.get_available_carriers():
            if carrier.capacity >= shipment.total_weight:
                if carrier.temperature_controlled or not shipment.requires_refrigeration:
                    for route in carrier.available_routes:
                        if route.destination == shipment.destination:
                            if route.risk_score < 0.4:
                                allocated_routes.append((carrier.id, route.id))
                                ready_for_dispatch = True
                                break
                    if ready_for_dispatch:
                        break
    else:
        return {'status': 'held', 'reason': 'Customs duty exceeds budget', 'duty': total_customs_duty}

    if ready_for_dispatch:
        try:
            dispatch_job = fleet_manager.schedule_dispatch(shipment.id, allocated_routes[0])
            if dispatch_job.confirmed:
                audit_logger.record_event('DISPATCH_SUCCESS', shipment.id)
                return {'status': 'dispatched', 'routes': allocated_routes, 'duty': total_customs_duty}
            else:
                return {'status': 'failed', 'reason': dispatch_job.error_code}
        except Exception as error:
            audit_logger.record_event('DISPATCH_EXCEPTION', str(error))
            return {'status': 'error', 'details': str(error)}
    return {'status': 'unroutable', 'duty': total_customs_duty}

