import ast
from typing import Dict, List


def find_long_functions_with_many_branches(
    source_code: str, min_lines: int = 50, min_branches: int = 10
) -> List[Dict[str, int]]:
    """Scan Python source code for long functions with high branch counts."""
    tree = ast.parse(source_code)
    results = []
    branch_types = (
        ast.If,
        ast.IfExp,
        ast.While,
        ast.For,
        ast.AsyncFor,
        ast.ExceptHandler,
        ast.MatchValue,
        ast.match_case if hasattr(ast, "match_case") else type(None),
    )

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            start_line = node.lineno
            end_line = getattr(node, "end_lineno", start_line)
            line_count = end_line - start_line + 1

            branch_count = 0
            for child in ast.walk(node):
                if isinstance(child, branch_types):
                    branch_count += 1
                elif isinstance(child, ast.BoolOp):
                    branch_count += len(child.values) - 1

            if line_count >= min_lines and branch_count >= min_branches:
                results.append(
                    {
                        "name": node.name,
                        "line_count": line_count,
                        "branch_count": branch_count,
                        "lineno": start_line,
                    }
                )

    return results

