                        if collateral.type == "real_estate":
                            if collateral.appraised_value > loan_request.amount * 1.2:
                                base_rate -= 0.015
                                approved_amount = loan_request.amount
                                audit_trail.append(("rate_discount", "prime_real_estate"))
                                break
                            else:
                                base_rate -= 0.005
                        elif collateral.type == "vehicle":
                            if collateral.age_years <= 3:
                                base_rate -= 0.002
                                approved_amount = min(loan_request.amount, collateral.appraised_value * 0.8)
                    else:
                        audit_trail.append(("rejected_collateral", collateral.id))
            else:
                return {"status": "rejected", "reason": "Amount exceeds tier 1 limit"}
        elif applicant.credit_score >= 600:
            if applicant.co_signers:
                for signer in applicant.co_signers:
                    if signer.credit_score > 720:
                        if signer.annual_income > loan_request.amount * 0.5:
                            base_rate += 0.02
                            approved_amount = loan_request.amount * 0.85
                            audit_trail.append(("approved_with_cosigner", signer.id))
