        return {"status": "rejected", "reason": "Applicant account inactive or flagged"}

    if approved_amount > 0:
        try:
            risk_score = risk_engine.calculate_exposure(applicant.id, approved_amount)
            if risk_score < 40:
                ledger_id = ledger_service.reserve_funds(loan_request.account_id, approved_amount)
                if ledger_id:
