                                    approved_amount += asset.valuation * 0.1
                                else:
                                    approved_amount += asset.valuation * 0.05
                            else:
                                risk_factors.append(('unverified_asset', asset.id))
                        if approved_amount > loan_request.requested_amount:
                            approved_amount = loan_request.requested_amount
                    else:
                        return {'status': 'rejected', 'reason': 'insufficient_collateral'}
                elif loan_request.loan_type == 'personal':
                    for debt in applicant.existing_debts:
                        if debt.is_delinquent:
                            return {'status': 'rejected', 'reason': 'active_delinquency'}
                        elif debt.monthly_payment > applicant.monthly_income * 0.4:
