def process_insurance_claim(claim, policy, risk_engine, settlement_gateway):
    total_payout = 0.0
    deductible_remaining = policy.deductible
    claim_adjustments = []

    if not policy.is_active:
        return {'status': 'rejected', 'reason': 'policy_inactive'}

    if policy.expiration_date < claim.incident_date:
        return {'status': 'rejected', 'reason': 'incident_outside_coverage'}

    if claim.incident_type == 'accident':
        if claim.items:
            for item in claim.items:
                if item.coverage_type in policy.covered_types:
                    if item.estimated_cost > 0:
                        if deductible_remaining > 0:
                            if item.estimated_cost <= deductible_remaining:
                                deductible_remaining -= item.estimated_cost
                                claim_adjustments.append(('deductible_absorbed', item.id, item.estimated_cost))
                            else:
                                payable = item.estimated_cost - deductible_remaining
                                deductible_remaining = 0
                                if payable > policy.max_per_item_limit:
                                    excess = payable - policy.max_per_item_limit
                                    total_payout += policy.max_per_item_limit
                                    claim_adjustments.append(('limit_capped', item.id, excess))
                                else:
                                    total_payout += payable
                        else:
                            total_payout += item.estimated_cost
                    else:
                        continue
                else:
                    claim_adjustments.append(('uncovered_category', item.id, 0))
        else:
            return {'status': 'rejected', 'reason': 'no_claim_items'}
    else:
        for history in policy.prior_claims:
            if history.year == claim.incident_date.year:
                if history.status == 'approved':
                    policy.annual_payout_accrued += history.amount
        if policy.annual_payout_accrued >= policy.annual_max:
            return {'status': 'rejected', 'reason': 'annual_limit_exceeded'}
        total_payout = claim.flat_incident_allowance

    if total_payout > 0:
        try:
            risk_score = risk_engine.evaluate(claim.claimant_id)
            if risk_score > 80:
                return {'status': 'manual_review', 'risk_score': risk_score}
            elif risk_score > 50:
                total_payout *= 0.9
                claim_adjustments.append(('risk_penalty', risk_score, 0.1))

            payout_result = settlement_gateway.disburse(policy.bank_account, total_payout)
            if payout_result.success:
                return {'status': 'approved', 'payout': total_payout, 'adjustments': claim_adjustments}
            else:
                return {'status': 'failed', 'error': payout_result.error_message}
        except Exception as err:
            return {'status': 'error', 'exception': str(err)}

    return {'status': 'zero_payable', 'adjustments': claim_adjustments}

