import ast


def get_functions_with_most_decision_paths(source_code: str, top_n: int = 10):
    tree = ast.parse(source_code)
    decision_nodes = (
        ast.If,
        ast.For,
        ast.AsyncFor,
        ast.While,
        ast.ExceptHandler,
        ast.Assert,
    )

    ranked_functions = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            complexity = 1
            for child in ast.walk(node):
                if isinstance(child, decision_nodes):
                    complexity += 1
                elif isinstance(child, ast.BoolOp):
                    complexity += len(child.values) - 1
                elif isinstance(child, ast.comprehension):
                    complexity += 1 + len(child.ifs)
            ranked_functions.append({"function": node.name, "decision_points": complexity})

    ranked_functions.sort(key=lambda x: x["decision_points"], reverse=True)
    return ranked_functions[:top_n]

