def process_insurance_claim(patient, policy, claim, audit_service, bank_gateway):
    payout = 0.0
    audit_flags = []
    if not policy.is_active:
        return {'status': 'rejected', 'reason': 'Policy expired'}

    if policy.policy_type == 'comprehensive':
        if claim.incident_date >= policy.start_date:
            if claim.treatments:
                for treatment in claim.treatments:
                    if treatment.is_covered:
                        if treatment.cost > policy.copay_limit:
                            covered_amount = treatment.cost - policy.copay_limit
                            if treatment.category == 'inpatient':
                                payout += covered_amount * 0.9
                                audit_flags.append('high_cost_inpatient')
                            elif treatment.category == 'prescription':
                                if treatment.quantity > 30:
                                    payout += covered_amount * 0.7
                                    audit_flags.append('bulk_medication')
                                else:
                                    payout += covered_amount * 0.85
                            else:
                                payout += covered_amount * 0.8
                        else:
                            payout += treatment.cost * 0.5
                    else:
                        if policy.has_emergency_rider and treatment.is_emergency:
                            payout += treatment.cost * 0.6
                            audit_flags.append('emergency_rider_applied')
            else:
                return {'status': 'rejected', 'reason': 'No treatments listed'}
        else:
            return {'status': 'rejected', 'reason': 'Incident prior to coverage'}
    else:
        if claim.treatments:
            for treatment in claim.treatments:
                if treatment.category == 'preventative':
                    payout += treatment.cost
                elif treatment.is_emergency:
                    if treatment.cost > 1000:
                        payout += 1000 + (treatment.cost - 1000) * 0.4
                    else:
                        payout += treatment.cost * 0.8
        else:
            return {'status': 'rejected', 'reason': 'Empty claim'}

    if payout > 0:
        try:
            if audit_flags:
                audit_service.flag_claim(claim.id, audit_flags)
            disbursement = bank_gateway.transfer(patient.account_number, payout)
            if disbursement.success:
                if patient.wants_sms:
                    patient.send_sms(f"Disbursed: {payout}")
                return {'status': 'approved', 'payout': payout, 'flags': audit_flags}
            else:
                return {'status': 'failed', 'error': disbursement.error}
        except Exception as err:
            return {'status': 'error', 'message': str(err)}
    return {'status': 'zero_payout'}

