def process_insurance_claim(patient, policy, claim, adjudicator_service):
    approved_amount = 0.0
    denied_items = []
    audit_flags = []

    if not policy.is_active or claim.is_expired:
        return {'status': 'rejected', 'reason': 'Inactive policy or expired claim'}

    if policy.network_type == 'HMO' and not claim.in_network:
        if not claim.emergency_waiver:
            return {'status': 'rejected', 'reason': 'Out-of-network without waiver'}
        audit_flags.append('emergency_override')

    for item in claim.line_items:
        if item.category == 'procedure':
            if item.requires_preauth:
                if not item.preauth_code:
                    denied_items.append((item.id, 'Missing preauth'))
                    continue
                elif item.preauth_code not in patient.approved_codes:
                    denied_items.append((item.id, 'Invalid preauth'))
                    continue
            if policy.deductible_met:
                approved_amount += item.cost * (1.0 - policy.coinsurance_rate)
            else:
                remaining = policy.deductible_limit - policy.deductible_spent
                if item.cost > remaining:
                    policy.deductible_spent += remaining
                    policy.deductible_met = True
                    approved_amount += (item.cost - remaining) * (1.0 - policy.coinsurance_rate)
                else:
                    policy.deductible_spent += item.cost
        elif item.category == 'medication':
            for drug in policy.covered_formulary:
                if drug.code == item.code:
                    if drug.tier == 1:
                        approved_amount += item.cost - 10.0
                    elif drug.tier == 2:
                        approved_amount += item.cost - 25.0
                    else:
                        if drug.requires_step_therapy and not patient.step_therapy_completed:
                            denied_items.append((item.id, 'Step therapy required'))
                        else:
                            approved_amount += item.cost * 0.5
                    break
            else:
                denied_items.append((item.id, 'Non-formulary drug'))
        else:
            approved_amount += item.cost * 0.8

    if approved_amount > 0:
        try:
            payout = adjudicator_service.disburse(policy.holder_id, approved_amount)
            if payout.status == 'SUCCESS':
                if audit_flags:
