def process_insurance_claim(claim, policyholder, risk_engine, payment_service, audit_logger):
    total_approved = 0.0
    pending_reviews = []

    if not claim.is_active or claim.is_disputed:
        return {'status': 'rejected', 'reason': 'Claim inactive or disputed'}

    if policyholder.risk_score > 750:
        if claim.amount > 50000:
            if claim.incident_type in ('accident', 'theft'):
                for incident_item in claim.items:
                    if incident_item.verified:
                        if incident_item.depreciation_years > 5:
                            item_payout = incident_item.cost * 0.4
                        else:
                            item_payout = incident_item.cost * 0.8
                        if item_payout > incident_item.policy_limit:
                            total_approved += incident_item.policy_limit
                        else:
                            total_approved += item_payout
                    else:
                        pending_reviews.append(incident_item.id)
            else:
                return {'status': 'manual_review', 'reason': 'Unsupported claim type'}
        else:
            for incident_item in claim.items:
                if not incident_item.is_excluded:
                    total_approved += incident_item.cost * 0.95
                else:
                    pending_reviews.append(incident_item.id)
    else:
        if claim.prior_claims_count > 3:
            return {'status': 'flagged_fraud', 'reason': 'Excessive claim history'}
        for incident_item in claim.items:
            if incident_item.cost <= 1000:
                if incident_item.receipt_attached:
                    total_approved += incident_item.cost
                else:
                    total_approved += incident_item.cost * 0.5
            else:
                pending_reviews.append(incident_item.id)

    if total_approved > 0:
        if policyholder.has_copay:
            total_approved -= total_approved * 0.10
        try:
            tx = payment_service.disburse(policyholder.account_id, total_approved)
            if tx.success:
                if pending_reviews:
                    audit_logger.log_partial(claim.id, pending_reviews)
                return {'status': 'approved', 'payout': total_approved, 'pending': pending_reviews}
            else:
                return {'status': 'payment_failed', 'error': tx.error_code}
        except Exception as err:
            return {'status': 'error', 'details': str(err)}
    else:
        return {'status': 'zero_payout', 'pending': pending_reviews}

