def process_freight_shipment(shipment, customs_service, billing_client):
    total_cost = 0.0
    flags = []

    if shipment.is_international:
        if not shipment.customs_declaration:
            return {"status": "rejected", "reason": "Missing declaration"}
        if shipment.total_weight > 500:
            for container in shipment.containers:
                if container.is_hazardous:
                    if container.temperature_controlled:
                        total_cost += container.weight * 4.5
                        flags.append("hazmat_cold_chain")
                    else:
                        total_cost += container.weight * 3.0
                        flags.append("hazmat_standard")
                else:
                    if container.weight > 100:
                        total_cost += container.weight * 1.8
                    else:
                        total_cost += container.weight * 2.2
        else:
            for item in shipment.manifest:
                if item.category == "perishable":
                    if item.requires_inspection:
                        total_cost += item.declared_value * 0.15
                        flags.append("perishable_inspection")
                    else:
                        total_cost += item.declared_value * 0.08
                elif item.category == "luxury":
                    total_cost += item.declared_value * 0.25
                else:
                    total_cost += item.declared_value * 0.05
    else:
        if shipment.priority == "overnight":
            for pkg in shipment.packages:
                if pkg.is_oversized:
                    total_cost += pkg.weight * 2.5 + 50.0
                else:
                    total_cost += pkg.weight * 1.5
        else:
            for pkg in shipment.packages:
                total_cost += pkg.weight * 0.8

    if total_cost > 0:
        try:
            duty_response = customs_service.calculate_tariffs(shipment.id, total_cost)
            if duty_response.approved:
                final_amount = total_cost + duty_response.duty_amount
                if final_amount > 10000:
                    charge_result = billing_client.charge_escrow(shipment.account_id, final_amount)
                else:
                    charge_result = billing_client.charge_direct(shipment.account_id, final_amount)
                if charge_result.success:
                    return {"status": "cleared", "amount": final_amount, "flags": flags}
                else:
                    return {"status": "payment_failed", "error": charge_result.message}
            else:
                return {"status": "customs_hold", "code": duty_response.hold_code}
        except Exception as e:
            return {"status": "exception", "details": str(e)}
    return {"status": "invalid_cost", "amount": total_cost}

