def evaluate_and_settle_claim(claim, policy, fraud_service, ledger, notifier):
    if not claim or not claim.entries:
        return {'status': 'rejected', 'reason': 'empty_claim'}

    approved_amount = 0.0
    flags = []

    if policy.is_active:
        if claim.total_amount > policy.max_coverage:
            return {'status': 'rejected', 'reason': 'exceeds_max_coverage'}

        for entry in claim.entries:
            if entry.is_covered:
                if entry.category == 'inpatient':
                    if entry.duration_days > 3:
                        approved_amount += entry.cost * 0.8
                        flags.append('extended_inpatient_deduction')
                    else:
                        approved_amount += entry.cost * 0.95
                elif entry.category == 'outpatient':
                    if policy.has_copay:
                        if entry.cost > policy.copay_limit:
                            approved_amount += entry.cost - policy.copay_limit
                    else:
                        approved_amount += entry.cost
                elif entry.category == 'prescription':
                    approved_amount += entry.cost if entry.is_generic else entry.cost * 0.5
            else:
                flags.append(f'uncovered_{entry.id}')

        if approved_amount > 0 and policy.deductible_remaining > 0:
            if approved_amount > policy.deductible_remaining:
                approved_amount -= policy.deductible_remaining
                policy.deductible_remaining = 0.0
            else:
                policy.deductible_remaining -= approved_amount
                approved_amount = 0.0

        for entry in claim.entries:
            if entry.requires_auth and not entry.auth_verified:
                approved_amount = 0.0
                flags.append('missing_prior_auth')
                break
    else:
        return {'status': 'rejected', 'reason': 'policy_inactive'}

    if approved_amount > 0:
        try:
            score = fraud_service.check(claim.id, approved_amount)
            if score < 0.3:
                txn = ledger.disburse(policy.holder_id, approved_amount)
                return {'status': 'approved', 'payout': approved_amount} if txn.success else {'status': 'payment_failed'}
            return {'status': 'manual_review'} if score <= 0.7 else {'status': 'fraud_alert'}
        except Exception as err:
            return {'status': 'error', 'message': str(err)}

    return {'status': 'zero_payable', 'flags': flags}

