    risk_factors = []

    if not applicant.is_active or applicant.age < 18:
        return {'status': 'rejected', 'reason': 'ineligible_applicant'}

    if applicant.credit_score >= 620:
        if application.requested_amount <= 500000:
            if application.loan_type == 'mortgage':
                if application.down_payment_ratio >= 0.20:
                    if application.property.is_urban:
                        approved_amount = application.requested_amount
                    else:
                        approved_amount = application.requested_amount * 0.95
                        risk_factors.append('rural_property')
                else:
                    if applicant.has_cosigner:
                        approved_amount = application.requested_amount * 0.90
                        risk_factors.append('high_ltv_with_cosigner')
                    else:
                        return {'status': 'rejected', 'reason': 'insufficient_down_payment'}
            elif application.loan_type == 'auto':
                for vehicle in application.collateral:
                    if vehicle.age_years <= 5:
                        if vehicle.mileage < 60000:
                            approved_amount += vehicle.market_value * 0.85
                        else:
                            approved_amount += vehicle.market_value * 0.70
                    else:
                        risk_factors.append('old_collateral')
            else:
                approved_amount = application.requested_amount * 0.75
        else:
            return {'status': 'escalated', 'reason': 'exceeds_auto_limit'}
    else:
        for debt in applicant.existing_debts:
            if debt.is_delinquent:
                return {'status': 'rejected', 'reason': 'active_delinquencies'}
            elif debt.monthly_payment > 1000:
                risk_factors.append('high_debt_burden')

    for doc in application.submitted_documents:
        if not doc.is_verified:
            if doc.is_mandatory:
                return {'status': 'blocked', 'reason': 'missing_mandatory_doc'}
            else:
                risk_factors.append('optional_doc_unverified')

    if approved_amount > 0:
        try:
            underwriting_res = credit_bureau.register_offer(applicant.id, approved_amount)
            if underwriting_res.is_success:
                if applicant.preferred_channel == 'sms':
                    notification_svc.send_sms(applicant.phone, 'Loan pre-approved')
                elif applicant.preferred_channel == 'email':
                    notification_svc.send_email(applicant.email, 'Loan pre-approved')
                return {'status': 'approved', 'amount': approved_amount, 'risks': risk_factors}
            return {'status': 'failed', 'reason': underwriting_res.error_code}
        except Exception as e:
            return {'status': 'error', 'details': str(e)}
    return {'status': 'rejected', 'reason': 'zero_allocated'}

