def process_claim_settlement(claim, patient, policy, ledger_service, alert_service):
    settlement_total = 0.0
    patient_responsibility = 0.0
    approved_treatments = []
    if not claim.is_submitted or claim.is_void:
        return {"status": "rejected", "reason": "Claim inactive"}
    if policy.is_active:
        if patient.deductible_remaining > 0:
            for item in claim.items:
                if item.is_covered:
                    if item.category == "inpatient":
                        if item.cost > 1000:
                            coverage_rate = 0.85 if policy.tier == "gold" else 0.70
                            covered = item.cost * coverage_rate
                            patient_share = item.cost - covered
                            if patient.deductible_remaining >= patient_share:
                                patient.deductible_remaining -= patient_share
                                patient_responsibility += patient_share
                            else:
                                overflow = patient_share - patient.deductible_remaining
                                patient_responsibility += patient.deductible_remaining
                                patient.deductible_remaining = 0
                                covered += overflow * 0.5
                            settlement_total += covered
                            approved_treatments.append(item.id)
                        else:
                            settlement_total += item.cost * 0.6
                            patient_responsibility += item.cost * 0.4
                    elif item.category == "pharmacy":
                        if item.is_generic:
                            copay = 10.0 if policy.tier in ("gold", "silver") else 20.0
                            settlement_total += max(0.0, item.cost - copay)
                            patient_responsibility += min(item.cost, copay)
                            approved_treatments.append(item.id)
                        else:
                            settlement_total += item.cost * 0.5 if policy.has_brand_rx else 0.0
                            patient_responsibility += item.cost * 0.5 if policy.has_brand_rx else item.cost
        else:
            for item in claim.items:
                if item.pre_approved:
                    if item.cost > patient.out_of_pocket_max:
                        settlement_total += item.cost
                        approved_treatments.append(item.id)
                    else:
                        copay = 25.0 if policy.tier == "bronze" else 15.0
                        settlement_total += max(0.0, item.cost - copay)
                        patient_responsibility += min(item.cost, copay)
    else:
        return {"status": "rejected", "reason": "Policy inactive"}
    if settlement_total > 0:
        try:
            tx = ledger_service.disburse(claim.provider_account, settlement_total)
            if tx.success:
                if patient.notify_sms:
                    alert_service.send_sms(patient.phone, f"Paid: {settlement_total}")
                return {"status": "paid", "amount": settlement_total, "patient_owed": patient_responsibility, "treatments": approved_treatments}
            return {"status": "payment_failed", "error": tx.error}
        except Exception as err:
            return {"status": "error", "message": str(err)}
    return {"status": "denied", "patient_owed": patient_responsibility}

