import ast
from typing import Dict, List, Union


class PathComplexityCounter(ast.NodeVisitor):
    def __init__(self):
        self.paths = 1

    def visit_If(self, node: ast.If):
        self.paths += 1
        self.generic_visit(node)

    def visit_IfExp(self, node: ast.IfExp):
        self.paths += 1
        self.generic_visit(node)

    def visit_For(self, node: Union[ast.For, ast.AsyncFor]):
        self.paths += 1
        self.generic_visit(node)

    visit_AsyncFor = visit_For

    def visit_While(self, node: ast.While):
        self.paths += 1
        self.generic_visit(node)

    def visit_ExceptHandler(self, node: ast.ExceptHandler):
        self.paths += 1
        self.generic_visit(node)

    def visit_BoolOp(self, node: ast.BoolOp):
        self.paths += len(node.values) - 1
        self.generic_visit(node)

    def visit_comprehension(self, node: ast.comprehension):
        self.paths += len(node.ifs)
        self.generic_visit(node)

    def visit_Match(self, node: ast.Match):
        self.paths += max(len(node.cases) - 1, 0)
        self.generic_visit(node)


def find_hard_to_test_functions(source_code: str, min_paths: int = 10) -> List[Dict[str, Union[str, int]]]:
    """Scan code for functions with excessive independent execution paths (high cyclomatic complexity)."""
    tree = ast.parse(source_code)
    hard_to_test = []

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            counter = PathComplexityCounter()
            for stmt in node.body:
                counter.visit(stmt)

            if counter.paths >= min_paths:
                hard_to_test.append({
                    "name": node.name,
                    "line": node.lineno,
                    "independent_paths": counter.paths,
                    "risk": "HIGH" if counter.paths >= 15 else "MEDIUM"
                })

    return sorted(hard_to_test, key=lambda f: f["independent_paths"], reverse=True)

