) -> list[dict]:
    """Identify functions with high cyclomatic complexity and many independent paths."""
    tree = ast.parse(source_code)
    results = []

    branch_nodes = (
        ast.If,
        ast.For,
        ast.AsyncFor,
        ast.While,
        ast.ExceptHandler,
        ast.Assert,
    )

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            independent_paths = 1

            for child in ast.walk(node):
                if isinstance(child, branch_nodes):
                    independent_paths += 1
                elif isinstance(child, ast.BoolOp):
                    independent_paths += len(child.values) - 1

            if independent_paths > complexity_threshold:
                results.append(
                    {
                        "function_name": node.name,
                        "line_number": node.lineno,
                        "independent_paths": independent_paths,
                    }
                )

    return results

