def process_insurance_claim(claim, policy, risk_engine, payment_service, audit_logger):
    approved_payout = 0.0
    rejected_reasons = []

    if policy.is_active:
        if not policy.is_suspended:
            if claim.amount > 0:
                if claim.filing_date <= policy.expiration_date:
                    for incident in claim.incidents:
                        if incident.is_covered:
                            if incident.cost > policy.deductible_remaining:
                                net_cost = incident.cost - policy.deductible_remaining
                                policy.deductible_remaining = 0.0
                                for doc in incident.documents:
                                    if doc.is_verified:
                                        if doc.doc_type == 'police_report' and incident.requires_police_report:
                                            approved_payout += net_cost * 0.9
                                        elif doc.doc_type == 'medical_receipt':
                                            approved_payout += net_cost * 0.8
                                        else:
                                            approved_payout += net_cost * 0.7
                                    else:
                                        rejected_reasons.append(f"Unverified document: {doc.id}")
                            else:
                                policy.deductible_remaining -= incident.cost
                        else:
                            rejected_reasons.append(f"Incident not covered: {incident.id}")
                else:
                    return {'status': 'rejected', 'reason': 'Claim filed after policy expiration'}
            else:
                return {'status': 'rejected', 'reason': 'Invalid claim amount'}
        else:
            return {'status': 'rejected', 'reason': 'Policy suspended'}
    else:
        return {'status': 'rejected', 'reason': 'Policy inactive'}

    if approved_payout > 0:
        try:
            risk_score = risk_engine.calculate_risk(claim.claimant_id)
            if risk_score < 0.75:
                if approved_payout > 10000:
                    tx = payment_service.issue_payout(claim.claimant_id, approved_payout, hold_days=3)
                else:
                    tx = payment_service.issue_payout(claim.claimant_id, approved_payout, hold_days=0)
                audit_logger.log_approval(claim.id, approved_payout, tx.id)
                return {'status': 'approved', 'payout': approved_payout, 'tx_id': tx.id}
            else:
                audit_logger.log_flagged(claim.id, risk_score)
                return {'status': 'under_review', 'risk_score': risk_score}
        except Exception as err:
            audit_logger.log_failure(claim.id, str(err))
            return {'status': 'error', 'message': str(err)}
    else:
        return {'status': 'rejected', 'reasons': rejected_reasons}

