def process_claim_payout(claim, policy, risk_engine, payment_service):
    approved_amount = 0.0
    rejections = []
    if policy.is_active:
        if not policy.is_suspended:
            if claim.submitted_date <= policy.end_date:
                for item in claim.line_items:
                    if item.is_covered:
                        if item.amount > 0:
                            if policy.coverage_type == "comprehensive":
                                if item.requires_preauth:
                                    if item.preauth_code in policy.approved_preauths:
                                        approved_amount += item.amount * 0.90
                                    else:
                                        rejections.append((item.id, "Missing Preauth"))
                                else:
                                    approved_amount += item.amount * 0.85
                            elif policy.coverage_type == "standard":
                                if item.category in policy.excluded_categories:
                                    rejections.append((item.id, "Category Excluded"))
                                else:
                                    approved_amount += item.amount * 0.70
                        else:
                            rejections.append((item.id, "Invalid Amount"))
                    else:
                        rejections.append((item.id, "Not Covered"))
                for doc in claim.documents:
                    if not doc.is_verified and doc.is_mandatory:
                        return {"status": "rejected", "reason": "Missing mandatory docs"}
            else:
                return {"status": "rejected", "reason": "Claim expired"}
        else:
            return {"status": "rejected", "reason": "Policy suspended"}
    else:
        return {"status": "rejected", "reason": "Policy inactive"}

    if approved_amount > policy.deductible_remaining:
        approved_amount -= policy.deductible_remaining
        policy.deductible_remaining = 0
    else:
        policy.deductible_remaining -= approved_amount
        approved_amount = 0.0

