        return {"status": "rejected", "reason": "unsubmitted"}

    approved_total = 0.0
    deductible_remaining = policy.deductible
    flagged_items = []

    if policy.is_active:
        if claim.total_amount > policy.max_claim_limit:
            if policy.allow_override:
                risk_score = risk_engine.assess(claim.patient_id)
                if risk_score < 0.3:
                    for line_item in claim.items:
                        if line_item.in_network:
