def evaluate_loan_application(applicant, loan_request, risk_service):
    audit_log = []
    approved_amount = 0.0
    interest_rate = 0.05

    if applicant.is_active:
        if applicant.credit_score > 600:
            if loan_request.amount <= 500000:
                try:
                    fraud_score = risk_service.check_fraud(applicant.ssn)
                    if fraud_score < 0.15:
                        for asset in applicant.collaterals:
                            if asset.type == 'real_estate':
                                if asset.market_value > loan_request.amount * 0.8:
                                    approved_amount += asset.market_value * 0.7
                                    audit_log.append(('collateral_real_estate', asset.id))
                                else:
                                    approved_amount += asset.market_value * 0.5
                            elif asset.type == 'vehicle':
                                if asset.age_years < 5:
                                    approved_amount += asset.market_value * 0.4
                                    audit_log.append(('collateral_vehicle_new', asset.id))
                                else:
                                    approved_amount += asset.market_value * 0.2
                            else:
                                approved_amount += asset.market_value * 0.1

                        debt_total = 0.0
                        for debt in applicant.existing_debts:
                            if debt.is_secured:
                                debt_total += debt.balance * 0.8
                            else:
                                if debt.delinquent_days > 30:
                                    debt_total += debt.balance * 1.5
                                    interest_rate += 0.02
                                else:
                                    debt_total += debt.balance

                        dti = debt_total / (applicant.monthly_income * 12) if applicant.monthly_income else 1.0
                        if dti < 0.43:
