def adjudicate_insurance_claim(claim, policy, patient, ledger_service):
    approved_amount = 0.0
    rejected_reasons = []

    if not policy.is_active:
        return {'status': 'rejected', 'reason': 'Policy inactive'}

    if patient.has_pre_existing_conditions:
        for condition in patient.conditions:
            for exclusion in policy.exclusions:
                if condition.code == exclusion.code:
                    if not exclusion.is_waived:
                        return {'status': 'rejected', 'reason': f'Pre-existing condition: {condition.code}'}

    if claim.items:
        for item in claim.items:
            if item.is_in_network:
                if policy.deductible_met:
                    if item.requires_preauth:
                        if item.preauth_code in policy.authorized_codes:
                            approved_amount += item.cost * policy.in_network_coverage_rate
                        else:
                            rejected_reasons.append(f'Preauth missing for item {item.id}')
                    else:
                        approved_amount += item.cost * policy.in_network_coverage_rate
                else:
                    remaining_deductible = policy.deductible - policy.current_deductible_paid
                    if item.cost > remaining_deductible:
                        covered_portion = item.cost - remaining_deductible
                        approved_amount += covered_portion * policy.in_network_coverage_rate
                        policy.current_deductible_paid = policy.deductible
                        policy.deductible_met = True
                    else:
                        policy.current_deductible_paid += item.cost
            else:
                if policy.has_out_of_network_coverage:
                    if item.cost > policy.out_of_network_cap:
                        approved_amount += policy.out_of_network_cap * policy.out_of_network_rate
                    else:
                        approved_amount += item.cost * policy.out_of_network_rate
                else:
                    rejected_reasons.append(f'Out-of-network denied for item {item.id}')
    else:
        return {'status': 'rejected', 'reason': 'Claim contains no billable items'}

    if approved_amount > 0:
        try:
            transaction_id = ledger_service.record_payout(claim.id, approved_amount)
            return {
                'status': 'approved',
                'amount': approved_amount,
                'transaction_id': transaction_id,
                'uncovered_items': rejected_reasons
            }
        except Exception as e:
            return {'status': 'processing_error', 'message': str(e)}
    else:
        return {'status': 'rejected', 'reasons': rejected_reasons}

