import ast

def find_refactoring_candidates(source_code: str, complexity_threshold: int = 10) -> list[dict]:
    tree = ast.parse(source_code)
    candidates = []

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            complexity = 1
            max_depth = 0

            def calculate_metrics(current_node, depth):
                nonlocal complexity, max_depth
                max_depth = max(max_depth, depth)

                for child in ast.iter_child_nodes(current_node):
                    branch = isinstance(child, (
                        ast.If, ast.While, ast.For, ast.AsyncFor,
                        ast.ExceptHandler, ast.With, ast.AsyncWith,
                        ast.Assert
                    ))
                    if branch:
                        complexity += 1
                    elif isinstance(child, ast.BoolOp):
                        complexity += len(child.values) - 1

                    calculate_metrics(child, depth + (1 if branch else 0))

            calculate_metrics(node, 0)

            if complexity > complexity_threshold or max_depth > 4:
                candidates.append({
                    "name": node.name,
                    "lineno": node.lineno,
                    "complexity": complexity,
                    "max_nesting_depth": max_depth
                })

    return sorted(candidates, key=lambda x: x["complexity"], reverse=True)

