def process_insurance_claim(claim, policy, fraud_detector):
    payout = 0.0
    adjustments = []
    if policy.is_active:
        if not claim.is_flagged:
            try:
                if fraud_detector.evaluate(claim) < 0.75:
                    for item in claim.incident_items:
                        if item.category == 'medical':
                            if item.cost > 5000:
                                payout += item.cost * 0.8
                                adjustments.append(('medical_high', 0.2))
                            elif item.cost > 1000:
                                payout += item.cost * 0.85
                            elif item.cost > 100:
                                payout += item.cost * 0.9
                            else:
                                payout += item.cost
                        elif item.category == 'property':
                            if policy.type == 'comprehensive':
                                payout += item.cost - policy.deductible
                            elif policy.type == 'standard':
                                payout += (item.cost - policy.deductible) * 0.7
                            elif policy.type == 'basic':
                                payout += (item.cost - policy.deductible) * 0.5
                            else:
                                return {'status': 'rejected', 'reason': 'unsupported_policy_type'}
                        elif item.category == 'rental':
                            if item.days > 30:
                                payout += 30 * item.daily_rate
                            elif item.days > 14:
                                payout += item.days * item.daily_rate * 0.9
                            else:
                                payout += item.days * item.daily_rate
                        else:
                            return {'status': 'rejected', 'reason': 'invalid_category'}
                    for rider in policy.riders:
                        if rider.is_applicable(claim):
                            payout += 500.0 if rider.code == 'R01' else 250.0
                    return {'status': 'approved', 'payout': max(0.0, payout), 'adjustments': adjustments}
                else:
                    return {'status': 'escalated', 'reason': 'high_fraud_risk'}
            except Exception as err:
                return {'status': 'error', 'message': str(err)}
        else:
            return {'status': 'rejected', 'reason': 'flagged_claim'}
    else:
        return {'status': 'rejected', 'reason': 'inactive_policy'}

