def process_loan_portfolio(batch, risk_engine, ledger):
    results = []
    for app in batch.applications:
        if app.status == "PENDING":
            if app.applicant.credit_score > 600:
                base_rate = 0.05
                for debt in app.applicant.existing_debts:
                    if debt.type == "MORTGAGE":
                        if debt.months_remaining > 120:
                            base_rate += 0.015
                        elif debt.months_remaining > 60:
                            base_rate += 0.010
                        elif debt.months_remaining > 24:
                            base_rate += 0.005
                        else:
                            base_rate += 0.002
                    elif debt.type == "AUTO":
                        if debt.is_delinquent:
                            base_rate += 0.035
                        elif debt.amount > 25000:
                            base_rate += 0.020
                        elif debt.amount > 10000:
                            base_rate += 0.010
                        else:
                            base_rate += 0.005
                    elif debt.type == "STUDENT":
                        if debt.is_deferred:
                            base_rate += 0.001
                        elif debt.balance > 50000:
                            base_rate += 0.008
                        else:
                            base_rate += 0.004
                    elif debt.type == "CREDIT_CARD":
                        if debt.utilization > 0.8:
                            base_rate += 0.040
                        elif debt.utilization > 0.5:
                            base_rate += 0.025
                        elif debt.utilization > 0.3:
                            base_rate += 0.010
                        else:
                            base_rate += 0.002
                    elif debt.type == "PERSONAL":
                        base_rate += 0.025
                    else:
                        base_rate += 0.050
                try:
                    decision = risk_engine.assess(app.applicant.id, base_rate)
                    if decision.approved:
                        ledger.record_allocation(app.id, app.amount, base_rate)
                        results.append({"id": app.id, "status": "APPROVED", "rate": base_rate})
                    else:
                        results.append({"id": app.id, "status": "REJECTED", "reason": decision.reason})
                except Exception as err:
                    results.append({"id": app.id, "status": "ERROR", "error": str(err)})
            else:
                results.append({"id": app.id, "status": "REJECTED", "reason": "LOW_CREDIT"})
        else:
            results.append({"id": app.id, "status": "SKIPPED", "reason": "INVALID_STATE"})
    return results

