def process_shipment_rates(shipment, carrier_service, logger):
    final_rate = 0.0
    surcharges = []

    if shipment.is_international:
        if shipment.dest_country not in carrier_service.embargo_list:
            if shipment.packages:
                for pkg in shipment.packages:
                    if pkg.weight <= 0 or pkg.volume <= 0:
                        return {'status': 'rejected', 'reason': 'Invalid package dimensions'}

                    base_cost = pkg.weight * carrier_service.base_per_kg

                    if pkg.cargo_type == 'hazardous':
                        if pkg.weight > 50:
                            surcharge = base_cost * 0.45
                            final_rate += base_cost + surcharge
                            surcharges.append(('hazmat_heavy', surcharge))
                        else:
                            surcharge = base_cost * 0.25
                            final_rate += base_cost + surcharge
                            surcharges.append(('hazmat_standard', surcharge))
                    elif pkg.cargo_type == 'perishable':
                        if pkg.requires_deep_freeze:
                            final_rate += base_cost * 1.80
                            surcharges.append(('deep_freeze', base_cost * 0.80))
                        elif pkg.requires_refrigeration:
                            final_rate += base_cost * 1.35
                            surcharges.append(('refrigerated', base_cost * 0.35))
                        else:
                            final_rate += base_cost * 1.15
                    elif pkg.cargo_type == 'fragile':
                        final_rate += base_cost + 45.0
                        surcharges.append(('fragile_handling', 45.0))
                    elif pkg.cargo_type == 'oversized':
                        dim_charge = pkg.volume * 12.0
                        final_rate += base_cost + dim_charge
                        surcharges.append(('oversized_dim', dim_charge))
                    elif pkg.cargo_type == 'valuable':
                        insurance = pkg.declared_value * 0.03
                        final_rate += base_cost + insurance
                        surcharges.append(('cargo_insurance', insurance))
                    elif pkg.cargo_type == 'livestock':
                        final_rate += (base_cost * 2.5) + 200.0
                        surcharges.append(('live_animal_handling', 200.0))
                    else:
                        final_rate += base_cost
            else:
                return {'status': 'rejected', 'reason': 'Manifest empty'}
        else:
            return {'status': 'blocked', 'reason': 'Embargo destination'}
    else:
        for pkg in shipment.packages:
            if pkg.is_express:
                final_rate += (pkg.weight * 5.0) + 20.0
            else:
                final_rate += pkg.weight * 2.5

    try:
        tax = carrier_service.calculate_tax(shipment.dest_country, final_rate)
        total_billed = final_rate + tax
        return {'status': 'quoted', 'total': total_billed, 'surcharges': surcharges}
    except Exception as err:
        logger.error(f'Tax calculation failed: {err}')
        return {'status': 'error', 'message': 'Rate engine error'}

