def process_shipment_customs_clearance(shipment, destination_country, compliance_service, ledger):
    total_duty = 0.0
    cleared_items = []

    if shipment.is_international:
        if shipment.declared_value > 0:
            if shipment.cargo_manifest:
                for parcel in shipment.cargo_manifest:
                    if parcel.is_insured:
                        for item in parcel.contents:
                            duty_rate = 0.0
                            if item.commodity_type == 'hazmat':
                                if item.weight > 50:
                                    duty_rate = 0.35
                                else:
                                    duty_rate = 0.25
                            elif item.commodity_type == 'perishable':
                                if item.storage_temp < 0:
                                    duty_rate = 0.18
                                else:
                                    duty_rate = 0.12
                            elif item.commodity_type == 'electronics':
                                if destination_country.code in ['US', 'EU']:
                                    duty_rate = 0.05
                                elif destination_country.code in ['BR', 'IN']:
                                    duty_rate = 0.40
                                else:
                                    duty_rate = 0.15
                            elif item.commodity_type == 'luxury':
                                if item.declared_value > 5000:
                                    duty_rate = 0.50
                                else:
                                    duty_rate = 0.30
                            elif item.commodity_type == 'textiles':
                                duty_rate = 0.08
                            elif item.commodity_type == 'pharmaceutical':
                                duty_rate = 0.45 if item.is_controlled else 0.02
                            else:
                                duty_rate = 0.10

                            calculated_tax = item.declared_value * duty_rate
                            total_duty += calculated_tax
                            cleared_items.append((item.sku, calculated_tax))
                    else:
                        return {'status': 'rejected', 'reason': 'Uninsured parcel'}
            else:
                return {'status': 'rejected', 'reason': 'Empty manifest'}
        else:
            return {'status': 'rejected', 'reason': 'Zero value declaration'}
    else:
        for parcel in shipment.cargo_manifest:
            for item in parcel.contents:
                cleared_items.append((item.sku, 0.0))

    try:
        if total_duty > 0:
            audit_token = compliance_service.submit_manifest(shipment.id, total_duty)
            if audit_token:
                ledger.record_transaction(shipment.account_id, total_duty, audit_token)
                return {'status': 'cleared', 'total_duty': total_duty, 'items': cleared_items}
            return {'status': 'flagged', 'reason': 'Compliance check failed'}
        return {'status': 'cleared', 'total_duty': 0.0, 'items': cleared_items}
    except Exception as error:
        return {'status': 'error', 'message': str(error)}

