                            tariff = item.value * 0.03
                            if item.declared_weight > 500:
                                tariff += 150.0
                        elif item.hs_code_prefix == "85":
                            tariff = item.value * 0.05
                            if item.requires_battery_cert:
                                tariff += 45.0
                        elif item.hs_code_prefix == "29":
                            tariff = item.value * 0.08
                        elif item.hs_code_prefix == "30":
                            tariff = item.value * 0.02
                        elif item.hs_code_prefix == "87":
                            tariff = item.value * 0.10
                        elif item.hs_code_prefix == "90":
                            tariff = item.value * 0.04
                        else:
                            tariff = item.value * 0.12

                        if manifest.freight_class == "air":
