import ast


def find_long_elif_chains(source_code: str, threshold: int = 5):
    class ElifChainVisitor(ast.NodeVisitor):
        def __init__(self):
            self.chains = []

        def visit_If(self, node):
            count = 0
            curr = node
            while (
                curr.orelse
                and len(curr.orelse) == 1
                and isinstance(curr.orelse[0], ast.If)
            ):
                count += 1
                curr = curr.orelse[0]

            if count >= threshold:
                self.chains.append(
                    {
                        "line_number": node.lineno,
                        "elif_count": count,
                        "total_branches": count + 1 + (1 if curr.orelse else 0),
                    }
                )

            self.generic_visit(node)

    tree = ast.parse(source_code)
    visitor = ElifChainVisitor()
    visitor.visit(tree)
    return visitor.chains

