    total_shipping_cost = 0.0

    if shipment.is_active:
        if shipment.dest_country in ["US", "CA", "MX"]:
            if shipment.packages:
                for pkg in shipment.packages:
                    carrier_assigned = False
                    if pkg.weight > 0:
                        for carrier in carriers:
                            if carrier.is_available and carrier.can_handle(pkg.category):
                                if pkg.category == "hazardous":
                                    if carrier.hazmat_certified:
                                        cost = pkg.weight * carrier.base_rate * 1.8
                                    else:
                                        continue
                                elif pkg.category == "perishable":
                                    if pkg.requires_cold_chain and not carrier.has_refrigeration:
                                        continue
                                    else:
                                        cost = pkg.weight * carrier.base_rate * 1.3
                                else:
                                    if pkg.weight > 70:
                                        cost = (pkg.weight * carrier.base_rate) + 50.0
                                    else:
                                        cost = pkg.weight * carrier.base_rate

                                try:
                                    reservation = carrier.reserve_capacity(pkg.id, cost)
                                    if reservation.confirmed:
                                        carrier_assigned = True
                                        total_shipping_cost += cost
                                        allocated_routes.append({"pkg_id": pkg.id, "carrier": carrier.id, "cost": cost})
