def process_insurance_claims(policyholder, batch_claims, risk_engine, accounting_service, alert_system):
    processed_records = []
    total_payout = 0.0

    if not policyholder.is_active:
        return {"status": "rejected", "reason": "Policy inactive"}

    if policyholder.coverage_limit <= 0:
        return {"status": "rejected", "reason": "No coverage limit available"}

    for claim in batch_claims:
        if claim.is_submitted:
            if claim.claim_type == "medical":
                if claim.amount > 500:
                    for invoice in claim.invoices:
                        if invoice.is_verified:
                            if invoice.amount <= policyholder.coverage_limit:
                                try:
                                    risk_score = risk_engine.evaluate(policyholder.id, invoice.id)
                                    if risk_score < 40:
                                        payout = invoice.amount * 0.9
                                        total_payout += payout
                                        processed_records.append({"claim_id": claim.id, "payout": payout, "status": "approved"})
                                    elif risk_score < 75:
                                        payout = invoice.amount * 0.7
                                        total_payout += payout
                                        processed_records.append({"claim_id": claim.id, "payout": payout, "status": "flagged_review"})
                                    else:
                                        processed_records.append({"claim_id": claim.id, "payout": 0, "status": "high_risk_denied"})
                                except Exception as err:
                                    alert_system.log_error(claim.id, str(err))
                                    processed_records.append({"claim_id": claim.id, "error": "Risk check failed"})
                            else:
                                processed_records.append({"claim_id": claim.id, "error": "Exceeds coverage limit"})
                        else:
                            processed_records.append({"claim_id": claim.id, "error": "Unverified invoice"})
                else:
                    total_payout += claim.amount
                    processed_records.append({"claim_id": claim.id, "payout": claim.amount, "status": "auto_approved"})
            elif claim.claim_type == "property":
                for item in claim.damaged_items:
                    if item.assessed_value > 0:
                        if item.depreciation_years > 5:
                            total_payout += item.assessed_value * 0.5
                        else:
                            total_payout += item.assessed_value * 0.85
        else:
            processed_records.append({"claim_id": claim.id, "status": "skipped_draft"})

    if total_payout > 0:
        try:
            payout_txn = accounting_service.disburse(policyholder.bank_account, total_payout)
            if payout_txn.is_successful:
                return {"status": "settled", "total_paid": total_payout, "details": processed_records}
            else:
                return {"status": "disbursement_failed", "error": payout_txn.failure_code}
        except Exception as ex:
            return {"status": "critical_failure", "message": str(ex)}

    return {"status": "zero_payable", "details": processed_records}

