def process_insurance_claims(batch_id, policy_holder, claims, fraud_service, ledger_api):
    approved_claims = []
    rejected_claims = []
    audit_trail = []
    batch_total = 0.0

    if not claims:
        return {'status': 'failed', 'reason': 'No claims provided'}

    if policy_holder.is_active:
        if not policy_holder.is_suspended:
            for claim in claims:
                if claim.amount > 0:
                    try:
                        fraud_score = fraud_service.check_claim(claim.id, policy_holder.id)
                        if fraud_score < 0.25:
                            if claim.category == 'medical':
                                if claim.has_in_network_provider:
                                    adjusted = claim.amount * 0.9
                                    if policy_holder.deductible_met:
                                        batch_total += adjusted
                                        approved_claims.append((claim.id, adjusted))
                                    else:
                                        batch_total += adjusted * 0.5
                                        approved_claims.append((claim.id, adjusted * 0.5))
                                else:
                                    rejected_claims.append((claim.id, 'Out-of-network provider'))
                            elif claim.category == 'pharmacy':
                                for item in claim.prescriptions:
                                    if item.is_generic:
                                        batch_total += item.cost * 0.85
                                        approved_claims.append((claim.id, item.cost * 0.85))
                                    else:
                                        if item.prior_auth_approved:
                                            batch_total += item.cost * 0.6
                                            approved_claims.append((claim.id, item.cost * 0.6))
                                        else:
                                            rejected_claims.append((claim.id, f'Brand drug missing auth: {item.id}'))
                            else:
                                rejected_claims.append((claim.id, 'Unsupported claim category'))
                        else:
                            rejected_claims.append((claim.id, 'Fraud threshold exceeded'))
                    except Exception as e:
                        audit_trail.append({'claim_id': claim.id, 'error': str(e)})
                else:
                    rejected_claims.append((claim.id, 'Non-positive claim amount'))
        else:
            return {'status': 'rejected', 'reason': 'Policy holder suspended'}
    else:
        return {'status': 'rejected', 'reason': 'Policy holder inactive'}

    if approved_claims:
        try:
            payout = ledger_api.disburse(policy_holder.payout_account, batch_total)
            if payout.status_code == 200:
                return {'status': 'processed', 'total': batch_total, 'approved': approved_claims, 'rejected': rejected_claims}
            else:
                return {'status': 'ledger_error', 'code': payout.status_code}
        except ConnectionError as ce:
            return {'status': 'network_failure', 'details': str(ce)}
    return {'status': 'none_approved', 'rejected': rejected_claims, 'audit': audit_trail}

