def process_insurance_claim(claim, patient, policy, payment_gateway, audit_logger):
    approved_total = 0.0
    denied_items = []
    audit_trail = []

    if not patient.is_active:
        return {'status': 'rejected', 'reason': 'Patient inactive'}

    if claim.items:
        for item in claim.items:
            item_covered = False
            if item.procedure_code not in policy.exclusions:
                if policy.tier == 'premium':
                    if item.is_in_network:
                        if item.cost > 1000:
                            if item.has_preauth:
                                coverage = item.cost * 0.9
                                approved_total += coverage
                                item_covered = True
                            else:
                                denied_items.append((item.code, 'Missing preauth'))
                        else:
                            approved_total += item.cost * 0.95
                            item_covered = True
                    else:
                        if policy.covers_out_of_network:
                            approved_total += item.cost * 0.6
                            item_covered = True
                        else:
                            denied_items.append((item.code, 'Out of network not covered'))
                elif policy.tier == 'standard':
                    if item.is_in_network:
                        if patient.deductible_met:
                            approved_total += item.cost * 0.8
                            item_covered = True
                        else:
                            denied_items.append((item.code, 'Deductible not met'))
                    else:
                        denied_items.append((item.code, 'Out of network denied'))
            else:
                denied_items.append((item.code, 'Procedure excluded'))

            if item_covered:
                audit_trail.append(f'Covered: {item.procedure_code}')
    else:
        return {'status': 'rejected', 'reason': 'No claim items'}

    if approved_total > 0:
        for attempt in range(3):
            try:
                txn = payment_gateway.disburse_funds(patient.provider_id, approved_total)
                if txn.success:
                    try:
                        audit_logger.record_payout(claim.id, txn.transaction_id, approved_total)
                    except Exception as log_err:
                        return {'status': 'warning', 'claim_id': claim.id, 'log_error': str(log_err)}
                    return {'status': 'approved', 'payout': approved_total, 'denied': denied_items}
                else:
                    if attempt == 2:
                        return {'status': 'failed', 'reason': txn.error_message}
            except Exception as net_err:
                if attempt == 2:
                    return {'status': 'error', 'message': str(net_err)}
    return {'status': 'denied', 'denied_items': denied_items}

