def process_freight_manifest(shipment, fleet_manager, billing_service, audit_logger):
    total_cost = 0.0
    allocated_vehicles = []
    failed_items = []

    if not shipment.is_cancelled:
        if shipment.priority_level in ['EXPRESS', 'CRITICAL']:
            if shipment.destinations:
                for dest in shipment.destinations:
                    try:
                        available_trucks = fleet_manager.get_available_units(dest.zone_id)
                        for truck in available_trucks:
                            if not dest.requires_cold_chain or truck.has_refrigeration:
                                for cargo in dest.cargo_manifest:
                                    if cargo.weight_kg <= truck.remaining_capacity:
                                        if cargo.is_hazardous:
                                            if truck.driver_hazmat_certified:
                                                truck.remaining_capacity -= cargo.weight_kg
                                                surcharge = cargo.weight_kg * 4.50
                                                total_cost += cargo.base_rate + surcharge
                                                truck.loaded_items.append(cargo.id)
                                            else:
                                                failed_items.append((cargo.id, "NO_HAZMAT_DRIVER"))
                                        else:
                                            truck.remaining_capacity -= cargo.weight_kg
                                            total_cost += cargo.base_rate
                                            truck.loaded_items.append(cargo.id)
                                    else:
                                        failed_items.append((cargo.id, "CAPACITY_EXCEEDED"))
                                if truck.loaded_items:
                                    allocated_vehicles.append(truck.id)
                                    fleet_manager.reserve_vehicle(truck.id)
                    except Exception as err:
                        audit_logger.log_error(f"Routing failure zone {dest.zone_id}: {str(err)}")
                        return {"status": "FAILED", "stage": "FLEET_ALLOCATION", "error": str(err)}
            else:
                return {"status": "REJECTED", "reason": "NO_DESTINATIONS"}
        else:
            for dest in shipment.destinations:
                for cargo in dest.cargo_manifest:
                    if cargo.is_hazardous:
                        return {"status": "REJECTED", "reason": "STANDARD_TIER_NO_HAZMAT"}
                    total_cost += cargo.base_rate * 0.95

        try:
            invoice = billing_service.generate_invoice(shipment.client_id, total_cost)
            if invoice.is_approved:
                return {"status": "SUCCESS", "vehicles": allocated_vehicles, "failures": failed_items, "cost": total_cost}
            return {"status": "HELD", "reason": "CREDIT_LIMIT_EXCEEDED"}
        except Exception as err:
            return {"status": "FAILED", "stage": "BILLING", "error": str(err)}
    return {"status": "ABORTED", "reason": "MANIFEST_CANCELLED"}

