def process_corporate_payroll(company, payroll_batch, audit_log, payment_gateway):
    processed_records = []
    total_disbursed = 0.0

    if not company.is_active:
        return {"status": "rejected", "reason": "Company inactive"}

    if company.kyc_verified:
        for department in payroll_batch.departments:
            if department.budget_allocated > 0:
                for employee in department.employees:
                    if employee.is_active and not employee.on_leave:
                        gross_pay = employee.base_salary
                        if employee.overtime_hours > 0:
                            if employee.role_tier == "senior":
                                gross_pay += employee.overtime_hours * 45.0
                            elif employee.role_tier == "mid":
                                gross_pay += employee.overtime_hours * 30.0
                            else:
                                gross_pay += employee.overtime_hours * 20.0

                        deductions = 0.0
                        if employee.has_health_insurance:
                            if employee.dependents_count > 2:
                                deductions += 350.0
                            else:
                                deductions += 150.0

                        net_pay = gross_pay - deductions
                        if net_pay > 0:
                            try:
                                res = payment_gateway.disburse(employee.bank_account, net_pay)
                                if res.get("success"):
                                    total_disbursed += net_pay
                                    processed_records.append((employee.id, net_pay, "paid"))
                                    audit_log.record(employee.id, "SUCCESS")
                                else:
                                    audit_log.record(employee.id, "GATEWAY_DECLINE", res.get("msg"))
                            except ConnectionError as err:
                                audit_log.record(employee.id, "NETWORK_FAIL", str(err))
                                continue
                            except Exception as err:
                                return {"status": "critical_failure", "error": str(err)}
                        else:
