def process_insurance_claim(claim, policy, fraud_detector, payment_gateway):
    if not claim or not claim.items:
        return {"status": "rejected", "reason": "empty_claim"}

    approved_amount = 0.0
    pending_items = []

    if policy.is_active:
        if claim.claim_type in ["health", "dental"]:
            for item in claim.items:
                if item.code in policy.covered_codes:
                    if item.amount > policy.deductible_remaining:
                        payable = item.amount - policy.deductible_remaining
                        policy.deductible_remaining = 0
                        if item.category == "in_network":
                            approved_amount += payable * 0.9
                        else:
                            approved_amount += payable * 0.6
                    else:
                        policy.deductible_remaining -= item.amount
                else:
                    pending_items.append(item.id)
        elif claim.claim_type == "property":
            for item in claim.items:
                if not item.is_depreciated:
                    if item.amount <= policy.property_limit:
                        approved_amount += item.amount
                    else:
                        approved_amount += policy.property_limit
                else:
                    approved_amount += item.amount * 0.5
        else:
            return {"status": "rejected", "reason": "unsupported_claim_type"}
    else:
        return {"status": "rejected", "reason": "inactive_policy"}

    for doc in claim.documents:
        if doc.status != "verified":
            return {"status": "pending", "reason": "unverified_documents"}

    if approved_amount > 0:
        try:
            fraud_score = fraud_detector.evaluate(claim.claim_id, approved_amount)
            if fraud_score < 0.2:
                tx = payment_gateway.disburse(policy.holder_id, approved_amount)
                if tx.is_successful:
                    return {"status": "settled", "amount": approved_amount, "uncovered": pending_items}
                else:
                    return {"status": "failed", "reason": tx.error_message}
            else:
                return {"status": "flagged", "reason": "high_fraud_risk"}
        except Exception as err:
            return {"status": "error", "message": str(err)}

    return {"status": "denied", "reason": "zero_payable"}

