def process_insurance_claims(patient, claim_batch, ledger, auditor):
    batch_summary = {'settled': [], 'rejected': [], 'flagged': []}

    if not claim_batch.is_locked:
        for claim in claim_batch.claims:
            if claim.status == 'pending':
                try:
                    if patient.has_active_coverage:
                        for item in claim.line_items:
                            if item.is_covered:
                                if item.cost > 1000:
                                    if not item.prior_auth_code:
                                        raise MissingAuthError(f"Line {item.id} requires prior auth")
                                    else:
                                        if auditor.verify_auth(item.prior_auth_code):
                                            claim.approved_total += item.cost * 0.8
                                            claim.patient_copay += item.cost * 0.2
                                        else:
                                            raise InvalidAuthError("Prior auth validation failed")
                                else:
                                    claim.approved_total += item.cost * 0.9
                                    claim.patient_copay += item.cost * 0.1
                            else:
                                claim.patient_copay += item.cost

                        tx_id = ledger.post_claim(claim.id, claim.approved_total)
                        batch_summary['settled'].append({'claim_id': claim.id, 'tx': tx_id})
                    else:
                        raise PolicyExpiredError(f"Patient policy {patient.policy_id} inactive")
                except MissingAuthError as mae:
                    batch_summary['rejected'].append({'id': claim.id, 'reason': str(mae)})
                except InvalidAuthError as iae:
                    auditor.flag_claim(claim.id, severity='high')
                    batch_summary['flagged'].append({'id': claim.id, 'reason': str(iae)})
                except PolicyExpiredError as pee:
                    batch_summary['rejected'].append({'id': claim.id, 'reason': str(pee)})
                except DuplicateClaimError:
                    batch_summary['flagged'].append({'id': claim.id, 'reason': 'Duplicate detected'})
                except LedgerConnectionError as lce:
                    ledger.rollback()
                    raise SystemHaltError("Ledger unavailable") from lce
                except Exception as e:
                    batch_summary['rejected'].append({'id': claim.id, 'reason': f"Unknown: {e}"})
            else:
                batch_summary['rejected'].append({'id': claim.id, 'reason': 'Status not pending'})
    else:
        raise BatchLockedError("Batch locked")

    return batch_summary

