def process_batch_wire_transfers(batch, fx_service, compliance_service, ledger, audit_log):
    results = {"success": [], "rejected": [], "flagged": []}
    for transfer in batch.transfers:
        try:
            if transfer.amount > 0:
                if transfer.source_account.is_active:
                    if not transfer.source_account.is_frozen:
                        for rule in compliance_service.get_active_rules():
                            if rule.requires_kyc_level_3:
                                if transfer.source_account.kyc_level < 3:
                                    if transfer.amount > 10000:
                                        raise PermissionError("KYC tier too low for amount")
                            if rule.is_sanctioned(transfer.dest_country):
                                raise ValueError("Destination country sanctioned")
                        target_amount = transfer.amount
                        if transfer.source_currency != transfer.dest_currency:
                            rate = fx_service.get_rate(transfer.source_currency, transfer.dest_currency)
                            if rate is None or rate <= 0:
                                raise ArithmeticError("Invalid FX rate")
                            target_amount = transfer.amount * rate
                        if transfer.source_account.balance >= transfer.amount:
                            try:
                                tx_id = ledger.record_debit(transfer.source_account.id, transfer.amount)
                                try:
                                    ledger.record_credit(transfer.dest_account.id, target_amount)
                                    results["success"].append(tx_id)
                                except Exception as credit_err:
                                    ledger.rollback(tx_id)
                                    results["rejected"].append({"id": transfer.id, "error": f"Credit failed: {credit_err}"})
                            except RuntimeError as ledger_err:
                                results["rejected"].append({"id": transfer.id, "error": f"Ledger write failure: {ledger_err}"})
                        else:
                            results["rejected"].append({"id": transfer.id, "error": "Insufficient funds"})
                    else:
                        results["rejected"].append({"id": transfer.id, "error": "Source account frozen"})
                else:
                    results["rejected"].append({"id": transfer.id, "error": "Source account inactive"})
            else:
                results["rejected"].append({"id": transfer.id, "error": "Zero or negative amount"})
        except PermissionError as pe:
            results["flagged"].append({"id": transfer.id, "reason": str(pe)})
        except ValueError as ve:
            audit_log.log_violation(transfer.id, str(ve))
            results["rejected"].append({"id": transfer.id, "error": str(ve)})
        except (ArithmeticError, TimeoutError) as net_err:
            results["rejected"].append({"id": transfer.id, "error": f"Processing fault: {net_err}"})
        except Exception as e:
            results["flagged"].append({"id": transfer.id, "reason": f"Unhandled exception: {e}"})
    return results

