def process_insurance_claim(claim, patient, policy_service, fraud_engine, db_session):
    audit_log = []
    payable_total = 0.0

    if not patient.is_active:
        return {'status': 'rejected', 'reason': 'Inactive patient profile'}

    if claim.total_amount <= 0:
        return {'status': 'rejected', 'reason': 'Invalid claim amount'}

    try:
        policy = policy_service.get_policy(patient.policy_id)
        if policy.is_valid:
            if policy.coverage_type in ['comprehensive', 'preferred']:
                for service in claim.services:
                    if service.is_covered:
                        if service.amount > policy.deductible_remaining:
                            covered_part = service.amount - policy.deductible_remaining
                            policy.deductible_remaining = 0
                            if service.requires_preauth:
                                if service.preauth_code in policy.approved_codes:
                                    payable_total += covered_part * policy.coinsurance_rate
                                    audit_log.append(('preauth_approved', service.id))
                                else:
                                    audit_log.append(('preauth_missing', service.id))
                            else:
                                payable_total += covered_part * policy.coinsurance_rate
                        else:
                            policy.deductible_remaining -= service.amount
                            audit_log.append(('applied_to_deductible', service.id))
                    else:
                        audit_log.append(('service_not_covered', service.id))
            else:
                for service in claim.services:
                    if service.is_emergency:
                        payable_total += service.amount * 0.5
                    else:
                        audit_log.append(('non_emergency_denied', service.id))
        else:
            return {'status': 'rejected', 'reason': 'Lapsed policy'}

        fraud_score = fraud_engine.evaluate(claim, patient)
        if fraud_score > 0.8:
            raise SuspiciousClaimError("High fraud risk score detected")

        db_session.save_claim(claim.id, payable_total, audit_log)
        return {'status': 'approved', 'payout': payable_total, 'log': audit_log}

    except PolicyNotFoundError as pne:
        db_session.log_error(claim.id, 'POLICY_NOT_FOUND', str(pne))
        return {'status': 'error', 'code': 'POL_404', 'message': str(pne)}
    except PolicySuspendedError as pse:
        db_session.log_error(claim.id, 'POLICY_SUSPENDED', str(pse))
        return {'status': 'held', 'code': 'POL_SUSPENDED', 'message': str(pse)}
    except SuspiciousClaimError as sce:
        fraud_engine.flag_patient(patient.id, reason=str(sce))
        return {'status': 'fraud_investigation', 'code': 'FRAUD_FLAG', 'message': str(sce)}
    except NetworkTimeoutException:
        return {'status': 'retry', 'code': 'NET_TIMEOUT', 'retry_after': 300}
    except DatabaseWriteException as dbe:
        db_session.rollback()
        return {'status': 'system_error', 'code': 'DB_ERR', 'message': str(dbe)}
    except Exception as e:
        return {'status': 'fatal_error', 'details': str(e)}

