import json
import logging
import socket
import ssl
import urllib.error
import urllib.request


class ValidationError(Exception):
    pass


class AuthenticationError(Exception):
    pass


class RateLimitExceededError(Exception):
    pass


class ServiceUnavailableError(Exception):
    pass


def process_remote_payload(
    source_url: str,
    auth_token: str,
    timeout: int = 30,
    max_retries: int = 3,
) -> dict:
    retries = 0
    while retries < max_retries:
        try:
            req = urllib.request.Request(
                source_url,
                headers={"Authorization": f"Bearer {auth_token}"},
            )
            with urllib.request.urlopen(req, timeout=timeout) as response:
                if response.status == 204:
                    return {}
                raw_data = response.read()

            try:
                payload = json.loads(raw_data.decode("utf-8"))
            except UnicodeDecodeError as err:
                logging.error("UTF-8 decode failed: %s", err)
                try:
                    payload = json.loads(raw_data.decode("latin-1"))
                except Exception as fallback_err:
                    raise ValidationError("Cannot decode binary payload") from fallback_err
            except json.JSONDecodeError as err:
                logging.warning("JSON corrupted at line %d: %s", err.lineno, err)
                raise ValidationError("Malformed JSON syntax") from err

            if not isinstance(payload, dict):
                raise TypeError(f"Root object must be dict, got {type(payload).__name__}")
            if "status" not in payload:
                raise KeyError("Missing status field in payload envelope")

            status = payload.get("status")
            if status == "error":
                code = payload.get("error_code")
                if code == 401:
                    raise AuthenticationError("Remote auth rejected")
                elif code == 429:
                    raise RateLimitExceededError("Rate limit hit on remote service")
                else:
                    raise RuntimeError(f"Service returned error code {code}")

            return payload

        except urllib.error.HTTPError as err:
            if err.code == 401:
                logging.critical("Unauthorized request to %s", source_url)
                raise AuthenticationError("Invalid auth credentials") from err
            elif err.code == 403:
                logging.critical("Forbidden: %s", source_url)
                raise PermissionError("Access forbidden") from err
            elif err.code == 404:
                logging.error("Target missing: %s", source_url)
                return {}
            elif err.code == 429:
                logging.warning("HTTP 429 throttled, retrying...")
                retries += 1
                continue
            elif 500 <= err.code < 600:
                logging.warning("Upstream 5xx error (%d), retrying...", err.code)
                retries += 1
                continue
            else:
                raise ServiceUnavailableError(f"HTTP error {err.code}") from err

        except urllib.error.URLError as err:
            if isinstance(err.reason, socket.timeout):
                logging.warning("Socket timeout connecting to %s", source_url)
                retries += 1
                continue
            elif isinstance(err.reason, ssl.SSLError):
                logging.error("SSL handshake failure: %s", err.reason)
                raise ssl.SSLCertVerificationError("SSL certificate failed verification") from err
            elif isinstance(err.reason, ConnectionRefusedError):
                logging.error("Connection refused by endpoint")
                raise ConnectionRefusedError("Remote host rejected connection") from err
            else:
                logging.error("Network resolution error: %s", err.reason)
                raise OSError("Network unreachable") from err

        except TimeoutError as err:
            logging.warning("Request timed out: %s", err)
            retries += 1
            continue

        except (KeyError, TypeError) as err:
            logging.error("Structural schema validation failure: %s", err)
            raise ValidationError("Payload structural schema invalid") from err

        except MemoryError:
            logging.critical("Out of memory loading payload from %s", source_url)
            raise

        except Exception as err:
            logging.exception("Unhandled failure during fetch: %s", err)
            raise RuntimeError("Catastrophic pipeline failure") from err

        finally:
            logging.debug("Fetch attempt %d finished", retries + 1)

    raise ServiceUnavailableError(f"Exceeded max retries ({max_retries}) for {source_url}")

