        except HTTPError as err:
            logger.error("Upstream validation proxy HTTP error %d: %s", err.code, err.reason)
            return {"status": "upstream_error", "code": err.code}
        except URLError as err:
            logger.error("Network unreachable during remote verification: %s", err.reason)
            return {"status": "network_unreachable", "reason": str(err.reason)}
        except Exception as err:
            if db_session:
                try:
                    db_session.rollback()
                except Exception as rollback_err:
                    logger.critical("Rollback failure following fatal query error: %s", rollback_err)
            logger.exception("Unrecoverable database failure encountered: %s", err)
            raise DatabaseTransactionError(f"Fatal error while recording transaction: {err}") from err
        finally:
            if os.path.exists(cache_path):
                try:
                    os.remove(cache_path)
                except OSError as cleanup_err:
                    logger.warning("Failed to remove temporary cache file %s: %s", cache_path, cleanup_err)

    return {"status": "success", "record_id": record_id, "processed": True}

