            return {"status": "error", "code": 502, "message": "Protocol error"}
        except ConnectionResetError as err:
            logging.warning("Connection reset by peer: %s", err)
            retry_count += 1
        except DatabaseConnectionError as err:
            logging.critical("Database link dropped: %s", err)
