                logger.warning("Remote server down (status %s), retry suggested", err.code)
                return False
            else:
                logger.error("HTTP failure: %s", err)
                raise
        except urllib.error.URLError as err:
            if isinstance(err.reason, socket.timeout):
                logger.error("Connection timed out reaching %s", source_url)
                raise TimeoutError("Network timeout") from err
            elif isinstance(err.reason, ssl.SSLError):
                logger.critical("TLS certificate validation failed: %s", err.reason)
                raise ssl.SSLCertVerificationError("Untrusted certificate") from err
            else:
                logger.error("Network unreachable: %s", err.reason)
                raise ConnectionError("Host resolution failure") from err
        except socket.timeout:
            logger.error("Socket level timeout")
            raise TimeoutError("Socket unresponsive")
        else:
            try:
                payload = json.loads(raw_data)
            except json.JSONDecodeError as json_err:
                logger.error("Malformed JSON received: %s", json_err)
                raise ValueError("Corrupt body data") from json_err

        if not isinstance(payload, dict):
            raise TypeError("Root payload structure must be JSON object")

        if "items" not in payload:
