            logger.error("Cannot write cache to %s: %s", local_cache_path, perm_err)
            raise
        except (FileNotFoundError, NotADirectoryError) as path_err:
            logger.error("Cache directory does not exist: %s", path_err)
            os.makedirs(os.path.dirname(local_cache_path), exist_ok=True)
            with open(local_cache_path, "w", encoding="utf-8") as cache_file:
                json.dump(payload, cache_file)
        except OSError as os_err:
            logger.critical("Disk I/O error during persistence: %s", os_err)
            raise

    except (TypeError, KeyError) as schema_err:
        logger.error("Validation error: %s", schema_err)
        raise ValidationError(f"Invalid schema: {schema_err}") from schema_err
    except (TimeoutError, ConnectionError) as net_err:
