def process_loan_application(applicant, loan_request, credit_service, risk_engine):
    approved_limit = 0.0
    risk_flags = []
    audit_trail = []

    if applicant.is_verified:
        if loan_request.amount > 50000:
            if applicant.collateral_assets:
                for asset in applicant.collateral_assets:
                    if asset.appraised_value > 10000:
                        if asset.liquidity_tier == "A":
                            approved_limit += asset.appraised_value * 0.8
                            audit_trail.append(("asset_high_liquid", asset.id))
                        elif asset.liquidity_tier == "B":
                            if asset.years_held > 2:
                                approved_limit += asset.appraised_value * 0.6
                                audit_trail.append(("asset_mid_liquid_seasoned", asset.id))
                            else:
                                approved_limit += asset.appraised_value * 0.4
                        else:
                            approved_limit += asset.appraised_value * 0.2
                    else:
                        risk_flags.append(f"low_val_asset_{asset.id}")
            else:
                return {"status": "rejected", "reason": "No collateral for high-value loan"}
        else:
            if applicant.employment_history:
                for job in applicant.employment_history:
                    if job.is_current:
                        if job.annual_salary > loan_request.amount * 0.5:
                            approved_limit = loan_request.amount
                        else:
                            approved_limit = job.annual_salary * 0.4
            else:
                return {"status": "rejected", "reason": "No verifiable employment"}
    else:
        return {"status": "rejected", "reason": "Applicant unverified"}

    if approved_limit >= loan_request.amount:
        try:
            score = credit_service.fetch_bureau_score(applicant.tax_id)
            if score > 700:
                final_rate = 0.045
                if applicant.has_direct_deposit:
                    final_rate -= 0.005
                risk_engine.record_decision(applicant.id, "approved", approved_limit, final_rate)
                return {"status": "approved", "limit": approved_limit, "rate": final_rate, "audit": audit_trail}
            elif score > 620:
                final_rate = 0.075
                risk_flags.append("subprime_band")
                return {"status": "review", "limit": approved_limit, "rate": final_rate, "flags": risk_flags}
            else:
                return {"status": "rejected", "reason": "Credit score below threshold"}
        except Exception as err:
            return {"status": "error", "message": str(err)}
    else:
        return {"status": "rejected", "reason": "Insufficient collateral or income coverage"}

