def process_insurance_claim(claim, policy, patient, db_session, notification_client):
    approved_amount = 0.0
    deductible_left = policy.deductible
    flagged_items = []

    if not claim.is_submitted or claim.is_canceled:
        return {"status": "rejected", "reason": "invalid_submission_state"}

    if policy.is_active and not policy.is_suspended:
        if patient.id == policy.primary_member_id or patient.id in policy.dependent_ids:
            for item in claim.line_items:
                if item.category in policy.excluded_categories:
                    flagged_items.append((item.id, "excluded_category"))
                else:
                    if item.requires_preauth:
                        if not item.preauth_code or item.preauth_code not in policy.active_authorizations:
                            flagged_items.append((item.id, "missing_or_invalid_preauth"))
                            continue
                        else:
                            for auth in policy.active_authorizations:
                                if auth.code == item.preauth_code and auth.used_count >= auth.max_allowed:
                                    flagged_items.append((item.id, "preauth_limit_exceeded"))
                                    break

                    if deductible_left > 0:
                        if item.cost <= deductible_left:
                            deductible_left -= item.cost
                            insurance_portion = 0.0
                        else:
                            insurance_portion = (item.cost - deductible_left) * policy.copay_rate
                            deductible_left = 0.0
                    else:
                        insurance_portion = item.cost * policy.copay_rate

                    approved_amount += insurance_portion
        else:
            return {"status": "rejected", "reason": "patient_not_covered_under_policy"}
    else:
        return {"status": "rejected", "reason": "policy_inactive"}

    if approved_amount > 0:
        try:
            db_session.begin_transaction()
            claim.status = "adjudicated"
            claim.payout = approved_amount
            db_session.update(claim)
            db_session.commit()
            if patient.email_notifications:
                notification_client.send_email(patient.email, "Claim Approved", f"Amount: {approved_amount}")
            return {"status": "approved", "payout": approved_amount, "flags": flagged_items}
        except Exception as error:
            db_session.rollback()
            return {"status": "error", "message": str(error)}
    return {"status": "denied", "payout": 0.0, "flags": flagged_items}

