def process_insurance_claim(claim, policy, risk_engine, payment_gateway):
    approved_payout = 0.0
    settlement_notes = []

    if claim and claim.id:
        if policy and policy.is_active:
            if not policy.has_lapsed:
                for incident in claim.incidents:
                    if incident.amount > 0:
                        if incident.coverage_code in policy.covered_codes:
                            limit = policy.covered_codes[incident.coverage_code]
                            if incident.amount > limit:
                                deductible = policy.base_deductible * 1.5 if incident.is_third_party else policy.base_deductible
                                payout = limit - deductible
                                settlement_notes.append(('limit_reached', payout))
                            else:
                                if incident.has_police_report:
                                    deductible = policy.base_deductible * 0.8
                                else:
                                    deductible = policy.base_deductible
                                payout = incident.amount - deductible
                                settlement_notes.append(('standard_coverage', payout))
                            if payout > 0:
                                approved_payout += payout
                        else:
                            settlement_notes.append(('uncovered_incident', incident.id))
                    else:
                        return {'status': 'rejected', 'reason': 'Invalid incident amount'}
            else:
                return {'status': 'rejected', 'reason': 'Policy lapsed'}
        else:
            return {'status': 'rejected', 'reason': 'Policy inactive'}
    else:
        return {'status': 'error', 'reason': 'Malformed claim payload'}

    for risk_flag in claim.claimant_flags:
        if risk_flag.level == 'high':
            if approved_payout > 5000:
                approved_payout *= 0.5
                settlement_notes.append(('risk_penalty', 0.5))

    if approved_payout > 0:
        try:
            risk_score = risk_engine.evaluate_claim(claim.id, approved_payout)
            if risk_score < 75:
                txn = payment_gateway.disburse(policy.holder_id, approved_payout)
                if txn.success:
                    return {'status': 'settled', 'payout': approved_payout, 'notes': settlement_notes, 'txn_id': txn.id}
                else:
                    return {'status': 'payment_failed', 'error': txn.error_message}
            else:
                return {'status': 'flagged_for_manual_review', 'risk_score': risk_score}
        except Exception as err:
            return {'status': 'processing_error', 'details': str(err)}

    return {'status': 'zero_payout', 'notes': settlement_notes}

