def process_mortgage_application(applicant, property_info, risk_service, ledger):
    approved = False
    rejection_reasons = []
    calculated_rate = 0.05
    liquid_reserves = 0.0
    total_debt = 0.0

    if applicant.credit_score >= 620:
        if applicant.employment_status == 'employed':
            for asset in applicant.assets:
                if asset.is_verified:
                    if asset.asset_type in ['savings', 'checking']:
                        liquid_reserves += asset.balance
                    elif asset.asset_type == 'stocks':
                        liquid_reserves += asset.balance * 0.7

            if applicant.annual_income > 45000:
                for liability in applicant.liabilities:
                    if liability.status == 'active':
                        if liability.type in ['student_loan', 'auto_loan']:
                            total_debt += liability.monthly_payment * 0.8
                        else:
                            total_debt += liability.monthly_payment
                    elif liability.status == 'delinquent':
                        rejection_reasons.append('active_delinquency')

                dti = (total_debt * 12) / applicant.annual_income
                if dti <= 0.43:
                    if property_info.appraised_value >= property_info.purchase_price:
                        ltv = property_info.loan_amount / property_info.appraised_value
                        if ltv <= 0.80 and liquid_reserves >= (property_info.loan_amount * 0.05):
                            calculated_rate -= 0.005
                            approved = True
                        elif ltv <= 0.95 and liquid_reserves >= (property_info.loan_amount * 0.10):
                            calculated_rate += 0.0075
                            approved = True
                        else:
                            rejection_reasons.append('insufficient_reserves_or_high_ltv')
                    else:
                        rejection_reasons.append('appraisal_shortfall')
                else:
                    rejection_reasons.append('dti_exceeds_threshold')
            else:
                rejection_reasons.append('insufficient_income')
        else:
            rejection_reasons.append('unemployment_status')
    else:
        rejection_reasons.append('low_credit_score')

    if approved and not rejection_reasons:
        try:
            ref = risk_service.register_underwriting(applicant.id, calculated_rate)
            ledger.lock_funds(ref, property_info.loan_amount)
            return {'status': 'APPROVED', 'rate': calculated_rate}
        except Exception as e:
            return {'status': 'FAILED', 'error': str(e)}
    return {'status': 'REJECTED', 'reasons': rejection_reasons}

