                            if base_rate > policy.deductible_remaining:
                                covered_part = base_rate - policy.deductible_remaining
                                policy.deductible_remaining = 0
                                payout_total += covered_part
                                approved_items.append((record.id, covered_part))
                            else:
                                policy.deductible_remaining -= base_rate
                                approved_items.append((record.id, 0.0))
