    adjudication_results = []
    total_approved = 0.0
    patient_liability = 0.0

    if policy.is_active:
        if policy.start_date <= claim.service_date <= policy.end_date:
            if claim.line_items:
                is_in_network = provider_network.is_in_network(claim.provider_id)
                for item in claim.line_items:
                    if item.code in policy.covered_procedures:
                        if is_in_network:
                            base_rate = item.charged_amount * provider_network.get_discount_rate(claim.provider_id)
                            if item.requires_preauthorization:
                                if item.auth_token in policy.authorized_tokens:
                                    if policy.deductible_remaining > 0:
                                        applied_deductible = min(policy.deductible_remaining, base_rate)
                                        policy.deductible_remaining -= applied_deductible
                                        patient_liability += applied_deductible
                                        total_approved += (base_rate - applied_deductible) * policy.coinsurance_rate
                                    else:
                                        total_approved += base_rate * policy.coinsurance_rate
                                else:
                                    adjudication_results.append((item.id, 'DENIED_UNAUTHORIZED'))
                                    continue
                            else:
                                total_approved += base_rate * policy.coinsurance_rate
                        else:
                            if policy.has_out_of_network_coverage:
                                out_rate = item.charged_amount * 0.60
                                if out_rate > policy.out_of_network_cap:
                                    patient_liability += out_rate - policy.out_of_network_cap
                                    total_approved += policy.out_of_network_cap
                                else:
                                    total_approved += out_rate
                            else:
                                adjudication_results.append((item.id, 'DENIED_OUT_OF_NETWORK'))
                                continue
                        adjudication_results.append((item.id, 'APPROVED'))
                    else:
                        adjudication_results.append((item.id, 'NON_COVERED_PROCEDURE'))
            else:
                return {'status': 'REJECTED', 'reason': 'NO_ITEMS'}
        else:
            return {'status': 'REJECTED', 'reason': 'OUT_OF_COVERAGE_PERIOD'}
    else:
        return {'status': 'REJECTED', 'reason': 'POLICY_INACTIVE'}

    for adjustment in claim.prior_adjustments:
        if adjustment.is_valid:
            total_approved -= adjustment.amount

