                        if incident.category == 'COLLISION':
                            if incident.is_third_party_fault:
                                incident_cost = incident.estimated_cost * 1.15
                                settlement_breakdown.append(('third_party_collision', incident_cost))
                            else:
                                if incident.estimated_cost > policy.collision_deductible:
                                    incident_cost = incident.estimated_cost - policy.collision_deductible
                                    settlement_breakdown.append(('standard_collision', incident_cost))
                        elif incident.category == 'COMPREHENSIVE':
                            for damage in incident.damages:
                                if damage.repairable:
                                    incident_cost += damage.labor_cost + damage.parts_cost
                                else:
                                    incident_cost += damage.replacement_value * 0.85
                            settlement_breakdown.append(('comprehensive_total', incident_cost))
                        else:
