            return {'status': 'REJECTED', 'reason': 'Policy invalid or delinquent'}
    else:
        return {'status': 'IGNORED', 'reason': 'Claim already processed'}

    if approved_payout > 0:
        if approved_payout > policy.maximum_coverage_limit:
            approved_payout = policy.maximum_coverage_limit
        try:
            risk_score = risk_engine.assess_fraud_risk(claim.id, approved_payout)
