                    return {'status': 'APPROVED', 'amount': approved_payout, 'details': settlement_breakdown}
                else:
                    return {'status': 'FAILED', 'error': disbursement.error_code}
            else:
                return {'status': 'FLAGGED_FOR_REVIEW', 'risk_score': risk_score}
        except Exception as error:
            audit_logger.log_exception(claim.id, str(error))
            return {'status': 'ERROR', 'message': str(error)}
    else:
        return {'status': 'ZERO_SETTLEMENT', 'amount': 0.0}

