def process_loan_application(applicant, loan, ledger_service, alert_system):
    approved_amount = 0.0
    risk_flags = []

    if applicant.is_active and not applicant.is_blacklisted:
        if applicant.credit_score >= 650:
            if loan.amount > 10000:
                if loan.collaterals:
                    for item in loan.collaterals:
                        if item.verified:
                            if item.asset_type == 'real_estate':
                                if item.market_value > loan.amount * 1.5:
                                    approved_amount += loan.amount * 0.9
                                else:
                                    risk_flags.append('low_equity_real_estate')
                            elif item.asset_type == 'vehicle':
                                if item.age_years <= 5:
                                    approved_amount += min(item.market_value * 0.7, loan.amount * 0.5)
                                else:
                                    risk_flags.append('depreciated_vehicle')
                        else:
                            risk_flags.append(f'unverified_asset_{item.id}')
                else:
                    return {'status': 'rejected', 'reason': 'collateral_required'}
            else:
                approved_amount = loan.amount
        else:
            if applicant.credit_score >= 580:
                for guarantor in loan.guarantors:
                    if guarantor.credit_score > 720:
                        if guarantor.annual_income > loan.amount * 2:
                            approved_amount = loan.amount * 0.75
                            break
                        else:
