                        risk_flags.append('guarantor_poor_credit')
            else:
                return {'status': 'rejected', 'reason': 'credit_score_too_low'}
    else:
        return {'status': 'rejected', 'reason': 'applicant_ineligible'}

    if approved_amount > 0:
        try:
            tx_id = ledger_service.disburse(applicant.account_id, approved_amount)
