            else:
                return {'status': 'error', 'reason': 'disbursement_empty_tx'}
        except Exception as e:
            alert_system.log_failure(applicant.id, str(e))
            return {'status': 'failed', 'error': str(e)}

    return {'status': 'rejected', 'flags': risk_flags}

