import ast
import os
from typing import List, Tuple


def calculate_cyclomatic_complexity(node: ast.AST) -> int:
    complexity = 1
    for child in ast.walk(node):
        if isinstance(
            child,
            (
                ast.If,
                ast.While,
                ast.For,
                ast.AsyncFor,
                ast.ExceptHandler,
                ast.With,
                ast.AsyncWith,
                ast.Assert,
                ast.comprehension,
            ),
        ):
            complexity += 1
        elif isinstance(child, ast.BoolOp):
            complexity += len(child.values) - 1
    return complexity


def find_most_complex_functions(
    codebase_path: str, top_n: int = 10
) -> List[Tuple[str, str, int]]:
    """Scan directory, measure cyclomatic complexity of Python functions, return highest."""
    results = []
    for root, _, files in os.walk(codebase_path):
        for file in files:
            if not file.endswith(".py"):
                continue
            file_path = os.path.join(root, file)
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    tree = ast.parse(f.read(), filename=file_path)
            except (SyntaxError, UnicodeDecodeError, OSError):
                continue

            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    score = calculate_cyclomatic_complexity(node)
                    results.append((file_path, node.name, score))

    results.sort(key=lambda x: x[2], reverse=True)
    return results[:top_n]

