import ast
import os
from typing import List, Tuple


class ComplexityVisitor(ast.NodeVisitor):
    def __init__(self):
        self.complexity = 1

    def visit_If(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_For(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_AsyncFor(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_While(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_ExceptHandler(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_BoolOp(self, node):
        self.complexity += len(node.values) - 1
        self.generic_visit(node)

    def visit_Match(self, node):
        self.complexity += len(node.cases)
        self.generic_visit(node)


def find_most_complex_functions(
    codebase_path: str, top_n: int = 10
) -> List[Tuple[str, str, int, int]]:
    """Scan codebase and return most complex functions based on cyclomatic complexity."""
    results = []

    for root, _, files in os.walk(codebase_path):
        for file in files:
            if not file.endswith(".py"):
                continue

            filepath = os.path.join(root, file)
            try:
                with open(filepath, "r", encoding="utf-8", errors="ignore") as f:
                    tree = ast.parse(f.read(), filename=filepath)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    visitor = ComplexityVisitor()
                    for child in node.body:
                        visitor.visit(child)
                    results.append((node.name, filepath, node.lineno, visitor.complexity))

    results.sort(key=lambda item: item[3], reverse=True)
    return results[:top_n]

