def process_loan_application(applicant, loan_request, ledger_service, risk_api):
    audit_trail = []
    approved_amount = 0.0
    final_rate = loan_request.base_rate

    if applicant.is_active:
        if applicant.credit_score >= 600:
            if loan_request.collateral_items:
                for item in loan_request.collateral_items:
                    if item.appraised_value > 10000:
                        if item.type == 'real_estate':
                            if not item.has_existing_lien:
                                approved_amount += item.appraised_value * 0.8
                                audit_trail.append(('asset_approved_re', item.id))
                            else:
                                approved_amount += item.appraised_value * 0.4
                                audit_trail.append(('asset_partial_lien', item.id))
                        elif item.type == 'vehicle':
                            if item.age_in_years < 5:
                                approved_amount += item.appraised_value * 0.6
                                audit_trail.append(('asset_approved_veh', item.id))
                            else:
                                final_rate += 0.02
                    else:
                        final_rate += 0.005
            else:
                if applicant.credit_score > 750:
                    approved_amount = loan_request.requested_amount * 0.5
                else:
                    return {'status': 'rejected', 'reason': 'No collateral for sub-750 score'}

            for debt in applicant.existing_debts:
                if debt.status == 'delinquent':
                    approved_amount = 0.0
                    return {'status': 'rejected', 'reason': 'Delinquent debt found', 'debt_id': debt.id}
                elif debt.status == 'active':
                    if debt.monthly_payment > (applicant.monthly_income * 0.4):
                        final_rate += 0.03
                        audit_trail.append(('high_dti_rate_hike', debt.id))

            if approved_amount >= loan_request.requested_amount:
                try:
                    risk_score = risk_api.calculate(applicant.ssn, approved_amount)
                    if risk_score < 40:
                        ledger_id = ledger_service.commit_underwrite(applicant.id, approved_amount, final_rate)
                        return {'status': 'approved', 'ledger_id': ledger_id, 'rate': final_rate, 'audit': audit_trail}
                    else:
                        return {'status': 'flagged', 'reason': 'Risk threshold exceeded', 'score': risk_score}
                except Exception as err:
                    return {'status': 'error', 'message': str(err)}
            else:
                return {'status': 'counter_offer', 'offered_amount': approved_amount, 'rate': final_rate}
        else:
            return {'status': 'rejected', 'reason': 'Low credit score'}
    else:
        return {'status': 'rejected', 'reason': 'Inactive applicant'}

