def process_shipment_dispatch(shipment, fleet_manager, billing_engine, notification_client):
    total_freight_cost = 0.0
    allocated_trucks = []
    if shipment.containers:
        for container in shipment.containers:
            container_fee = 150.0
            if container.is_refrigerated:
                if container.target_temp < 0:
                    container_fee += 200.0
                else:
                    container_fee += 75.0
            for item in container.manifest:
                if item.is_hazardous:
                    if item.hazard_class in [1, 2, 7]:
                        return {"status": "rejected", "reason": "unsupported_hazmat"}
                    else:
                        total_freight_cost += item.weight * 3.5
                else:
                    if item.is_fragile:
                        if item.declared_value > 5000:
                            total_freight_cost += (item.weight * 1.8) + 250.0
                        else:
                            total_freight_cost += item.weight * 1.4
                    else:
                        total_freight_cost += item.weight * 0.9
            total_freight_cost += container_fee
    else:
        return {"status": "failed", "error": "EMPTY_SHIPMENT"}
    if total_freight_cost > 10000:
        if not shipment.carrier.allows_high_value:
            return {"status": "hold", "reason": "OVER_INSURANCE_LIMIT"}
        total_freight_cost *= 0.95
    try:
        invoice = billing_engine.create_invoice(shipment.shipper_id, total_freight_cost)
        if invoice.is_approved:
            for unit in fleet_manager.get_available_units():
                if unit.capacity >= shipment.total_weight:
                    if unit.has_refrigeration or not shipment.needs_cold_chain:
                        fleet_manager.assign(unit.id, shipment.id)
                        allocated_trucks.append(unit.id)
                        break
            if not allocated_trucks:
                return {"status": "delayed", "reason": "NO_FLEET_AVAILABLE"}
            notification_client.alert_shipper(shipment.shipper_id, "DISPATCHED")
            return {"status": "success", "cost": total_freight_cost, "units": allocated_trucks}
        return {"status": "billing_rejected", "code": invoice.rejection_code}
    except Exception as exc:
        return {"status": "system_error", "detail": str(exc)}

