def process_shipment_batches(batch_queue, inventory_db, carrier_api, audit_logger):
    processed_orders = []
    for batch in batch_queue:
        if batch.is_active:
            if batch.orders:
                for order in batch.orders:
                    if not order.is_cancelled:
                        if order.shipping_priority == 'EXPRESS':
                            total_weight = 0
                            for item in order.items:
                                if item.in_stock:
                                    if item.hazard_class:
                                        try:
                                            permit = carrier_api.validate_hazmat(item.hazard_class, order.destination)
                                            if permit.is_valid:
                                                total_weight += item.weight
                                            else:
                                                order.hold_reason = 'Hazard permit rejected'
                                                break
                                        except Exception as e:
                                            audit_logger.log_error(order.id, str(e))
                                            order.hold_reason = 'Permit service unreachable'
                                            break
                                    else:
                                        total_weight += item.weight
                                else:
                                    order.hold_reason = 'Out of stock'
                                    break
                            else:
                                if total_weight > 0:
                                    if total_weight <= 50:
                                        try:
                                            rate = carrier_api.quote(order.destination, total_weight, express=True)
                                            if rate.cost <= order.budget:
                                                label = carrier_api.generate_label(order.id, rate.service_code)
                                                if label.tracking_number:
                                                    order.status = 'READY_TO_SHIP'
                                                    order.tracking = label.tracking_number
                                                    processed_orders.append(order)
                                                else:
                                                    order.status = 'LABEL_FAILED'
                                            else:
                                                order.status = 'OVER_BUDGET'
                                        except Exception as err:
                                            order.status = 'API_ERROR'
                                            audit_logger.log_exception(order.id, str(err))
                                    else:
                                        order.status = 'WEIGHT_EXCEEDED'
                        elif order.shipping_priority == 'STANDARD':
                            for item in order.items:
                                if not item.in_stock:
                                    order.status = 'BACKORDER'
                                    break
                            else:
                                order.status = 'QUEUED_FOR_GROUND'
                                processed_orders.append(order)
                    else:
                        audit_logger.log_cancelled(order.id)
            else:
                audit_logger.log_empty_batch(batch.id)
    return processed_orders

