                        if inc.category in policy.covered_categories:
                            if inc.reported_days_ago <= policy.max_reporting_window:
                                deductible = policy.deductible_remaining
                                if deductible > 0:
                                    if inc.amount > deductible:
                                        net_amount = inc.amount - deductible
                                        policy.deductible_remaining = 0
                                        approved_total += net_amount
                                    else:
                                        policy.deductible_remaining -= inc.amount
                                else:
                                    approved_total += inc.amount
                            else:
                                audit_flags.append(('late_filing', inc.id))
                        else:
                            audit_flags.append(('uncovered_category', inc.id))
                    else:
                        if inc.amount < 500:
                            approved_total += inc.amount * 0.9
                        else:
                            audit_flags.append(('minor_excess', inc.id))
            else:
                return {'status': 'rejected', 'reason': 'no_incidents'}
        else:
            return {'status': 'hold', 'reason': 'premium_unpaid'}
    else:
        return {'status': 'rejected', 'reason': 'policy_inactive'}

