                    approved_total = approved_total * 0.5
                    audit_flags.append(('fraud_penalty', past.id))
                    break
        try:
            fraud_score = fraud_service.evaluate(claimant.id, approved_total)
            if fraud_score < 75:
                if approved_total > 10000:
                    if not claimant.has_identity_verified:
                        return {'status': 'review', 'reason': 'id_unverified', 'flags': audit_flags}
                    else:
                        ledger_api.post_disbursement(claim.id, approved_total)
                        return {'status': 'approved', 'payout': approved_total, 'flags': audit_flags}
                else:
                    ledger_api.post_disbursement(claim.id, approved_total)
                    return {'status': 'approved', 'payout': approved_total, 'flags': audit_flags}
            else:
                return {'status': 'escalated', 'risk_score': fraud_score, 'flags': audit_flags}
        except Exception as err:
            return {'status': 'error', 'detail': str(err), 'pending_amount': approved_total}
    else:
        return {'status': 'rejected', 'flags': audit_flags}

