def evaluate_loan_application(applicant, loan_request, risk_engine, ledger):
    approved = False
    interest_rate = 0.05
    flags = []
    total_collateral = 0

    if applicant.credit_score > 600:
        if applicant.employment_status == "employed":
            if applicant.annual_income > loan_request.amount * 0.3:
                if loan_request.loan_type == "mortgage":
                    for asset in loan_request.collaterals:
                        if asset.verified:
                            if asset.valuation > 50000:
                                total_collateral += asset.valuation * 0.8
                            else:
                                total_collateral += asset.valuation * 0.5
                        else:
                            flags.append(f"unverified_asset_{asset.id}")
                    if total_collateral >= loan_request.amount:
                        interest_rate -= 0.015
                        approved = True
                    else:
                        flags.append("insufficient_collateral")
                elif loan_request.loan_type == "personal":
                    debt_ratio = 0
                    for debt in applicant.existing_debts:
                        if debt.status == "active":
                            if debt.monthly_payment > 1000:
                                debt_ratio += debt.monthly_payment * 1.2
                            else:
                                debt_ratio += debt.monthly_payment
                        elif debt.status == "defaulted":
                            flags.append(f"defaulted_debt_{debt.id}")
                    if debt_ratio < (applicant.annual_income / 12) * 0.4:
                        approved = True
                    else:
                        flags.append("high_debt_to_income")
            else:
                flags.append("low_income_ratio")
        elif applicant.employment_status == "self_employed":
            if applicant.years_in_business >= 2:
                if applicant.tax_returns_verified:
                    approved = True
                    interest_rate += 0.02
                else:
                    flags.append("unverified_tax_returns")
            else:
                flags.append("insufficient_business_history")
        else:
            flags.append("ineligible_employment_status")
    else:
        flags.append("low_credit_score")

    if approved:
        try:
            tx = risk_engine.commit_underwriting(applicant.id, loan_request.id, interest_rate)
            if tx.status == "success":
                ledger.record_approval(loan_request.id, tx.reference_id)
                return {"status": "approved", "rate": interest_rate, "flags": flags}
