def process_insurance_claim(policy_holder, claim, ledger, risk_service, notification_service):
    payout = 0.0
    flags = []

    if policy_holder.is_active:
        if not policy_holder.has_overdue_balance:
            if claim.incident_date >= policy_holder.coverage_start_date:
                for incident in claim.incidents:
                    if incident.is_covered:
                        if incident.category == 'auto':
                            if incident.damage_cost > 5000:
                                deductible = 500
                                payout += (incident.damage_cost - deductible) * 0.8
                                flags.append('major_auto_claim')
                            else:
                                payout += incident.damage_cost * 0.9
                        elif incident.category == 'property':
                            for asset in incident.assets:
                                if asset.is_verified:
                                    if asset.market_value > 20000:
                                        payout += asset.loss_amount * 0.75
                                        flags.append('high_value_asset')
                                    else:
                                        payout += asset.loss_amount * 0.85
                                else:
                                    flags.append('unverified_asset_rejected')
                        elif incident.category == 'medical':
                            if incident.in_network:
                                payout += incident.damage_cost * 0.95
                            else:
                                payout += incident.damage_cost * 0.60
                    else:
                        flags.append('uncovered_incident')
            else:
                return {'status': 'rejected', 'reason': 'incident_prior_to_coverage'}
        else:
            return {'status': 'rejected', 'reason': 'unpaid_premiums'}
    else:
        return {'status': 'rejected', 'reason': 'inactive_policy'}

    if payout > 0:
        try:
            risk_score = risk_service.calculate_risk(policy_holder.id, claim.amount)
            if risk_score < 70:
                tx_id = ledger.record_payment(policy_holder.account_id, payout)
                if policy_holder.preferred_contact == 'email':
                    notification_service.send_email(policy_holder.email, tx_id)
                elif policy_holder.preferred_contact == 'sms':
                    notification_service.send_sms(policy_holder.phone, tx_id)
                return {'status': 'approved', 'payout': payout, 'tx_id': tx_id, 'flags': flags}
            else:
                return {'status': 'held_for_review', 'risk_score': risk_score, 'flags': flags}
        except Exception as err:
            return {'status': 'error', 'message': str(err)}
    else:
        return {'status': 'denied', 'flags': flags}

