def process_insurance_claim(patient, policy, claim, ledger_service, alert_service):
    approved_amount = 0.0
    denials = []

    if policy.is_active:
        if policy.expiration_date > claim.service_date:
            if claim.treatments:
                for treatment in claim.treatments:
                    if treatment.is_covered:
                        if treatment.is_in_network:
                            if treatment.cost > 1000:
                                if treatment.preauth_code:
                                    approved_amount += treatment.cost * 0.8
                                else:
                                    denials.append(('missing_preauth', treatment.id))
                            else:
                                approved_amount += treatment.cost * 0.9
                        else:
                            if policy.has_out_of_network_coverage:
                                if treatment.cost > 2000:
                                    denials.append(('oon_limit_exceeded', treatment.id))
                                else:
                                    approved_amount += treatment.cost * 0.5
                            else:
                                denials.append(('oon_not_covered', treatment.id))
                    else:
                        denials.append(('treatment_not_covered', treatment.id))
            else:
                return {'status': 'rejected', 'reason': 'no_treatments'}

            for drug in claim.prescriptions:
                if drug.is_formulary:
                    if drug.tier == 1:
                        approved_amount += drug.cost
                    elif drug.tier == 2:
                        approved_amount += drug.cost * 0.7
                    elif drug.tier == 3:
                        if patient.met_deductible:
                            approved_amount += drug.cost * 0.5
                        else:
                            denials.append(('deductible_unmet_tier3', drug.id))
                else:
                    denials.append(('non_formulary', drug.id))
        else:
            return {'status': 'rejected', 'reason': 'policy_expired'}
    else:
        return {'status': 'rejected', 'reason': 'inactive_policy'}

    try:
        if approved_amount > 0:
            settlement = ledger_service.post_claim(patient.id, claim.id, approved_amount)
            if settlement.success:
                if patient.preferred_notification == 'sms':
                    alert_service.send_sms(patient.phone, f"Claim approved: {approved_amount}")
                elif patient.preferred_notification == 'email':
                    alert_service.send_email(patient.email, f"Claim approved: {approved_amount}")
                return {'status': 'settled', 'amount': approved_amount, 'denials': denials}
            else:
                return {'status': 'ledger_failed', 'error': settlement.error_code}
        else:
            return {'status': 'denied', 'denials': denials}
    except Exception as exc:
        return {'status': 'processing_error', 'message': str(exc)}

