def find_high_complexity_functions(source_code: str, threshold: int = 10) -> list[dict]:
    """Parse source code and find functions exceeding McCabe complexity threshold."""
    tree = ast.parse(source_code)
    results = []

    branch_nodes = (
        ast.If, ast.While, ast.For, ast.AsyncFor,
        ast.ExceptHandler, ast.With, ast.AsyncWith,
        ast.Assert
    )

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            complexity = 1
            for child in ast.walk(node):
                if isinstance(child, branch_nodes):
                    complexity += 1
                elif isinstance(child, ast.BoolOp):
                    complexity += len(child.values) - 1
                elif isinstance(child, (ast.IfExp, ast.comprehension)):
                    complexity += 1

            if complexity > threshold:
                results.append({
                    "name": node.name,
                    "lineno": node.lineno,
                    "complexity": complexity
                })

    return results

