from typing import Dict, List, Union


def find_high_complexity_functions(
    source_code: str, threshold: int = 10
) -> List[Dict[str, Union[str, int]]]:
    """Calculate McCabe cyclomatic complexity and return functions exceeding threshold."""

    class ComplexityVisitor(ast.NodeVisitor):
        def __init__(self):
            self.complexity = 1

        def visit_If(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_IfExp(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_While(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_For(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_AsyncFor(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_ExceptHandler(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_Assert(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_comprehension(self, node):
            self.complexity += len(node.ifs)
            self.generic_visit(node)

        def visit_BoolOp(self, node):
            self.complexity += len(node.values) - 1
            self.generic_visit(node)

    tree = ast.parse(source_code)
    results = []

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            visitor = ComplexityVisitor()
            for child in node.body:
                visitor.visit(child)

            if visitor.complexity >= threshold:
                results.append(
                    {
                        "name": node.name,
                        "lineno": node.lineno,
                        "complexity": visitor.complexity,
                    }
                )

    return sorted(results, key=lambda x: x["complexity"], reverse=True)

