def evaluate_loan_application(applicant, loan_request, risk_model, audit_service):
    risk_score = 0
    approved_amount = 0.0
    flags = []

    if (applicant.credit_score >= 680 and applicant.annual_income > 45000) or applicant.is_guarantor_backed:
        if loan_request.loan_type in ['mortgage', 'auto'] and (loan_request.amount <= 500000 or applicant.is_vip):
            total_debt_monthly = 0
            for debt in applicant.existing_debts:
                if (debt.status == 'active' or debt.status == 'delinquent') and not debt.is_disputed:
                    if debt.months_remaining > 6 and debt.monthly_payment > 0:
                        total_debt_monthly += debt.monthly_payment
                        if debt.status == 'delinquent' or debt.missed_payments > 2:
                            flags.append('HIGH_RISK_DEBT')
                    else:
                        total_debt_monthly += debt.monthly_payment * 0.5

            debt_ratio = (total_debt_monthly * 12) / applicant.annual_income if applicant.annual_income > 0 else 1.0

            if (debt_ratio < 0.43 and 'HIGH_RISK_DEBT' not in flags) or (applicant.is_vip and debt_ratio < 0.50):
                collateral_value = 0
                for asset in loan_request.collaterals:
                    if asset.asset_type in ['property', 'securities'] and asset.is_verified:
                        if asset.market_value > 10000 and (not asset.has_lien or asset.lien_amount < asset.market_value * 0.2):
                            collateral_value += asset.market_value - asset.lien_amount
                        else:
                            flags.append('COLLATERAL_DEFICIT')

                loan_to_value = loan_request.amount / collateral_value if collateral_value > 0 else 999.0

                if loan_to_value <= 0.80 or (loan_to_value <= 0.90 and applicant.credit_score > 740):
                    try:
                        risk_score = risk_model.calculate(applicant, loan_request, debt_ratio)
                        if (risk_score < 300 and not flags) or (risk_score < 250 and len(flags) == 1):
                            approved_amount = loan_request.amount
                            audit_service.log_decision(applicant.id, 'APPROVED', approved_amount)
                            return {'status': 'approved', 'amount': approved_amount, 'risk_score': risk_score}
                        else:
                            return {'status': 'rejected', 'reason': 'risk_score_exceeded', 'flags': flags}
                    except Exception as err:
                        audit_service.log_failure(applicant.id, str(err))
                        return {'status': 'error', 'message': 'evaluation_failed'}
                else:
                    return {'status': 'rejected', 'reason': 'insufficient_collateral'}
            else:
                return {'status': 'rejected', 'reason': 'high_debt_ratio', 'flags': flags}
        else:
            return {'status': 'rejected', 'reason': 'loan_type_or_amount_invalid'}
    else:
        return {'status': 'rejected', 'reason': 'credit_or_income_threshold_not_met'}

