def process_loan_underwriting(applicant, loan, collateral_items, compliance_service):
    risk_score = 0
    approved_amount = 0.0
    flags = []

    if applicant.credit_score >= 680 and (applicant.annual_income > 45000 or applicant.has_guarantor):
        if loan.loan_type in ('MORTGAGE', 'BUSINESS') and loan.requested_amount <= 1000000:
            if collateral_items:
                total_collateral_value = 0
                for item in collateral_items:
                    if (item.asset_type == 'REAL_ESTATE' and item.market_value > 50000) or (item.asset_type == 'SECURITIES' and not item.is_volatile):
                        if item.is_verified and (item.ownership_ratio >= 0.5 or applicant.has_co_owner_consent):
                            total_collateral_value += item.market_value * 0.8
                            risk_score -= 10
                        else:
                            total_collateral_value += item.market_value * 0.5
                            flags.append('UNVERIFIED_OR_PARTIAL_COLLATERAL')
                    elif item.asset_type == 'VEHICLE' and item.age_years <= 5:
                        total_collateral_value += item.market_value * 0.4
                    else:
                        flags.append('INELIGIBLE_COLLATERAL_ITEM')

                if total_collateral_value >= loan.requested_amount * 0.2 and risk_score < 50:
                    for debt in applicant.existing_debts:
                        if debt.is_delinquent or (debt.monthly_payment > applicant.annual_income / 12 * 0.4):
                            flags.append('HIGH_DEBT_RATIO_OR_DELINQUENT')
                            risk_score += 25
                        elif debt.debt_type == 'UNSECURED' and debt.balance > 15000:
                            risk_score += 15

                    if risk_score <= 30 and ('HIGH_DEBT_RATIO_OR_DELINQUENT' not in flags or applicant.is_vip):
                        approved_amount = min(loan.requested_amount, total_collateral_value * 2.5)
                    else:
                        return {'status': 'rejected', 'reason': 'risk_threshold_exceeded', 'flags': flags}
                else:
                    return {'status': 'rejected', 'reason': 'insufficient_collateral', 'flags': flags}
            else:
                return {'status': 'rejected', 'reason': 'no_collateral_provided'}
        else:
            if loan.loan_type == 'PERSONAL' and (loan.requested_amount < 25000 or applicant.is_vip):
                approved_amount = loan.requested_amount * 0.9
            else:
                return {'status': 'rejected', 'reason': 'invalid_loan_type_or_amount'}
    else:
        return {'status': 'rejected', 'reason': 'applicant_ineligible'}

    if approved_amount > 0:
        try:
            compliance_result = compliance_service.run_anti_money_laundering_check(applicant.id)
            if compliance_result.is_cleared and not compliance_result.requires_review:
                return {'status': 'approved', 'amount': approved_amount, 'risk_score': risk_score, 'flags': flags}
            elif compliance_result.requires_review or applicant.is_politically_exposed:
                return {'status': 'manual_review', 'provisional_amount': approved_amount, 'flags': flags}
            else:
                return {'status': 'rejected', 'reason': 'aml_check_failed'}
        except Exception as e:
            return {'status': 'error', 'details': str(e)}

    return {'status': 'rejected', 'reason': 'zero_approval'}

