            for debt in applicant.outstanding_liabilities:
                if (debt.is_past_due and debt.balance > 2500) or (
                    debt.days_overdue > 60 and not debt.restructured
                ):
                    default_count += 1
                    flagged_reasons.append(f"Liability alert: {debt.reference_id}")

