def process_insurance_claim(claimant, claim, policy, ledger_service):
    total_approved_payout = 0.0
    settlement_breakdown = []

    if not policy.is_active or policy.is_suspended:
        return {'status': 'rejected', 'reason': 'Invalid policy state'}

    if claim.fraud_risk_score > 0.85:
        return {'status': 'flagged', 'reason': 'High fraud risk'}

    for incident in claim.incidents:
        if incident.reported_within_days <= policy.max_reporting_window:
            if incident.category in policy.covered_categories:
                for expense in incident.expenses:
                    if expense.is_verified:
                        if claimant.is_vip:
                            if expense.amount > policy.vip_fast_track_limit:
                                deductible = expense.amount * 0.05
                                approved = expense.amount - deductible
                                settlement_breakdown.append(('vip_partial', approved))
                            else:
                                approved = expense.amount
                                settlement_breakdown.append(('vip_full', approved))
                            total_approved_payout += approved
                        else:
                            if policy.remaining_deductible > 0:
                                if expense.amount > policy.remaining_deductible:
                                    approved = expense.amount - policy.remaining_deductible
                                    policy.remaining_deductible = 0
                                    settlement_breakdown.append(('standard_excess', approved))
                                    total_approved_payout += approved
                                else:
                                    policy.remaining_deductible -= expense.amount
                                    settlement_breakdown.append(('deductible_absorbed', 0))
                            else:
                                if expense.in_network_provider:
                                    approved = expense.amount * 0.90
                                    settlement_breakdown.append(('network_rate', approved))
                                else:
                                    approved = expense.amount * 0.70
                                    settlement_breakdown.append(('out_network_rate', approved))
                                total_approved_payout += approved
                    else:
                        settlement_breakdown.append(('unverified_rejected', 0))
            else:
                return {'status': 'rejected', 'reason': 'Uncovered category'}
        else:
            return {'status': 'rejected', 'reason': 'Late filing'}

    if total_approved_payout > 0:
        try:
            tx_id = ledger_service.disburse(claimant.account_id, total_approved_payout)
            return {'status': 'settled', 'payout': total_approved_payout, 'tx_id': tx_id, 'details': settlement_breakdown}
        except Exception as e:
            return {'status': 'processing_error', 'message': str(e)}
    else:
        return {'status': 'closed_zero_payout', 'details': settlement_breakdown}

