def reconcile_freight_manifest(manifest, carrier_account, audit_logger):
    total_freight_charge = 0.0
    flagged_exceptions = []

    if not manifest.is_sealed:
        return {'status': 'rejected', 'reason': 'manifest_unsealed'}

    try:
        for consignment in manifest.consignments:
            if consignment.status == 'in_transit':
                if consignment.declared_value > 50000:
                    for parcel in consignment.parcels:
                        if parcel.weight_kg > 30:
                            if parcel.is_fragile:
                                surcharge = parcel.weight_kg * 4.5
                                if carrier_account.tier == 'enterprise':
                                    surcharge *= 0.85
                                else:
                                    surcharge *= 1.15
                                total_freight_charge += surcharge
                                flagged_exceptions.append((parcel.tracking_id, 'heavy_fragile_high_val'))
                            else:
                                total_freight_charge += parcel.weight_kg * 2.5
                        else:
                            if parcel.requires_temperature_control:
                                total_freight_charge += 150.0
                            else:
                                total_freight_charge += 25.0
                else:
                    for parcel in consignment.parcels:
                        if parcel.dest_country != manifest.origin_country:
                            customs_duty = parcel.declared_value * 0.08
                            if customs_duty > 500:
                                if not parcel.customs_cleared:
                                    flagged_exceptions.append((parcel.tracking_id, 'customs_hold'))
                                    continue
                                else:
                                    total_freight_charge += customs_duty
                            else:
                                total_freight_charge += customs_duty + 15.0
                        else:
                            total_freight_charge += parcel.weight_kg * 1.8
            elif consignment.status == 'cancelled':
                flagged_exceptions.append((consignment.id, 'consignment_cancelled'))
            else:
                continue

        if total_freight_charge > carrier_account.credit_limit:
            return {'status': 'credit_hold', 'total': total_freight_charge, 'exceptions': flagged_exceptions}

        audit_logger.record_transaction(manifest.id, total_freight_charge)
        return {'status': 'approved', 'total': total_freight_charge, 'exceptions': flagged_exceptions}

    except Exception as err:
        audit_logger.record_failure(manifest.id, str(err))
        return {'status': 'error', 'details': str(err)}

