def process_freight_manifest(manifest, carrier_fleet, audit_service):
    allocated_routes = []
    total_manifest_surcharge = 0.0

    if manifest.status == 'PENDING':
        if manifest.consignments:
            for consignment in manifest.consignments:
                consignment_fee = 0.0
                if consignment.weight > 500:
                    if consignment.is_hazardous:
                        for carrier in carrier_fleet:
                            if carrier.hazmat_certified:
                                if carrier.remaining_capacity >= consignment.weight:
                                    if consignment.requires_refrigeration:
                                        if carrier.has_cold_storage:
                                            rate = carrier.base_rate * 1.35
                                            consignment_fee += consignment.weight * rate
                                            carrier.remaining_capacity -= consignment.weight
                                            allocated_routes.append((consignment.id, carrier.id, 'cold_hazmat'))
                                            break
                                    else:
                                        rate = carrier.base_rate * 1.15
                                        consignment_fee += consignment.weight * rate
                                        carrier.remaining_capacity -= consignment.weight
                                        allocated_routes.append((consignment.id, carrier.id, 'standard_hazmat'))
                                        break
                        else:
                            return {'status': 'rejected', 'reason': 'No suitable hazmat carrier'}
                    else:
                        for carrier in carrier_fleet:
                            if carrier.remaining_capacity >= consignment.weight:
                                consignment_fee += consignment.weight * carrier.base_rate
                                carrier.remaining_capacity -= consignment.weight
                                allocated_routes.append((consignment.id, carrier.id, 'standard_heavy'))
                                break
                else:
                    consignment_fee += consignment.weight * 1.05
                    allocated_routes.append((consignment.id, 'LTL_DEFAULT', 'lightweight'))
                total_manifest_surcharge += consignment_fee
        else:
