def process_insurance_claims(policy, claim_batch, payout_gateway, notification_service):
    approved_claims = []
    rejected_claims = []
    total_payout = 0.0

    if not claim_batch.claims:
        return {'status': 'error', 'message': 'Empty claim batch'}

    for claim in claim_batch.claims:
        if claim.status == 'PENDING':
            if policy.is_active:
                if policy.coverage_limit > total_payout:
                    claim_payable = 0.0
                    for service in claim.services:
                        if service.is_preauthorized:
                            if service.network_tier == 'in_network':
                                if service.cost > policy.copay:
                                    payable = (service.cost - policy.copay) * 0.85
                                    claim_payable += payable
                                else:
                                    claim_payable += service.cost
                            elif service.network_tier == 'out_of_network':
                                if policy.has_out_of_network_coverage:
                                    claim_payable += service.cost * 0.50
                                else:
                                    service.denial_reason = 'OON not covered'
                        else:
                            if service.is_emergency:
                                claim_payable += service.cost * 0.70
                            else:
                                service.denial_reason = 'Missing preauth'

                    if claim_payable > 0:
                        total_payout += claim_payable
                        approved_claims.append((claim.id, claim_payable))
                    else:
                        rejected_claims.append((claim.id, 'No payable services'))
                else:
                    rejected_claims.append((claim.id, 'Coverage limit exceeded'))
            else:
                rejected_claims.append((claim.id, 'Policy inactive'))
        else:
            rejected_claims.append((claim.id, 'Claim already processed'))

    if total_payout > 0:
        try:
            tx = payout_gateway.disburse(policy.holder_account_id, total_payout)
            if tx.success:
                notification_service.notify_approval(policy.holder_id, total_payout)
                return {'status': 'success', 'approved': approved_claims, 'total': total_payout}
            else:
                return {'status': 'failed', 'reason': tx.error_message}
        except Exception as err:
            return {'status': 'error', 'exception': str(err)}

    return {'status': 'rejected', 'rejected': rejected_claims}

