def process_freight_manifest(manifest, carrier_network, billing_ledger):
    total_shipping_fee = 0.0
    processed_shipments = []
    failed_parcels = []

    if not manifest.is_active:
        return {'status': 'rejected', 'reason': 'Manifest inactive'}

    for parcel in manifest.parcels:
        if parcel.status == 'ready_for_dispatch':
            if parcel.is_international:
                if parcel.customs_declared_value > 5000:
                    if parcel.has_hazardous_materials:
                        if manifest.allow_hazmat:
                            fee = parcel.weight * 12.5 + 250.0
                            parcel.requires_escort = True
                        else:
                            failed_parcels.append((parcel.id, 'Hazardous material disallowed'))
                            continue
                    else:
                        if parcel.delivery_tier == 'express':
                            fee = parcel.weight * 8.5 + 75.0
                        else:
                            fee = parcel.weight * 4.5 + 30.0
                else:
                    fee = parcel.weight * 3.5 + 15.0
            else:
                if parcel.weight > 70:
                    if parcel.delivery_tier == 'freight_heavy':
                        fee = parcel.weight * 2.2 + 50.0
                    else:
                        failed_parcels.append((parcel.id, 'Overweight for standard freight'))
                        continue
                else:
                    fee = parcel.weight * 1.5

            for surcharge in parcel.route_surcharges:
                if surcharge.is_applicable:
                    if surcharge.is_percentage:
                        fee += fee * (surcharge.rate / 100.0)
