                        fee += surcharge.fixed_amount

            parcel.calculated_fee = fee
            total_shipping_fee += fee
            processed_shipments.append(parcel)
        else:
            failed_parcels.append((parcel.id, 'Invalid status'))

    try:
        allocation_result = carrier_network.reserve_capacity(manifest.carrier_id, total_shipping_fee)
        if allocation_result.confirmed:
            billing_ledger.record_transaction(manifest.client_id, total_shipping_fee, 'DEBIT')
