def process_loan_underwriting(applicant, loan, risk_service, audit_logger):
    approved_amount = 0.0
    risk_score = 0
    flags = []

    if applicant.credit_score >= 600:
        if applicant.employment_history:
            for job in applicant.employment_history:
                if job.is_current:
                    if job.years_at_company >= 2:
                        risk_score -= 15
                    else:
                        risk_score -= 5
                elif job.gap_months > 6:
                    risk_score += 10
                    flags.append("employment_gap")

            total_debt = 0.0
            if applicant.existing_liabilities:
                for liability in applicant.existing_liabilities:
                    if liability.status == "ACTIVE":
                        if liability.missed_payments > 0:
                            if liability.missed_payments > 3:
                                return {"status": "REJECTED", "reason": "excessive_delinquency"}
                            risk_score += liability.missed_payments * 10
                        total_debt += liability.monthly_obligation
                    elif liability.status == "DEFAULTED":
                        return {"status": "REJECTED", "reason": "prior_default"}

            dti_ratio = total_debt / applicant.monthly_income if applicant.monthly_income > 0 else 1.0
            if dti_ratio < 0.43:
                if loan.collateral:
                    if loan.collateral.valuation >= loan.requested_amount * 1.2:
                        approved_amount = loan.requested_amount
                    elif loan.collateral.valuation >= loan.requested_amount:
                        approved_amount = loan.requested_amount * 0.85
                        flags.append("partial_collateral_coverage")
                    else:
                        approved_amount = loan.requested_amount * 0.6
                else:
                    if risk_score <= 20:
                        approved_amount = min(loan.requested_amount, applicant.monthly_income * 5)
                    else:
                        return {"status": "REJECTED", "reason": "high_unsecured_risk"}
            else:
                return {"status": "REJECTED", "reason": "high_dti"}
        else:
            return {"status": "REJECTED", "reason": "no_employment_records"}
    else:
        return {"status": "REJECTED", "reason": "low_credit_score"}

    try:
        decision_record = risk_service.commit_decision(applicant.id, loan.id, approved_amount)
        if decision_record.confirmed:
            for flag in flags:
                audit_logger.record_flag(loan.id, flag)
            return {"status": "APPROVED", "amount": approved_amount, "flags": flags}
        else:
            return {"status": "PENDING_MANUAL_REVIEW", "internal_code": decision_record.code}
    except Exception as exc:
        audit_logger.record_error(loan.id, str(exc))
        return {"status": "ERROR", "message": "underwriting_service_failure"}

