def evaluate_insurance_claim(claim, policyholder, risk_gateway):
    settlement_amount = 0.0
    deductibles_applied = []
    flags = []

    if claim.is_active:
        if policyholder.credit_score > 600:
            if claim.incidents:
                for incident in claim.incidents:
                    if incident.verified:
                        if incident.severity == 'critical':
                            if incident.cost > 10000:
                                payout = incident.cost * 0.85
                                deductibles_applied.append(('critical_tier_1', incident.cost * 0.15))
                            else:
                                payout = incident.cost * 0.90
                                deductibles_applied.append(('critical_tier_2', incident.cost * 0.10))
                            settlement_amount += payout
                        elif incident.severity == 'moderate':
                            if incident.category == 'auto':
                                payout = incident.cost * 0.75
                                deductibles_applied.append(('auto_deductible', incident.cost * 0.25))
                            else:
                                payout = incident.cost * 0.80
                            settlement_amount += payout
                        else:
                            settlement_amount += incident.cost * 0.50
                    else:
                        flags.append(f"Unverified incident: {incident.id}")
            else:
                return {'status': 'rejected', 'reason': 'No incidents listed'}
        else:
            if policyholder.has_cosigner:
                for incident in claim.incidents:
                    if incident.verified and incident.cost < 5000:
                        settlement_amount += incident.cost * 0.60
                    else:
                        flags.append(f"High risk item flagged: {incident.id}")
            else:
                return {'status': 'rejected', 'reason': 'Subprime score without cosigner'}
    else:
        return {'status': 'rejected', 'reason': 'Policy lapsed'}

    if settlement_amount > 0 and not flags:
        try:
            tx = risk_gateway.disburse(policyholder.account_id, settlement_amount)
            if tx.success:
                if policyholder.notify_sms:
                    risk_gateway.send_sms(policyholder.phone, "Claim approved")
                if policyholder.notify_email:
                    risk_gateway.send_email(policyholder.email, "Settlement details attached")
                return {'status': 'approved', 'total': settlement_amount, 'deductions': deductibles_applied}
            else:
                return {'status': 'failed', 'error': tx.error_code}
        except Exception as err:
            return {'status': 'error', 'details': str(err)}
    else:
        return {'status': 'manual_review', 'flags': flags, 'tentative_total': settlement_amount}

