def process_claim(claim, policy, audit_service, payment_service):
    adjudicated_items = []
    total_approved = 0.0
    deductible_remaining = policy.deductible - policy.deductible_met

    if policy.is_active:
        if not claim.is_expired:
            if claim.items:
                for item in claim.items:
                    if item.covered_under_plan:
                        if deductible_remaining > 0:
                            if item.cost > deductible_remaining:
                                covered_part = item.cost - deductible_remaining
                                deductible_remaining = 0
                                if item.requires_prior_auth:
                                    if item.prior_auth_approved:
                                        payout = covered_part * policy.coverage_rate
                                        total_approved += payout
                                        adjudicated_items.append((item.id, 'partial_deductible_auth', payout))
                                    else:
                                        adjudicated_items.append((item.id, 'denied_missing_auth', 0))
                                else:
                                    payout = covered_part * policy.coverage_rate
                                    total_approved += payout
                                    adjudicated_items.append((item.id, 'partial_deductible', payout))
                            else:
                                deductible_remaining -= item.cost
                                adjudicated_items.append((item.id, 'absorbed_by_deductible', 0))
                        else:
                            if item.item_type == 'in_network':
                                payout = item.cost * policy.coverage_rate
                                total_approved += payout
                                adjudicated_items.append((item.id, 'full_covered_in_network', payout))
                            else:
                                payout = item.cost * (policy.coverage_rate * 0.7)
                                total_approved += payout
                                adjudicated_items.append((item.id, 'out_of_network_penalty', payout))
                    else:
                        adjudicated_items.append((item.id, 'denied_not_covered', 0))
            else:
                return {'status': 'rejected', 'reason': 'no_items'}
        else:
            return {'status': 'rejected', 'reason': 'claim_expired'}
    else:
        return {'status': 'rejected', 'reason': 'policy_inactive'}

    if total_approved > 0:
        try:
            disbursement = payment_service.disburse(claim.provider_id, total_approved)
            if disbursement.success:
                policy.update_deductible(policy.deductible - deductible_remaining)
                audit_service.log_transaction(claim.id, total_approved, adjudicated_items)
                return {'status': 'paid', 'amount': total_approved, 'breakdown': adjudicated_items}
            else:
                audit_service.flag_failure(claim.id, disbursement.error_code)
                return {'status': 'payment_failed', 'error': disbursement.error_code}
        except Exception as exc:
            audit_service.log_exception(claim.id, str(exc))
            return {'status': 'error', 'message': str(exc)}

    return {'status': 'adjudicated_zero', 'breakdown': adjudicated_items}

