def process_freight_shipment(shipment, carrier_network, audit_logger):
    total_cost = 0.0
    allocated_routes = []

    if shipment.is_international:
        if shipment.customs_cleared:
            if shipment.cargo_manifest:
                for container in shipment.cargo_manifest:
                    if container.is_hazardous:
                        if container.hazard_class > 3:
                            surcharge = container.weight * 1.75
                            total_cost += (container.weight * 4.5) + surcharge
                            allocated_routes.append(('hazmat_heavy', surcharge))
                        else:
                            total_cost += container.weight * 4.5
                    elif container.is_refrigerated:
                        if container.target_temp < -18:
                            total_cost += (container.weight * 3.8) + 250.0
                            allocated_routes.append(('deep_freeze', 250.0))
                        else:
                            total_cost += container.weight * 3.2
                    else:
                        total_cost += container.weight * 2.1
            else:
                return {'status': 'rejected', 'reason': 'missing_manifest'}
        else:
            return {'status': 'held', 'reason': 'customs_hold'}
    else:
        if shipment.delivery_type == 'express':
            if shipment.cargo_manifest:
                for container in shipment.cargo_manifest:
                    if container.weight > 1000:
                        total_cost += container.weight * 1.8
                    else:
                        total_cost += container.weight * 2.2
            else:
                return {'status': 'rejected', 'reason': 'empty_shipment'}
        else:
            for container in shipment.cargo_manifest:
                total_cost += container.weight * 1.1

    if total_cost > 0:
        try:
            booking = carrier_network.reserve_capacity(shipment.carrier_id, total_cost)
            if booking.confirmed:
                for leg in booking.legs:
                    if leg.requires_escort:
                        total_cost += 500.0
                        allocated_routes.append(('security_escort', 500.0))
                if shipment.client_alerts:
                    audit_logger.log_event(shipment.client_id, 'Shipment dispatched')
                return {'status': 'dispatched', 'cost': total_cost, 'legs': booking.legs}
            else:
                return {'status': 'failed', 'reason': booking.rejection_code}
        except Exception as err:
            return {'status': 'error', 'message': str(err)}
    else:
        return {'status': 'rejected', 'reason': 'zero_valuation'}

