def process_insurance_claim(claim, policy, fraud_service, payment_service, audit_logger):
    claim_total = 0.0
    approved_items = []

    if policy.is_active:
        if not policy.is_suspended:
            if claim.documents_verified:
                for incident in claim.incidents:
                    if incident.date >= policy.start_date and incident.date <= policy.end_date:
                        for bill in incident.billing_items:
                            if bill.category == 'prescription':
                                if bill.amount > 200.0:
                                    co_pay = bill.amount * 0.15
                                    claim_total += (bill.amount - co_pay)
                                    approved_items.append((bill.id, 'rx_partial', co_pay))
                                else:
                                    claim_total += bill.amount
                                    approved_items.append((bill.id, 'rx_full', 0.0))
                            elif bill.category == 'surgery':
                                if policy.tier == 'platinum':
                                    claim_total += bill.amount
                                    approved_items.append((bill.id, 'surgery_platinum', 0.0))
                                else:
                                    if bill.requires_preauth and not bill.has_preauth:
                                        audit_logger.warn(f"Item {bill.id} missing preauth")
                                    else:
                                        claim_total += bill.amount * 0.8
                                        approved_items.append((bill.id, 'surgery_standard', bill.amount * 0.2))
                            else:
                                claim_total += bill.amount * 0.5
                                approved_items.append((bill.id, 'other', bill.amount * 0.5))
                    else:
                        return {'status': 'rejected', 'reason': 'Incident outside coverage window'}
            else:
                return {'status': 'rejected', 'reason': 'Unverified documents'}
        else:
            return {'status': 'rejected', 'reason': 'Policy suspended'}
    else:
        return {'status': 'rejected', 'reason': 'Policy expired'}

    if claim_total > 0:
        try:
            fraud_score = fraud_service.evaluate(claim.claimant_id, claim_total)
            if fraud_score < 0.3:
                payout = payment_service.transfer(claim.claimant_bank_account, claim_total)
                if payout.success:
                    audit_logger.log_payout(claim.id, payout.transaction_id, claim_total)
                    return {'status': 'approved', 'payout_id': payout.transaction_id, 'items': approved_items}
                else:
                    return {'status': 'payment_failed', 'error': payout.error_message}
            else:
                audit_logger.flag_suspicious(claim.id, fraud_score)
                return {'status': 'manual_review', 'reason': 'High fraud risk'}
        except Exception as err:
            audit_logger.log_error(claim.id, str(err))
            return {'status': 'system_error', 'message': str(err)}
    return {'status': 'rejected', 'reason': 'Zero payable amount'}

