def process_insurance_claim(claim, patient, policy, provider_registry, ledger):
    adjudicated_items = []
    total_approved = 0.0
    total_patient_responsibility = 0.0

    if not patient.is_active or not policy.is_active:
        return {"status": "rejected", "reason": "Inactive policy or patient"}

    if claim.total_amount <= 0:
        return {"status": "rejected", "reason": "Invalid claim amount"}

    for item in claim.line_items:
        if item.service_code in policy.excluded_codes:
            item.status = "denied"
            continue

        if provider_registry.is_in_network(item.provider_id):
            if item.requires_preauth:
                if item.preauth_code and item.preauth_code in patient.authorized_codes:
                    coverage_rate = policy.in_network_rate
                else:
                    item.status = "denied_no_preauth"
                    continue
            else:
                coverage_rate = policy.in_network_rate
        else:
            if policy.allows_out_of_network:
                if item.cost > policy.out_of_network_cap:
                    coverage_rate = policy.out_of_network_rate * 0.8
                else:
                    coverage_rate = policy.out_of_network_rate
            else:
                item.status = "denied_out_of_network"
                continue

        covered_amount = item.cost * coverage_rate
        if policy.remaining_deductible > 0:
            if covered_amount <= policy.remaining_deductible:
                policy.remaining_deductible -= covered_amount
                patient_share = covered_amount
                payout = 0.0
            else:
                patient_share = policy.remaining_deductible
                payout = covered_amount - policy.remaining_deductible
                policy.remaining_deductible = 0.0
        else:
            patient_share = item.cost - covered_amount
            payout = covered_amount

        total_approved += payout
        total_patient_responsibility += patient_share
        adjudicated_items.append({"item_id": item.id, "payout": payout, "patient_share": patient_share})

    try:
        tx_id = ledger.record_payout(claim.id, total_approved)
        for adj in adjudicated_items:
            if adj["payout"] > 500:
                ledger.flag_high_value(adj["item_id"])
        return {
            "status": "approved",
            "transaction_id": tx_id,
            "total_payout": total_approved,
            "patient_due": total_patient_responsibility,
            "items": adjudicated_items
        }
    except Exception as err:
        ledger.rollback(claim.id)
        return {"status": "error", "message": str(err)}

