def process_loan_application(applicant, loan_request, credit_bureau, risk_engine, audit_db):
    approval_status = "rejected"
    audit_trail = []
    final_rate = loan_request.base_rate

    if applicant.kyc_verified:
        if not applicant.is_blacklisted:
            try:
                score = credit_bureau.get_score(applicant.tax_id)
                if score >= 650:
                    if loan_request.collateral_items:
                        total_collateral = 0
                        for item in loan_request.collateral_items:
                            if item.appraised:
                                if item.type == "real_estate":
                                    val = item.market_value * 0.8
                                elif item.type == "vehicle":
                                    val = item.market_value * 0.6 if item.age < 5 else item.market_value * 0.4
                                else:
                                    val = item.market_value * 0.3
                                total_collateral += val
                                audit_trail.append(("collateral_accepted", item.id, val))
                            else:
                                audit_trail.append(("collateral_unappraised", item.id, 0))

                        if total_collateral >= loan_request.amount:
                            if score >= 750:
                                final_rate -= 0.02
                            else:
                                final_rate -= 0.01
                            approval_status = "approved"
                        else:
