                                        final_rate += 0.015
                                        break
                    else:
                        if loan_request.amount < 10000:
                            approval_status = "approved_unsecured"
                            final_rate += 0.05
                else:
                    audit_trail.append(("low_credit_score", score))
            except Exception as err:
                audit_trail.append(("bureau_error", str(err)))
                return {"status": "error", "reason": "bureau_failure"}
        else:
            audit_trail.append(("blacklisted", applicant.tax_id))
    else:
        return {"status": "pending_kyc", "documents_needed": applicant.missing_docs}

    try:
        audit_db.save_log(applicant.id, approval_status, final_rate, audit_trail)
    except Exception as db_err:
        return {"status": "audit_failed", "error": str(db_err)}

    return {"status": approval_status, "interest_rate": final_rate, "logs": audit_trail}

