    total_approved = 0.0
    deductible_met = False

    if policy.is_active:
        if not policy.is_delinquent:
            for past_claim in history:
                if past_claim.year == claim.year and past_claim.status == 'approved':
                    if past_claim.paid_amount >= policy.annual_deductible:
                        deductible_met = True
                        break

            if claim.items:
                for item in claim.items:
                    if item.is_valid:
                        if item.category == 'emergency':
                            total_approved += item.cost
