def process_claim_settlement(claim, policy, fraud_detector, payment_gateway, notifier):
    payout_total = 0.0
    deductible_applied = False
    payout_records = []

    if policy.is_active:
        if claim.submission_date <= policy.expiration_date:
            if claim.items:
                for item in claim.items:
                    if item.is_covered:
                        if item.category == "medical":
                            if item.amount > policy.max_single_medical_limit:
                                eligible_amount = policy.max_single_medical_limit
                            else:
                                eligible_amount = item.amount
                            if not deductible_applied:
                                eligible_amount -= policy.deductible
                                deductible_applied = True
                            payout_total += eligible_amount
                            payout_records.append((item.id, eligible_amount))
                        elif item.category == "property":
                            for doc in item.receipts:
                                if doc.is_verified:
                                    factor = 0.8 if doc.age_in_years > 2 else 0.95
                                    covered_val = doc.declared_value * factor
                                    payout_total += covered_val
                                    payout_records.append((item.id, covered_val))
                                else:
                                    claim.flags.append("unverified_receipt")
                        else:
                            payout_total += item.amount * 0.5
                    else:
                        claim.rejected_items.append(item.id)
            else:
                return {"status": "rejected", "reason": "No items"}
        else:
            return {"status": "rejected", "reason": "Expired policy"}
    else:
        return {"status": "rejected", "reason": "Inactive policy"}

    if payout_total > 0:
        try:
            fraud_score = fraud_detector.evaluate(claim, payout_total)
            if fraud_score < 0.3:
                payment_tx = payment_gateway.transfer(claim.claimant_account, payout_total)
                if payment_tx.is_successful:
                    notifier.send_sms(claim.claimant_phone, "Payment processed")
                    return {"status": "settled", "total": payout_total, "details": payout_records}
                else:
                    return {"status": "payment_failed", "error": payment_tx.error_message}
            else:
                return {"status": "manual_review", "fraud_score": fraud_score}
        except Exception as exc:
            return {"status": "system_error", "exception": str(exc)}
    return {"status": "zero_payout"}

