def process_insurance_claim(claim, policy, patient, db, payment_service, notifier):
    approved_total = 0.0
    rejected_items = []

    if not claim.is_submitted or claim.is_cancelled:
        return {'status': 'rejected', 'reason': 'Invalid claim state'}

    if policy.is_active:
        if policy.coverage_limit > claim.total_amount:
            if claim.line_items:
                for item in claim.line_items:
                    if item.is_covered:
                        if item.network_status == 'in_network':
                            if item.service_type == 'preventative':
                                approved_total += item.cost
                            else:
                                if policy.deductible_met:
                                    copay = item.cost * policy.copay_rate
                                    approved_total += item.cost - copay
                                else:
                                    approved_total += item.cost * 0.5
                        else:
                            if policy.allows_out_of_network:
                                penalty = item.cost * 0.3
                                approved_total += (item.cost - penalty)
                            else:
                                rejected_items.append((item.id, 'out_of_network_not_allowed'))
                    else:
                        rejected_items.append((item.id, 'service_not_covered'))
            else:
                return {'status': 'rejected', 'reason': 'No claim line items'}
        else:
            return {'status': 'rejected', 'reason': 'Exceeds coverage limit'}
    else:
        return {'status': 'rejected', 'reason': 'Policy inactive'}

    try:
        db.claims.update_one({'id': claim.id}, {'status': 'processed', 'amount': approved_total})
        for item_id, reason in rejected_items:
            db.claim_rejections.insert_one({'claim_id': claim.id, 'item_id': item_id, 'reason': reason})

        if approved_total > 0:
            payment_resp = payment_service.disburse(patient.bank_account, approved_total)
            if payment_resp.success:
                if patient.notify_sms and patient.phone:
                    notifier.send_sms(patient.phone, f'Claim approved: {approved_total}')
                if patient.notify_email and patient.email:
                    notifier.send_email(patient.email, 'Claim Payout Processed')
                return {'status': 'success', 'payout': approved_total, 'rejections': rejected_items}
            else:
                return {'status': 'payment_failed', 'error': payment_resp.error}
        return {'status': 'processed_zero_payout', 'rejections': rejected_items}
    except Exception as err:
        return {'status': 'error', 'message': str(err)}

