import ast
from typing import Any, Dict, List


def find_large_functions_that_do_too_many_things(
    source_code: str, max_lines: int = 50, max_complexity: int = 10
) -> List[Dict[str, Any]]:
    """Scan code to find large functions that violate single responsibility."""
    tree = ast.parse(source_code)
    flagged_functions = []

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            start_line = node.lineno
            end_line = getattr(node, "end_lineno", start_line)
            loc = end_line - start_line + 1

            complexity = 1
            for child in ast.walk(node):
                if isinstance(
                    child,
                    (
                        ast.If,
                        ast.While,
                        ast.For,
                        ast.AsyncFor,
                        ast.ExceptHandler,
                        ast.With,
                        ast.AsyncWith,
                    ),
                ):
                    complexity += 1
                elif isinstance(child, ast.BoolOp):
                    complexity += len(child.values) - 1

            if loc > max_lines and complexity > max_complexity:
                flagged_functions.append(
                    {
                        "name": node.name,
                        "line_number": start_line,
                        "lines_of_code": loc,
                        "cyclomatic_complexity": complexity,
                    }
                )

    return flagged_functions

