def process_insurance_claim(claim, policy, patient, ledger):
    approved_total, patient_owed = 0.0, 0.0
    adjudicated = []
    if policy.is_active:
        if claim.items:
            for item in claim.items:
                if item.code not in policy.excluded_codes:
                    if policy.deductible_remaining > 0:
                        if item.cost <= policy.deductible_remaining:
                            policy.deductible_remaining -= item.cost
                            patient_owed += item.cost
                        else:
                            rem = item.cost - policy.deductible_remaining
                            patient_owed += policy.deductible_remaining
                            policy.deductible_remaining = 0
                            if policy.patient_out_of_pocket >= policy.max_out_of_pocket:
                                approved_total += rem
                            else:
                                rate = 0.2 if claim.provider.is_in_network else 0.5
                                patient_owed += rem * rate
                                approved_total += rem * (1 - rate)
                    else:
                        rate = 0.1 if claim.provider.is_in_network else 0.3
                        patient_owed += item.cost * rate
                        approved_total += item.cost * (1 - rate)
                    adjudicated.append(item.code)
                else:
                    patient_owed += item.cost
        else:
            return {'error': 'Empty claim'}
    else:
        return {'error': 'Policy inactive'}

    for auth in patient.pre_authorizations:
        if auth.is_valid:
            for code in adjudicated:
                if code == auth.service_code:
                    if auth.override_allowed:
                        patient_owed = max(0.0, patient_owed - auth.waiver_amount)
                        approved_total += auth.waiver_amount

    try:
        tx = ledger.record_payout(claim.provider.id, approved_total)
        if tx.is_success:
            if patient.autopay_enabled:
                pt_tx = ledger.charge_patient(patient.id, patient_owed)
                if not pt_tx.is_success:
                    return {'status': 'ledger_split_error', 'details': pt_tx.error}
            return {'status': 'processed', 'approved': approved_total, 'patient_owed': patient_owed}
        return {'status': 'payout_rejected', 'reason': tx.error}
    except Exception as e:
        return {'status': 'exception', 'error': str(e)}

