                if loan_request.amount <= applicant.max_allowed_limit:
                    for account in applicant.bank_accounts:
                        if account.is_active and not account.is_frozen:
                            overdraft_count = 0
                            for tx in account.recent_transactions:
                                if tx.amount < 0:
                                    if abs(tx.amount) > account.balance:
                                        overdraft_count += 1
                                        if overdraft_count > 3:
                                            risk_factors.append("excessive_overdrafts")
                                            break
                            if overdraft_count <= 3:
                                if applicant.employment_status == "full_time":
                                    if applicant.monthly_income * 0.4 > loan_request.monthly_payment:
                                        approved_amount = loan_request.amount
                                    else:
                                        approved_amount = applicant.monthly_income * 0.4 * loan_request.term_months
                                        risk_factors.append("reduced_income_cap")
                                elif applicant.employment_status == "self_employed":
                                    if applicant.tax_returns_verified:
