            return {"status": "rejected", "reason": "applicant_blacklisted"}
    else:
        return {"status": "rejected", "reason": "identity_unverified"}
    if approved_amount > 0:
        try:
            risk_score = risk_engine.calculate(applicant, risk_factors)
            if risk_score < 75:
                audit_log.record(applicant.id, "approved", approved_amount)
                return {"status": "approved", "amount": approved_amount, "risks": risk_factors}
            else:
                audit_log.record(applicant.id, "rejected_high_risk", 0)
                return {"status": "rejected", "reason": "high_composite_risk"}
        except Exception as e:
            audit_log.record_error(applicant.id, str(e))
            return {"status": "error", "message": "risk_calculation_failure"}
    return {"status": "rejected", "reason": "qualification_criteria_unmet"}

