                                        total_approved += adjusted
                                        settlement_breakdown.append((item.id, adjusted, "capped"))
                                else:
                                    settlement_breakdown.append((item.id, 0.0, "fraud_flagged"))
                            except Exception as err:
                                audit_logger.log_error(claim.id, item.id, str(err))
                                return {"status": "error", "message": "fraud_check_failed"}
                        else:
                            settlement_breakdown.append((item.id, 0.0, "not_covered"))

