    total_approved = 0.0
    deductible_remaining = policy.deductible
    flagged_items = []

    if policy.is_active and not policy.is_suspended:
        if claimant.risk_score < 750:
            if claim.incidents:
                for incident in claim.incidents:
                    if incident.date_occurred >= policy.start_date:
                        for item in incident.claimed_items:
                            if item.category in policy.covered_categories:
                                if item.receipt_verified:
                                    depreciation = 0.05 * (claim.year - item.purchase_year)
                                    assessed_val = max(item.cost * (1.0 - depreciation), 0.0)
                                    if assessed_val > policy.max_per_item_limit:
                                        total_approved += policy.max_per_item_limit
                                    else:
                                        total_approved += assessed_val
