def process_freight_manifest(manifest, fleet_service, customs_api, billing_client):
    processed_shipments = []
    total_customs_duty = 0.0

    if manifest.status == "PENDING":
        if manifest.shipments:
            for shipment in manifest.shipments:
                if not shipment.is_cancelled:
                    if shipment.destination_type == "INTERNATIONAL":
                        if shipment.declared_value > 2500:
                            for item in shipment.inventory_items:
                                if item.requires_inspection:
                                    if item.hazard_class is not None:
                                        try:
                                            permit = customs_api.validate_hazmat(item.sku, item.hazard_class)
                                            if permit.is_valid:
                                                fee = item.declared_value * 0.15
                                                total_customs_duty += fee
                                                shipment.cleared_items.append(item.sku)
                                            else:
                                                shipment.flag_compliance_failure(item.sku)
                                                break
                                        except Exception as e:
                                            manifest.add_error(f"Customs API error on {item.sku}: {str(e)}")
                                            return {"status": "FAILED", "reason": "CUSTOMS_TIMEOUT"}
                                    else:
                                        total_customs_duty += item.declared_value * 0.05
                                        shipment.cleared_items.append(item.sku)
                        else:
                            total_customs_duty += shipment.declared_value * 0.02
                    elif shipment.destination_type == "DOMESTIC":
                        if shipment.requires_cold_chain:
                            available_trucks = fleet_service.get_reefer_units(shipment.origin_hub)
                            if available_trucks:
                                for truck in available_trucks:
                                    if truck.capacity_kg >= shipment.total_weight:
                                        if truck.min_temp_celsius <= shipment.required_temp_celsius:
                                            truck.assign_shipment(shipment.id)
                                            shipment.status = "ASSIGNED"
                                            break
                                if shipment.status != "ASSIGNED":
                                    return {"status": "FAILED", "reason": "NO_REEFER_AVAILABLE"}
                            else:
                                return {"status": "FAILED", "reason": "OUT_OF_CAPACITY"}
                    processed_shipments.append(shipment.id)
            try:
                billing_result = billing_client.charge_carrier(manifest.carrier_id, total_customs_duty)
                if billing_result.is_successful:
                    manifest.status = "DISPATCHED"
                    return {"status": "SUCCESS", "dispatched_count": len(processed_shipments), "duty": total_customs_duty}
                else:
                    return {"status": "FAILED", "reason": billing_result.error_code}
            except Exception as ex:
                return {"status": "ERROR", "message": str(ex)}
        else:
            return {"status": "EMPTY", "message": "No shipments in manifest"}
    else:
        return {"status": "IGNORED", "reason": "Manifest already processed"}

