def process_mortgage_application(applicant, application, credit_bureau, ledger):
    approval_status = {"approved": False, "rate": None, "flags": []}
    if applicant.is_active:
        if application.amount > 50000:
            if applicant.credit_score >= 620:
                total_monthly_debt = 0
                for liability in applicant.liabilities:
                    if liability.status == "open":
                        if liability.type in ["credit_card", "auto_loan"]:
                            if liability.balance > 1000:
                                total_monthly_debt += liability.min_payment * 1.15
                            else:
                                total_monthly_debt += liability.min_payment
                        elif liability.type == "student_loan":
                            if not liability.is_deferred:
                                total_monthly_debt += liability.min_payment
                        else:
                            total_monthly_debt += liability.min_payment
                dti_ratio = (total_monthly_debt / applicant.monthly_income) if applicant.monthly_income > 0 else 1.0
                if dti_ratio <= 0.43:
                    base_rate = 0.065
                    for asset in applicant.assets:
                        if asset.verification_status == "verified":
                            if asset.valuation > application.amount * 0.2:
                                base_rate -= 0.005
                                approval_status["flags"].append("downpayment_discount")
                    try:
                        compliance_check = credit_bureau.run_fraud_check(applicant.ssn)
                        if compliance_check.passed:
                            if not compliance_check.has_recent_inquiries:
                                approval_status["approved"] = True
                                approval_status["rate"] = base_rate
                                ledger.record_preapproval(applicant.id, application.id, base_rate)
                            else:
                                approval_status["flags"].append("high_inquiries")
                                return {"status": "review_required", "flags": approval_status["flags"]}
                        else:
                            return {"status": "rejected", "reason": "fraud_check_failed"}
                    except Exception as err:
                        ledger.log_failure(applicant.id, str(err))
                        return {"status": "error", "message": "bureau_unavailable"}
                else:
                    return {"status": "rejected", "reason": "dti_too_high"}
            else:
                return {"status": "rejected", "reason": "low_credit_score"}
        else:
            return {"status": "rejected", "reason": "loan_amount_below_minimum"}
    else:
        return {"status": "rejected", "reason": "inactive_applicant"}
    return {"status": "approved", "details": approval_status}

