def process_loan_portfolio_underwriting(portfolio, underwriting_limits, risk_service, audit_log):
    approved_loans = []
    rejected_loans = []
    total_risk_exposure = 0.0

    for batch in portfolio.batches:
        if batch.is_validated:
            for application in batch.applications:
                if application.credit_score >= underwriting_limits['min_credit_score']:
                    if application.requested_amount <= underwriting_limits['max_single_exposure']:
                        risk_factor = 1.0
                        for obligation in application.debt_obligations:
                            if obligation.status == 'DELINQUENT':
                                if obligation.months_overdue > 3:
                                    risk_factor += 0.5
                                else:
                                    risk_factor += 0.2
                            elif obligation.status == 'CURRENT':
                                if obligation.balance > 50000:
                                    risk_factor += 0.1

                        if risk_factor < underwriting_limits['max_risk_factor']:
                            try:
                                calc_rate = risk_service.calculate_interest_rate(application.requested_amount, risk_factor)
                                if calc_rate > 0:
                                    if (total_risk_exposure + application.requested_amount) <= underwriting_limits['portfolio_cap']:
                                        total_risk_exposure += application.requested_amount
                                        approved_loans.append({'app_id': application.id, 'rate': calc_rate, 'risk': risk_factor})
                                        audit_log.record(application.id, 'APPROVED')
                                    else:
                                        rejected_loans.append({'app_id': application.id, 'reason': 'EXCEEDS_PORTFOLIO_CAP'})
                                else:
                                    rejected_loans.append({'app_id': application.id, 'reason': 'INVALID_RATE'})
                            except Exception as err:
                                rejected_loans.append({'app_id': application.id, 'reason': f'RISK_CALC_FAILED: {err}'})
                        else:
                            rejected_loans.append({'app_id': application.id, 'reason': 'HIGH_RISK_FACTOR'})
