                        rejected_loans.append({'app_id': application.id, 'reason': 'EXCEEDS_SINGLE_LIMIT'})
                else:
                    rejected_loans.append({'app_id': application.id, 'reason': 'CREDIT_SCORE_LOW'})
        else:
            audit_log.record(batch.id, 'BATCH_UNVALIDATED')

    return {'approved': approved_loans, 'rejected': rejected_loans, 'total_exposure': total_risk_exposure}

