import ast

def find_deeply_nested_functions(source_code: str, max_depth: int = 4) -> list[dict]:
    tree = ast.parse(source_code)
    deep_functions = []

    block_types = (
        ast.If,
        ast.For,
        ast.While,
        ast.Try,
        ast.With,
        ast.FunctionDef,
        ast.AsyncFunctionDef,
        ast.ClassDef,
    )

    def measure_depth(node: ast.AST, current_depth: int = 0) -> int:
        child_depths = [current_depth]
        for child in ast.iter_child_nodes(node):
            if isinstance(child, block_types):
                child_depths.append(measure_depth(child, current_depth + 1))
            else:
                child_depths.append(measure_depth(child, current_depth))
        return max(child_depths)

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            nesting_level = measure_depth(node, 0)
            if nesting_level >= max_depth:
                deep_functions.append({
                    "name": node.name,
                    "lineno": node.lineno,
                    "max_depth": nesting_level,
                })

    return deep_functions

