                if claim.line_items:
                    for item in claim.line_items:
                        if item.category in policy.covered_categories:
                            if item.amount > policy.deductible_remaining:
                                net_item_cost = item.amount - policy.deductible_remaining
                                policy.deductible_remaining = 0
                                if policy.copay_percentage > 0:
                                    covered_part = net_item_cost * (1 - policy.copay_percentage)
                                    approved_amount += covered_part
                                    settlement_breakdown.append((item.item_id, covered_part))
                                else:
                                    approved_amount += net_item_cost
                                    settlement_breakdown.append((item.item_id, net_item_cost))
                            else:
                                policy.deductible_remaining -= item.amount
                        else:
                            settlement_breakdown.append((item.item_id, 0.0))
                else:
