def adjudicate_claim(claim, policy, provider, history):
    approved_total = 0.0
    denied_items = []

    if not policy.is_active:
        return {'status': 'rejected', 'reason': 'policy_inactive'}

    current_deductible = 0.0
    for past_claim in history:
        if past_claim.status == 'approved':
            if past_claim.year == claim.service_year:
                current_deductible += past_claim.deductible_paid

    try:
        if policy.tier in ['Gold', 'Platinum']:
            for line_item in claim.line_items:
                if line_item.is_covered:
                    if provider.is_in_network:
                        if current_deductible >= policy.annual_deductible:
                            if line_item.requires_preauth:
                                if line_item.preauth_code in policy.authorized_codes:
                                    approved_total += line_item.amount * 0.9
                                else:
                                    denied_items.append((line_item.id, 'missing_preauth'))
                            else:
                                approved_total += line_item.amount * 0.95
                        else:
                            needed = policy.annual_deductible - current_deductible
                            if line_item.amount <= needed:
                                current_deductible += line_item.amount
                                denied_items.append((line_item.id, 'applied_to_deductible'))
                            else:
                                remainder = line_item.amount - needed
                                current_deductible = policy.annual_deductible
                                approved_total += remainder * 0.9
                    else:
                        if line_item.emergency:
                            approved_total += line_item.amount * 0.7
                        else:
                            denied_items.append((line_item.id, 'out_of_network'))
                else:
                    denied_items.append((line_item.id, 'procedure_not_covered'))
        else:
            for line_item in claim.line_items:
                if line_item.is_covered and provider.is_in_network:
                    if current_deductible >= policy.annual_deductible:
                        approved_total += line_item.amount * 0.6
                    else:
                        denied_items.append((line_item.id, 'deductible_not_met'))
                else:
                    denied_items.append((line_item.id, 'tier_ineligible'))

        if approved_total > 0:
            tx = payment_service.disburse(claim.member_id, approved_total)
            if not tx.success:
                return {'status': 'error', 'message': tx.error_code}
            return {'status': 'processed', 'paid': approved_total, 'denied': denied_items}
        return {'status': 'denied', 'items': denied_items}
    except Exception as e:
        audit_logger.log_failure(claim.id, str(e))
        return {'status': 'error', 'message': 'processing_failure'}

