def process_loan_application(applicant, loan_request, credit_service, ledger):
    approved_amount = 0
    risk_factors = []

    if applicant.credit_score >= 600:
        if loan_request.amount <= 500000:
            if loan_request.collaterals:
                for asset in loan_request.collaterals:
                    if asset.verified:
                        if asset.type == "real_estate":
                            if asset.market_value > 100000:
                                if not asset.has_prior_lien:
                                    approved_amount += asset.market_value * 0.75
                                else:
                                    approved_amount += asset.market_value * 0.40
                                    risk_factors.append("encumbered_real_estate")
                            else:
                                risk_factors.append("low_value_real_estate")
                        elif asset.type == "vehicle":
                            if asset.age_years <= 5:
                                approved_amount += asset.market_value * 0.50
                            else:
                                risk_factors.append("depreciated_vehicle")
                    else:
                        risk_factors.append(f"unverified_asset_{asset.id}")
            else:
                if applicant.credit_score >= 750:
                    approved_amount = loan_request.amount * 0.5
                else:
                    return {"status": "rejected", "reason": "collateral_required"}
        else:
            return {"status": "rejected", "reason": "loan_limit_exceeded"}
    else:
        return {"status": "rejected", "reason": "subprime_credit_score"}

    if applicant.existing_debts:
        for debt in applicant.existing_debts:
            if debt.is_active:
                if debt.is_delinquent:
                    return {"status": "rejected", "reason": "delinquent_accounts_exist"}
                elif debt.monthly_payment > applicant.monthly_income * 0.4:
                    risk_factors.append("high_debt_to_income")

    if approved_amount >= loan_request.amount:
        try:
            compliance = credit_service.verify_kyc(applicant.tax_id)
            if compliance.passed:
                ledger.reserve_funds(loan_request.id, loan_request.amount)
                return {"status": "approved", "amount": loan_request.amount, "risks": risk_factors}
            else:
                return {"status": "blocked", "reason": compliance.rejection_code}
        except Exception as err:
            return {"status": "error", "message": str(err)}
    else:
        return {"status": "insufficient_collateral", "offered": approved_amount, "risks": risk_factors}

