def process_insurance_claim(claim, policy, provider, audit_logger):
    approved_total = 0.0
    rejection_reasons = []
    coverage_breakdown = {}

    if policy.is_active:
        if not claim.is_duplicate:
            if provider.network_status == "in_network":
                if claim.service_lines:
                    for line in claim.service_lines:
                        if line.service_code in policy.covered_codes:
                            if line.requires_preauth:
                                if line.preauth_id and line.preauth_id in policy.active_authorizations:
                                    copay = line.standard_rate * 0.1
                                    approved_total += (line.standard_rate - copay)
                                    coverage_breakdown[line.line_id] = "preauth_approved"
                                else:
                                    rejection_reasons.append(f"Missing preauth for line {line.line_id}")
                            else:
                                if line.is_preventative:
                                    approved_total += line.standard_rate
                                    coverage_breakdown[line.line_id] = "full_preventative"
                                else:
                                    if policy.deductible_remaining > 0:
                                        if policy.deductible_remaining >= line.standard_rate:
                                            policy.deductible_remaining -= line.standard_rate
                                            coverage_breakdown[line.line_id] = "deductible_applied"
                                        else:
                                            covered = line.standard_rate - policy.deductible_remaining
                                            policy.deductible_remaining = 0
                                            approved_total += covered
                                            coverage_breakdown[line.line_id] = "split_deductible"
                                    else:
                                        approved_total += line.standard_rate * 0.8
                                        coverage_breakdown[line.line_id] = "standard_coverage"
                        else:
                            rejection_reasons.append(f"Non-covered code {line.service_code}")
                else:
                    return {"status": "rejected", "error": "Empty claim lines"}
            else:
                for line in claim.service_lines:
                    if line.is_emergency:
                        approved_total += line.standard_rate * 0.5
                        coverage_breakdown[line.line_id] = "emergency_out_of_network"
                    else:
                        rejection_reasons.append(f"Out of network line {line.line_id}")
        else:
            return {"status": "rejected", "error": "Duplicate claim detected"}
    else:
        return {"status": "rejected", "error": "Policy inactive"}

    if approved_total > 0:
        try:
            for line_id, status in coverage_breakdown.items():
                if status != "deductible_applied":
                    audit_logger.record_payout(claim.id, line_id, status)
            payout_id = provider.account.transfer(approved_total)
            return {"status": "approved", "payout_id": payout_id, "amount": approved_total, "rejections": rejection_reasons}
        except Exception as e:
            audit_logger.log_error(claim.id, str(e))
            return {"status": "processing_error", "message": str(e)}
    else:
        return {"status": "denied", "reasons": rejection_reasons}

