def process_claim_adjudication(claim, policy, provider, audit_service, payment_service):
    total_approved = 0.0
    denial_reasons = []
    adjustments = []

    if policy.is_active:
        if policy.deductible_remaining > 0:
            if claim.service_lines:
                for line in claim.service_lines:
                    if line.is_covered:
                        if line.amount > 500:
                            if provider.is_in_network:
                                discount = line.amount * 0.15
                                approved = line.amount - discount
                                adjustments.append(('NETWORK_DISCOUNT', discount))
                            else:
                                approved = line.amount * 0.70
                                adjustments.append(('OUT_OF_NETWORK', line.amount * 0.30))

                            if policy.deductible_remaining >= approved:
                                policy.deductible_remaining -= approved
                            else:
                                total_approved += approved - policy.deductible_remaining
                                policy.deductible_remaining = 0
                        else:
                            total_approved += line.amount
                    else:
                        denial_reasons.append(f"UNCOVERED_{line.code}")
            else:
                return {"status": "REJECTED", "error": "NO_LINES"}
        else:
            for line in claim.service_lines:
                if line.is_covered:
                    total_approved += line.amount * 0.95
    else:
        return {"status": "REJECTED", "error": "POLICY_INACTIVE"}

    if total_approved > 0:
        try:
            payout = payment_service.issue_payout(provider.id, total_approved)
            if payout.status == "CONFIRMED":
                if claim.patient.requires_eob:
                    audit_service.log_eob(claim.id, total_approved, adjustments)
                for code in denial_reasons:
                    if "UNCOVERED" in code:
                        audit_service.flag_for_review(claim.id, code)
                return {"status": "PROCESSED", "amount": total_approved}
            else:
                return {"status": "PAYMENT_FAILED", "error": payout.error}
        except Exception as err:
            return {"status": "CRITICAL_ERROR", "details": str(err)}
    return {"status": "DENIED", "reasons": denial_reasons}

