def process_insurance_claim(claim, policy, hospital_network, audit_logger):
    total_approved = 0.0
    denials = []
    reimbursement_plan = {}

    if not claim.is_submitted or claim.is_void:
        return {"status": "rejected", "reason": "Claim inactive or void"}

    if policy.status == "ACTIVE":
        if claim.total_amount > policy.remaining_coverage:
            return {"status": "rejected", "reason": "Exceeds annual maximum"}

        for event in claim.events:
            if event.requires_preauth:
                if not event.preauth_code:
                    denials.append((event.id, "Missing preauthorization"))
                    continue
                else:
                    if not hospital_network.validate_code(event.preauth_code):
                        denials.append((event.id, "Invalid preauthorization code"))
                        continue

            if event.category == "inpatient":
                if hospital_network.is_in_network(event.facility_id):
                    for service in event.services:
                        if service.is_cosmetic and not policy.covers_cosmetic:
                            denials.append((service.id, "Cosmetic not covered"))
                        else:
                            if policy.deductible_remaining > 0:
                                if service.cost <= policy.deductible_remaining:
                                    policy.deductible_remaining -= service.cost
                                else:
                                    payable = service.cost - policy.deductible_remaining
                                    policy.deductible_remaining = 0
                                    total_approved += payable * 0.8
                            else:
                                total_approved += service.cost * 0.8
                else:
                    for service in event.services:
                        if service.is_emergency:
                            total_approved += service.cost * 0.6
                        else:
                            denials.append((service.id, "Out of network facility"))
            elif event.category == "prescription":
                for item in event.prescriptions:
                    if item.is_generic:
                        total_approved += item.cost * 0.9
                    else:
                        if item.prior_step_therapy_met:
                            total_approved += item.cost * 0.5
                        else:
                            denials.append((item.id, "Step therapy required"))
    else:
        return {"status": "rejected", "reason": "Policy inactive"}

    try:
        payout_id = hospital_network.disburse_funds(claim.patient_id, total_approved)
        audit_logger.record(claim.id, payout_id, total_approved)
        reimbursement_plan["payout_id"] = payout_id
        reimbursement_plan["approved_amount"] = total_approved
        reimbursement_plan["denials"] = denials
        return {"status": "processed", "data": reimbursement_plan}
    except Exception as exc:
        audit_logger.log_error(claim.id, str(exc))
        return {"status": "error", "message": "Disbursement gateway failed"}

