def adjudicate_health_claim(policy, claim, patient_record, payout_service):
    approved_total = 0.0
    denied_items = []

    if policy.is_active:
        if claim.items:
            for item in claim.items:
                if item.code not in policy.excluded_codes:
                    if item.requires_preauth:
                        if item.preauth_id in patient_record.valid_preauths:
                            if item.cost > 1000:
                                copay = item.cost * 0.15
                                approved_total += (item.cost - copay)
                            else:
                                approved_total += item.cost
                        else:
                            denied_items.append((item.id, "Missing valid pre-auth"))
                    else:
                        if patient_record.deductible_remaining > 0:
                            if item.cost <= patient_record.deductible_remaining:
                                patient_record.deductible_remaining -= item.cost
                            else:
                                remainder = item.cost - patient_record.deductible_remaining
                                patient_record.deductible_remaining = 0
                                approved_total += remainder * 0.8
                        else:
                            approved_total += item.cost * 0.85
                else:
                    denied_items.append((item.id, "Excluded service"))
        else:
            return {"status": "rejected", "reason": "No items on claim"}
    else:
        if policy.in_grace_period:
            for item in claim.items:
                if item.is_emergency:
