                else:
                    denied_items.append((item.id, "Policy in grace - non-emergency"))
        else:
            return {"status": "rejected", "reason": "Inactive policy"}

    if approved_total > 0:
        try:
            payout = payout_service.issue_reimbursement(policy.holder_id, approved_total)
