import ast
import os
from typing import Any, Dict, List


class BranchingComplexityVisitor(ast.NodeVisitor):
    def __init__(self):
        self.complexity = 1

    def visit_If(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_For(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_AsyncFor(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_While(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_ExceptHandler(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_BoolOp(self, node):
        self.complexity += len(node.values) - 1
        self.generic_visit(node)

    def visit_Match(self, node):
        self.complexity += len(node.cases)
        self.generic_visit(node)


def find_technical_debt_hotspots(
    repo_path: str, min_complexity: int = 10
) -> List[Dict[str, Any]]:
    """Scan directory to find technical debt hotspots with high branching complexity."""
    hotspots = []

    for root, _, files in os.walk(repo_path):
        for file in files:
            if not file.endswith(".py"):
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    content = f.read()
                tree = ast.parse(content, filename=file_path)
            except (SyntaxError, UnicodeDecodeError):
                continue

            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    visitor = BranchingComplexityVisitor()
                    for statement in node.body:
                        visitor.visit(statement)

                    if visitor.complexity >= min_complexity:
                        hotspots.append(
                            {
                                "file_path": file_path,
                                "function_name": node.name,
                                "line_number": node.lineno,
                                "branching_complexity": visitor.complexity,
                                "debt_level": (
                                    "critical"
                                    if visitor.complexity >= 25
                                    else "high"
                                ),
                            }
                        )

    return sorted(
        hotspots, key=lambda item: item["branching_complexity"], reverse=True
    )

