    """Fetch URL, retry transient failures, then try fallback mirrors."""
    errors = []
    candidates = [url] + [
        mirror.format(path=url.split("://", 1)[-1])
        for mirror in ("https://mirror1.example/{path}", "https://mirror2.example/{path}")
    ]

    for candidate in candidates:
        for attempt in range(retries):
            try:
                response = requests.get(
                    candidate,
                    timeout=timeout,
                    verify=verify_ssl,
                    headers={"Accept": "application/json"},
                )
            except requests.exceptions.SSLError as exc:
                errors.append(f"SSL error for {candidate}: {exc}")
                if not verify_ssl:
                    try:
                        response = requests.get(
                            candidate,
                            timeout=timeout,
                            verify=False,
                            headers={"Accept": "application/json"},
                        )
                    except requests.exceptions.RequestException as fallback_exc:
                        errors.append(f"Fallback request failed: {fallback_exc}")
                        break
                else:
                    break
            except requests.exceptions.Timeout as exc:
                errors.append(f"Timeout for {candidate}: {exc}")
                continue
            except requests.exceptions.ConnectionError as exc:
                errors.append(f"Connection error for {candidate}: {exc}")
                continue
            except requests.exceptions.TooManyRedirects as exc:
                errors.append(f"Too many redirects for {candidate}: {exc}")
                break
            except requests.exceptions.InvalidURL as exc:
                errors.append(f"Invalid URL {candidate}: {exc}")
                break
            except requests.exceptions.RequestException as exc:
                errors.append(f"Request failed for {candidate}: {exc}")
                break
            except Exception as exc:
                errors.append(f"Unexpected error for {candidate}: {exc}")
                break

            try:
                response.raise_for_status()
            except requests.exceptions.HTTPError as exc:
                status = exc.response.status_code if exc.response is not None else None
                errors.append(f"HTTP {status} for {candidate}: {exc}")

                if status in (429, 500, 502, 503, 504):
                    retry_after = exc.response.headers.get("Retry-After")
                    try:
                        delay = float(retry_after)
                    except (TypeError, ValueError):
                        delay = 2 ** attempt
                    time.sleep(min(delay, 30))
                    continue
                break
            except ValueError as exc:
                errors.append(f"Invalid response for {candidate}: {exc}")
                break

            try:
                content_type = response.headers.get("Content-Type", "")
                if "application/json" in content_type:
                    return response.json()
                if "text/" in content_type:
                    return response.text
                return response.content
            except requests.exceptions.JSONDecodeError as exc:
                errors.append(f"JSON decode failed for {candidate}: {exc}")
                break
            except UnicodeDecodeError as exc:
                errors.append(f"Decode failed for {candidate}: {exc}")
                break
            except Exception as exc:
                errors.append(f"Response processing failed for {candidate}: {exc}")
                break

    raise ResourceFetchError(
        f"Unable to fetch {url}; attempts: " + " | ".join(errors)
    ) from (errors[-1] if errors else None)

