def handle_request(request_type, payload=None):
    match request_type:
        case "create":
            return {"status": "created", "data": payload}
        case "read":
            return {"status": "ok", "data": payload}
        case "update":
            return {"status": "updated", "data": payload}
        case "delete":
            return {"status": "deleted", "data": payload}
        case "list":
            return {"status": "ok", "items": payload or []}
        case "search":
            query = payload.get("query", "") if payload else ""
            return {"status": "ok", "query": query}
        case "batch":
            results = [handle_request(item["type"], item.get("data")) for item in payload or []]
