import ast


def find_deeply_indented_functions(source: str, min_indent: int = 4) -> list[tuple[str, int, int]]:
    """Return function name, indentation width, and line number."""
    matches = []

    class FunctionFinder(ast.NodeVisitor):
        def visit_function(self, node):
            if node.col_offset >= min_indent:
                matches.append((node.name, node.col_offset, node.lineno))
            self.generic_visit(node)

        visit_FunctionDef = visit_function
        visit_AsyncFunctionDef = visit_function

    FunctionFinder().visit(ast.parse(source))
    return matches

