                surcharge = base_cost * fuel_surcharge_rate
                total_cost += base_cost + surcharge
                manifest.append((shipment.id, 0, shipment.weight, base_cost + surcharge))

        except AttributeError as e:
            retry_queue.append(shipment)
            rejected.append((shipment.id, f'missing_field: {str(e)}'))
        except Exception as e:
            rejected.append((shipment.id, f'unknown_error: {str(e)}'))

    if total_cost > 0:
        if warehouse.email:
            notification_service.send_email(wareh

