def calculate_shipment_cost(order, warehouse, carrier, destination, insurance_opted, fragile_items, customer_tier, fuel_surcharge_rate, peak_season, weight_unit='kg'):
    base_cost = 0
    surcharges = []
    try:
        if warehouse.inventory:
            for item in order.items:
                found = False
                for stock in warehouse.inventory:
                    if stock.sku == item.sku:
                        found = True
                        if stock.quantity < item.quantity:
                            return {'error': 'Insufficient stock', 'sku': item.sku}
                        if item.weight > 50:
                            if carrier.type == 'air':
                                if peak_season:
                                    rate = carrier.air_rate * 1.3
                                else:
                                    rate = carrier.air_rate
                                base_cost += item.weight * rate
                            else:
                                base_cost += item.weight * carrier.ground_rate
                        else:
                            if item.category in fragile_items:
                                base_cost += item.weight * carrier.ground_rate * 1.15
                                surcharges.append(('fragile_handling', item.sku))
                            else:
                                base_cost += item.weight * carrier.ground_rate
                        break
                if not found:
                    return {'error': 'Item not in warehouse', 'sku': item.sku}
        else:
            return {'error': 'Warehouse empty'}

        if destination.zone == 'international':
            if customer_tier == 'gold':
                base_cost *= 0.9
            elif customer_tier == 'silver':
                base_cost *= 0.95
            base_cost += destination.customs_fee
        elif destination.zone == 'remote':
            base_cost += 25.0
            if carrier.type == 'air':
                base_cost *= 1.2

        base_cost += base_cost * fuel_surcharge_rate

        if insurance_opted:
            if order.declared_value > 1000:
                base_cost += order.declared_value * 0.02
            else:
                base_cost += order.declared_value * 0.01

        if base_cost > 0:
            try:
                rate_result = carrier.quote_api.confirm(destination.address, base_cost)
                if rate_result.confirmed:
                    return {'status': 'confirmed', 'cost': base_cost, 'surcharges': surcharges}
                else:
                    return {'status': 'rejected', 'reason': rate_result.reason}
            except Exception as e:
                return {'status': 'error', 'message': str(e)}
        else:
            return {'error': 'Invalid cost computed'}
    except AttributeError as e:
        return {'status': 'error', 'message': f'Missing data: {str(e)}'}

