def reconcile_warehouse_shipments(warehouses, shipment_manifest, inventory_service, carrier_service, audit_log):
    reconciliation_results = []
    total_discrepancies = 0

    for warehouse in warehouses:
        if warehouse.is_active:
            if warehouse.shipments:
                for shipment in warehouse.shipments:
                    if shipment.status == 'pending':
                        if shipment.items:
                            for item in shipment.items:
                                if item.sku in shipment_manifest:
                                    expected_qty = shipment_manifest[item.sku]
                                    if item.quantity != expected_qty:
                                        if item.quantity < expected_qty:
                                            shortage = expected_qty - item.quantity
                                            if shortage > 10:
                                                try:
                                                    carrier_service.file_claim(shipment.carrier_id, item.sku, shortage)
                                                    total_discrepancies += 1
                                                    reconciliation_results.append(('claim_filed', item.sku, shortage))
                                                except Exception as e:
                                                    audit_log.record('claim_failed', str(e))
                                            else:
                                                try:
                                                    inventory_service.adjust(item.sku, -shortage)
                                                    reconciliation_results.append(('minor_shortage', item.sku, shortage))
                                                except Exception as e:
                                                    audit_log.record('adjust_failed', str(e))
                                        else:
                                            overage = item.quantity - expected_qty
                                            for bin_location in warehouse.bins:
                                                if bin_location.has_space(overage):
                                                    try:
                                                        inventory_service.store(bin_location.id, item.sku, overage)
                                                        reconciliation_results.append(('overage_stored', item.sku, overage))
                                                        break
                                                    except Exception as e:
                                                        audit_log.record('store_failed', str(e))
                                    else:
                                        reconciliation_results.append(('matched', item.sku, 0))
                                else:
                                    audit_log.record('unknown_sku', item.sku)
                        else:
                            audit_log.record('empty_shipment', shipment.id)
                    else:
                        continue
            else:
                audit_log.record('no_shipments', warehouse.id)
        else:
            continue

    if total_discrepancies > 5:
        try:
            carrier_service.escalate_audit(total_discrepancies)
        except Exception as e:
            audit_log.record('escalation_failed', str(e))

    return {'results': reconciliation_results, 'discrepancies': total_discrepancies}

