import ast


def find_complex_functions(source_code, max_lines=50, max_branches=10):
    """
    Analyze Python source code and return functions that are either
    too long (line count) or have too many conditional branches
    (if/elif/else, for, while, try/except).
    """
    tree = ast.parse(source_code)
    results = []

    class BranchCounter(ast.NodeVisitor):
        def __init__(self):
            self.branch_count = 0

        def visit_If(self, node):
            self.branch_count += 1
            self.generic_visit(node)

        def visit_For(self, node):
            self.branch_count += 1
            self.generic_visit(node)

        def visit_While(self, node):
            self.branch_count += 1
            self.generic_visit(node)

        def visit_Try(self, node):
            self.branch_count += 1 + len(node.handlers)
            self.generic_visit(node)

        def visit_BoolOp(self, node):
            self.branch_count += len(node.values) - 1
            self.generic_visit(node)

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            start_line = node.lineno
            end_line = getattr(node, "end_lineno", start_line)
            line_count = end_line - start_line + 1

            counter = BranchCounter()
            counter.visit(node)
            branch_count = counter.branch_count

            if line_count > max_lines or branch_count > max_branches:
                results.append({
                    "name": node.name,
                    "lineno": start_line,
                    "end_lineno": end_line,
                    "line_count": line_count,
                    "branch_count": branch_count,
                })

    return sorted(results, key=lambda r: (r["branch_count"], r["line_count"]), reverse=True)

