    """
    Analyze Python source code to find long functions with many
    conditional branches (high cyclomatic complexity indicators).

    Args:
        source_code: string containing Python source
        min_lines: minimum line count to be considered "long"
        min_branches: minimum branch count to be considered "complex"

    Returns:
        list of dicts with function name, line count, branch count, lineno
    """
    tree = ast.parse(source_code)
    results = []

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            start_line = node.lineno
            end_line = getattr(node, "end_lineno", start_line)
            line_count = end_line - start_line + 1

            branch_count = count_branches(node)

            if line_count >= min_lines or branch_count >= min_branches:
                results.append({
                    "name": node.name,
                    "lineno": start_line,
                    "end_lineno": end_line,
                    "line_count": line_count,
                    "branch_count": branch_count,
                })

    results.sort(key=lambda r: (r["branch_count"], r["line_count"]), reverse=True)
    return results


def count_branches(func_node):
    """
    Count conditional branches within a function node.
    Counts if/elif, for, while, try/except, and boolean operators
    as contributors to branching complexity.
    """
    branch_count = 1  # base complexity

    for child in ast.walk(func_node):
        if isinstance(child, ast.If):
            branch_count += 1
        elif isinstance(child, (ast.For, ast.AsyncFor)):
            branch_count += 1
        elif isinstance(child, ast.While):
            branch_count += 1
        elif isinstance(child, ast.Try):
            branch_count += len(child.handlers)
        elif isinstance(child, ast.BoolOp):
            branch_count += len(child.values) - 1
        elif isinstance(child, (ast.comprehension,)):
            branch_count += len(child.ifs)
        elif isinstance(child, ast.Match):
            branch_count += len(child.cases)

    return branch_count


def analyze_file(filepath, min_lines=50, min_branches=10):
    """
    Read a Python file and find long, branch-heavy functions.
    """
