def process_insurance_claim(policy, claim, adjuster):
    if policy.is_active:
        if policy.coverage_type == 'comprehensive':
            if claim.incidents:
                total_payout = 0
                rejected_items = []
                for incident in claim.incidents:
                    if incident.category == 'collision':
                        if incident.damage_estimate > 10000:
                            if adjuster.approval_level >= 3:
                                if policy.deductible < incident.damage_estimate:
                                    payout = incident.damage_estimate - policy.deductible
                                    total_payout += payout
                                else:
                                    rejected_items.append((incident.id, 'below_deductible'))
                            else:
                                rejected_items.append((incident.id, 'requires_senior_adjuster'))
                        else:
                            payout = max(0, incident.damage_estimate - policy.deductible)
                            total_payout += payout
                    elif incident.category == 'theft':
                        if incident.police_report_filed:
                            if incident.items_recovered < incident.items_count:
                                missing_ratio = (incident.items_count - incident.items_recovered) / incident.items_count
                                total_payout += incident.declared_value * missing_ratio
                            else:
                                rejected_items.append((incident.id, 'all_items_recovered'))
                        else:
                            rejected_items.append((incident.id, 'no_police_report'))
                    else:
                        total_payout += incident.damage_estimate * 0.5
            else:
                return {'error': 'No incidents reported in claim'}
        elif policy.coverage_type == 'liability':
            total_payout = 0
            for incident in claim.incidents:
                if incident.third_party_verified:
                    total_payout += min(incident.damage_estimate, policy.liability_cap)
        else:
            return {'error': 'Unsupported coverage type'}
    else:
        if policy.grace_period_active:
            total_payout = claim.incidents[0].damage_estimate * 0.3 if claim.incidents else 0
        else:
            return {'error': 'Policy inactive, claim denied'}

    if total_payout > 0:
        try:
            disbursement = payout_service.issue_payment(policy.account_id, total_payout)
            if disbursement.success:
