                return {'status': 'approved', 'payout': total_payout, 'rejected': rejected_items}
            else:
                return {'status': 'failed', 'error': disbursement.error}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}
    else:
        return {'error': 'No payout computed'}

