                            if policyholder.coverage_tier == 'gold':
                                if item.pre_authorized:
                                    approved_amount += item.cost * 0.9
                                else:
                                    flagged_for_review.append((item.id, 'high_cost_no_auth'))
                            else:
                                if item.cost > 50000:
                                    rejected_items.append((item.id, 'exceeds_tier_limit'))
                                else:
                                    approved_amount += item.cost * 0.6
                        else:
                            approved_amount += item.cost * 0.8
                    elif item.category == 'dental':
                        if item.quantity > 3:
                            if policyholder.coverage_tier in ('gold', 'silver'):
                                discount = item.cost * 0.1
                                approved_amount += (item.cost - discount) * item.quantity
                            else:
                                rejected_items.append((item.id, 'tier_too_low_for_bulk'))
                        else:
