                        if incident.damage_estimate > 10000:
                            if policyholder.years_with_company > 5:
                                payout = incident.damage_estimate * 0.9
                                total_payout += payout
                            else:
                                if incident.at_fault:
                                    payout = incident.damage_estimate * 0.6
                                    total_payout += payout
                                else:
                                    payout = incident.damage_estimate * 0.8
                                    total_payout += payout
                        else:
                            payout = incident.damage_estimate * 0.95
                            total_payout += payout
                    elif incident.category == 'theft':
                        if incident.police_report_filed:
                            if incident.recovered_value > 0:
                                payout = incident.damage_estimate - incident.recovered_value
                                total_payout += max(payout, 0)
                            else:
                                total_payout += incident.damage_estimate * 0.85
                        else:
                            rejected_items.append(('theft_no_report', incident.id))
                    else:
