                            rejected_items.append(('invalid_estimate', incident.id))
            else:
                return {'error': 'No incidents in claim'}
        else:
            for incident in claim.incidents:
                if incident.category == 'collision' and incident.at_fault is False:
                    total_payout = incident.damage_estimate * 0.5
                else:
                    rejected_items = [('not_covered', incident.id)]
    else:
