import ast


def get_most_complex_functions(source_code, top_n=10):
    """
    Analyze Python source code and return the functions with the most
    decision points (branches) and execution paths, ranked by an
    approximation of cyclomatic complexity.

    Decision points counted: if, elif, for, while, except, with,
    boolean operators (and/or), assert, comprehension conditions,
    ternary expressions (IfExp), and match-case branches.

    Returns a list of dicts sorted descending by complexity:
        [{"name": str, "lineno": int, "complexity": int, "decision_points": int}, ...]
    """
    tree = ast.parse(source_code)
    results = []

    class ComplexityVisitor(ast.NodeVisitor):
        def __init__(self):
            self.decision_points = 0

        def generic_decision(self, node):
            self.decision_points += 1
            self.generic_visit(node)

        def visit_If(self, node):
            self.generic_decision(node)

        def visit_For(self, node):
            self.generic_decision(node)

        def visit_AsyncFor(self, node):
            self.generic_decision(node)

        def visit_While(self, node):
            self.generic_decision(node)

        def visit_Try(self, node):
            self.decision_points += len(node.handlers)
            self.generic_visit(node)

        def visit_ExceptHandler(self, node):
            self.generic_visit(node)

        def visit_With(self, node):
            self.decision_points += len(node.items)
            self.generic_visit(node)

        def visit_AsyncWith(self, node):
            self.decision_points += len(node.items)
            self.generic_visit(node)

        def visit_BoolOp(self, node):
            self.decision_points += len(node.values) - 1
            self.generic_visit(node)

        def visit_Assert(self, node):
            self.generic_decision(node)

        def visit_IfExp(self, node):
            self.generic_decision(node)

        def visit_comprehension(self, node):
            self.decision_points += len(node.ifs)
            self.generic_visit(node)

        def visit_Match(self, node):
            self.decision_points += len(node.cases)
            self.generic_visit(node)

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            visitor = ComplexityVisitor()
            for child in node.body:
                visitor.visit(child)
            complexity = visitor.decision_points + 1  # +1 base path
            results.append({
                "name": node.name,
                "lineno": node.lineno,
                "complexity": complexity,
                "decision_points": visitor.decision_points,
            })

    results.sort(key=lambda x: x["complexity"], reverse=True)
    return results[:top_n]


