import ast


def find_high_complexity_functions(source_code, threshold=10):
    """
    Analyze Python source code and return functions whose cyclomatic
    complexity exceeds the given threshold, making them hard to test
    due to a large number of independent execution paths.

    Returns a list of dicts: {"name": str, "lineno": int, "complexity": int}
    """

    class ComplexityVisitor(ast.NodeVisitor):
        def __init__(self):
            self.results = []

        def visit_FunctionDef(self, node):
            complexity = self._compute_complexity(node)
            self.results.append({
                "name": node.name,
                "lineno": node.lineno,
                "complexity": complexity,
            })
            self.generic_visit(node)

        visit_AsyncFunctionDef = visit_FunctionDef

        def _compute_complexity(self, node):
            # Base complexity of 1 for the function itself
            complexity = 1
            for child in ast.walk(node):
                if isinstance(child, (ast.If, ast.For, ast.While,
                                       ast.Try, ast.ExceptHandler,
                                       ast.With, ast.Assert)):
                    complexity += 1
                elif isinstance(child, ast.BoolOp):
                    complexity += len(child.values) - 1
                elif isinstance(child, ast.comprehension):
                    complexity += 1 + len(child.ifs)
                elif isinstance(child, ast.Match):
                    complexity += len(getattr(child, "cases", []))
            return complexity

    tree = ast.parse(source_code)
    visitor = ComplexityVisitor()
    visitor.visit(tree)

    return [
        func for func in visitor.results
        if func["complexity"] >= threshold
    ]

