import ast


def find_high_complexity_functions(source_code, threshold=10):
    """
    Analyze Python source code and return functions whose cyclomatic
    complexity exceeds a given threshold, indicating many independent
    execution paths and thus higher difficulty to test thoroughly.

    Args:
        source_code (str): Python source code to analyze.
        threshold (int): Complexity threshold above which a function
            is flagged as hard-to-test.

    Returns:
        list of dict: Each dict contains 'name', 'lineno', and
        'complexity' for functions exceeding the threshold.
    """
    tree = ast.parse(source_code)
    results = []

    class ComplexityVisitor(ast.NodeVisitor):
        def __init__(self):
            self.complexity = 1

        def visit_If(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_For(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_While(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_Try(self, node):
            self.complexity += len(node.handlers)
            self.generic_visit(node)

        def visit_BoolOp(self, node):
            self.complexity += len(node.values) - 1
            self.generic_visit(node)

        def visit_With(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_comprehension(self, node):
            self.complexity += len(node.ifs)
            self.generic_visit(node)

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            visitor = ComplexityVisitor()
            for child in ast.iter_child_nodes(node):
                visitor.visit(child)

            if visitor.complexity > threshold:
                results.append({
                    "name": node.name,
                    "lineno": node.lineno,
                    "complexity": visitor.complexity,
                })

    return sorted(results, key=lambda x: x["complexity"], reverse=True)

