import ast


def find_hard_to_test_functions(source_code, complexity_threshold=10):
    """
    Analyze Python source code and return functions whose cyclomatic
    complexity (number of independent execution paths) exceeds
    complexity_threshold. High complexity functions are hard to test
    because they require many test cases to cover all branches.
    """
    tree = ast.parse(source_code)
    results = []

    class ComplexityVisitor(ast.NodeVisitor):
        def __init__(self):
            self.complexity = 1

        def visit_If(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_For(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_While(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_Try(self, node):
            self.complexity += len(node.handlers)
            self.generic_visit(node)

        def visit_BoolOp(self, node):
            self.complexity += len(node.values) - 1
            self.generic_visit(node)

        def visit_With(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_comprehension(self, node):
            self.complexity += 1 + len(node.ifs)
            self.generic_visit(node)

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            visitor = ComplexityVisitor()
            for child in node.body:
                visitor.visit(child)

            if visitor.complexity >= complexity_threshold:
                results.append({
                    "name": node.name,
                    "lineno": node.lineno,
                    "complexity": visitor.complexity,
                    "args": len(node.args.args),
                })

    results.sort(key=lambda f: f["complexity"], reverse=True)
    return results


