def classify_shipping_cost(weight, is_member, country, express, fragile, insured, coupon, season):
    """
    Compute shipping cost based on many independent conditions.
    High cyclomatic complexity - hard to unit test exhaustively
    due to combinatorial explosion of branches.
    """
    cost = 0.0

    if weight <= 0:
        raise ValueError("Weight must be positive")

    if weight < 1:
        cost = 5.0
    elif weight < 5:
        cost = 10.0
    elif weight < 10:
        cost = 18.0
    elif weight < 20:
        cost = 30.0
    else:
        cost = 30.0 + (weight - 20) * 1.5

    if country == "US":
        cost *= 1.0
    elif country == "CA":
        cost *= 1.1
    elif country == "MX":
        cost *= 1.15
    elif country in ("UK", "DE", "FR", "IT", "ES"):
        cost *= 1.3
    elif country in ("CN", "JP", "KR"):
        cost *= 1.4
    else:
        cost *= 1.6

    if express:
        if weight < 5:
            cost += 15
        elif weight < 20:
            cost += 25
        else:
            cost += 40
        if country != "US":
            cost += 10

    if fragile:
        cost += 8
        if weight > 10:
            cost += 5
        if express:
            cost += 3

    if insured:
        if weight < 5:
            cost += 2
        elif weight < 20:
            cost += 5
        else:
            cost += 10
        if country not in ("US", "CA"):
            cost += 4

    if is_member:
        if season == "holiday":
            cost *= 0.95
        else:
            cost *= 0.9
    else:
        if season == "holiday":
            cost *= 1.05

    if coupon:
        if coupon == "FREESHIP" and cost < 50:
            cost = 0
        elif coupon == "SAVE10":
            cost *= 0.9
        elif coupon == "SAVE20" and weight > 5:
            cost *= 0.8
        elif coupon.startswith("VIP"):
            if is_member:
                cost *= 0.7
            else:
                cost *= 0.85

    if season == "peak":
        if express:
            cost *= 1.2
        else:
            cost *= 1.1
    elif season == "off":
        cost *= 0.95

    if cost < 0:
        cost = 0
    elif cost > 500:
        cost = 500

    return round(cost, 2)

