def find_refactor_candidates(source_code, complexity_threshold=10):
    """
    Analyze Python source code and return functions whose cyclomatic
    complexity exceeds the given threshold, marking them as
    refactoring candidates due to complex control flow.
    """

    class ComplexityVisitor(ast.NodeVisitor):
        def __init__(self):
            self.complexity = 1

        def visit_If(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_For(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_While(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_Try(self, node):
            self.complexity += len(node.handlers)
            self.generic_visit(node)

        def visit_ExceptHandler(self, node):
            self.generic_visit(node)

        def visit_BoolOp(self, node):
            self.complexity += len(node.values) - 1
            self.generic_visit(node)

        def visit_With(self, node):
            self.complexity += 1
            self.generic_visit(node)

        def visit_comprehension(self, node):
            self.complexity += 1 + len(node.ifs)
            self.generic_visit(node)

    def compute_complexity(func_node):
        visitor = ComplexityVisitor()
        visitor.visit(func_node)
        return visitor.complexity

    def max_nesting_depth(func_node):
        max_depth = 0

        def walk(node, depth):
            nonlocal max_depth
            nesting_nodes = (ast.If, ast.For, ast.While, ast.Try, ast.With)
            if isinstance(node, nesting_nodes):
                depth += 1
                max_depth = max(max_depth, depth)
            for child in ast.iter_child_nodes(node):
                walk(child, depth)

        walk(func_node, 0)
        return max_depth

    try:
        tree = ast.parse(source_code)
    except SyntaxError:
        return []

    candidates = []

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            complexity = compute_complexity(node)
            nesting = max_nesting_depth(node)
            line_count = (node.end_lineno - node.lineno + 1) if hasattr(node, "end_lineno") else None

            if complexity >= complexity_threshold or nesting >= 4:
                candidates.append({
                    "name": node.name,
                    "lineno": node.lineno,
                    "complexity": complexity,
                    "max_nesting_depth": nesting,
