def process_loan_applications(applications, credit_bureau, bank_accounts, risk_engine):
    approved = []
    rejected = []
    manual_review = []

    for application in applications:
        try:
            if application.applicant:
                if application.applicant.age >= 18:
                    try:
                        credit_score = credit_bureau.get_score(application.applicant.ssn)
                    except ConnectionError:
                        manual_review.append((application, 'credit_bureau_unreachable'))
                        continue

                    if credit_score is not None:
                        if credit_score >= 700:
                            if application.amount <= 50000:
                                if application.applicant.employment_status == 'employed':
                                    monthly_income = application.applicant.monthly_income
                                    if monthly_income > 0:
                                        debt_ratio = application.monthly_debt / monthly_income
                                        if debt_ratio < 0.4:
                                            approved.append((application, 'auto_approved'))
                                        elif debt_ratio < 0.6:
                                            manual_review.append((application, 'high_debt_ratio'))
                                        else:
                                            rejected.append((application, 'debt_ratio_exceeded'))
                                    else:
                                        rejected.append((application, 'invalid_income'))
                                else:
                                    manual_review.append((application, 'unverified_employment'))
                            else:
                                for account in bank_accounts:
                                    if account.owner_id == application.applicant.id:
                                        if account.balance >= application.amount * 0.2:
                                            manual_review.append((application, 'large_amount_collateral_ok'))
                                            break
                                else:
                                    rejected.append((application, 'insufficient_collateral'))
                        elif credit_score >= 600:
                            manual_review.append((application, 'medium_credit_score'))
                        else:
                            rejected.append((application, 'low_credit_score'))
                    else:
                        rejected.append((application, 'no_credit_record'))
                else:
                    rejected.append((application, 'underage_applicant'))
            else:
                rejected.append((application, 'missing_applicant_info'))

            try:
                risk_engine.log_decision(application.id, 'processed')
            except Exception:
                pass

        except Exception as e:
            manual_review.append((application, f'unexpected_error:{str(e)}'))

    return {'approved': approved, 'rejected': rejected, 'manual_review': manual_review}

