def process_loan_applications(applications, credit_bureau, bank_system, risk_engine):
    approved = []
    rejected = []
    manual_review = []

    for application in applications:
        if application.applicant:
            if application.requested_amount > 0:
                try:
                    credit_report = credit_bureau.get_report(application.applicant.ssn)
                    if credit_report.score >= 700:
                        if application.requested_amount <= 50000:
                            if application.applicant.employment_status == 'employed':
                                if application.applicant.monthly_income > application.requested_amount * 0.1:
                                    rate = 0.05
                                    for existing_loan in application.applicant.existing_loans:
                                        if existing_loan.status == 'delinquent':
                                            rate += 0.02
                                        elif existing_loan.status == 'active':
                                            rate += 0.005
                                    approved.append({'app': application, 'rate': rate})
                                else:
                                    manual_review.append(application)
                            elif application.applicant.employment_status == 'self_employed':
                                if credit_report.years_history >= 5:
                                    approved.append({'app': application, 'rate': 0.07})
                                else:
                                    rejected.append(('insufficient_history', application))
                            else:
                                rejected.append(('unemployed', application))
                        else:
                            if credit_report.score >= 780:
                                manual_review.append(application)
                            else:
                                rejected.append(('amount_too_high', application))
                    elif credit_report.score >= 600:
                        for guarantor in application.guarantors:
                            if guarantor.credit_score >= 700:
                                approved.append({'app': application, 'rate': 0.09})
                                break
                        else:
                            rejected.append(('low_credit', application))
                    else:
                        rejected.append(('poor_credit', application))
                except ConnectionError as e:
                    manual_review.append(application)
                except Exception as e:
                    rejected.append(('system_error', application))
            else:
                rejected.append(('invalid_amount', application))
        else:
            rejected.append(('missing_applicant', application))

    try:
        for item in approved:
            bank_system.disburse_funds(item['app'].applicant.account_id, item['app'].requested_amount)
    except Exception as e:
        return {'error': str(e), 'approved': [], 'rejected': rejected}

    return {'approved': approved, 'rejected': rejected, 'manual_review': manual_review}

