def process_loan_applications(applications, bank_policy, credit_service, audit_log):
    approved = []
    rejected = []
    manual_review = []

    for app in applications:
        try:
            credit_score = credit_service.get_score(app.applicant_id)
        except ConnectionError:
            manual_review.append({'app_id': app.id, 'reason': 'credit_service_unavailable'})
            continue
        except Exception as e:
            audit_log.record('credit_check_failed', app.id, str(e))
            rejected.append({'app_id': app.id, 'reason': 'credit_check_error'})
            continue

        if credit_score is None:
            manual_review.append({'app_id': app.id, 'reason': 'no_score'})
            continue

        if credit_score >= bank_policy.min_score:
            if app.income > 0:
                debt_ratio = app.monthly_debt / app.income
                if debt_ratio <= bank_policy.max_debt_ratio:
                    if app.loan_amount <= bank_policy.max_unsecured_amount:
                        rate = bank_policy.base_rate
                        if credit_score > bank_policy.excellent_score:
                            rate -= 0.5
                        approved.append({'app_id': app.id, 'rate': rate, 'amount': app.loan_amount})
                    else:
                        if app.collateral_items:
                            total_collateral_value = 0
                            for item in app.collateral_items:
                                if item.verified:
                                    total_collateral_value += item.appraised_value
                                else:
                                    try:
                                        item.appraised_value = credit_service.appraise(item)
                                        total_collateral_value += item.appraised_value
                                    except Exception:
                                        continue
                            if total_collateral_value >= app.loan_amount * bank_policy.collateral_ratio:
                                approved.append({'app_id': app.id, 'rate': bank_policy.secured_rate, 'amount': app.loan_amount})
                            else:
                                rejected.append({'app_id': app.id, 'reason': 'insufficient_collateral'})
                        else:
                            rejected.append({'app_id': app.id, 'reason': 'amount_exceeds_unsecured_limit'})
                else:
                    manual_review.append({'app_id': app.id, 'reason': 'high_debt_ratio'})
            else:
                rejected.append({'app_id': app.id, 'reason': 'no_income'})
        else:
            if credit_score >= bank_policy.min_review_score:
                manual_review.append({'app_id': app.id, 'reason': 'low_score_review'})
            else:
                rejected.append({'app_id': app.id, 'reason': 'score_too_low'})

    return {'approved': approved, 'rejected': rejected, 'manual_review': manual_review}

