def process_shipment_batch(shipments, warehouse, carrier_api, inventory_service):
    processed = []
    failed = []

    for shipment in shipments:
        if shipment.status == 'pending':
            if shipment.items:
                total_weight = 0
                reserved_items = []
                for item in shipment.items:
                    if item.sku:
                        try:
                            stock = inventory_service.check_stock(warehouse.id, item.sku)
                            if stock >= item.quantity:
                                if item.is_fragile:
                                    if item.weight > 20:
                                        failed.append({'shipment': shipment.id, 'error': 'fragile_overweight'})
                                        continue
                                    else:
                                        total_weight += item.weight * item.quantity * 1.1
                                else:
                                    total_weight += item.weight * item.quantity
                                reserved_items.append(item)
                            else:
                                if item.allow_backorder:
                                    reserved_items.append(item)
                                else:
                                    failed.append({'shipment': shipment.id, 'error': 'out_of_stock', 'sku': item.sku})
                        except ConnectionError as e:
                            failed.append({'shipment': shipment.id, 'error': 'inventory_unreachable', 'detail': str(e)})
                            continue
                    else:
                        failed.append({'shipment': shipment.id, 'error': 'missing_sku'})

                if reserved_items:
                    if total_weight > 0:
                        try:
                            if total_weight > 500:
                                carrier = carrier_api.get_freight_carrier(warehouse.region)
                            else:
                                carrier = carrier_api.get_standard_carrier(warehouse.region)

                            label_result = carrier.create_label(shipment.address, total_weight)
                            if label_result.success:
                                inventory_service.commit_reservation(warehouse.id, reserved_items)
                                processed.append({'shipment': shipment.id, 'tracking': label_result.tracking_number})
                            else:
                                failed.append({'shipment': shipment.id, 'error': label_result.error})
                        except TimeoutError:
                            failed.append({'shipment': shipment.id, 'error': 'carrier_timeout'})
                        except Exception as e:
                            failed.append({'shipment': shipment.id, 'error': 'unexpected', 'detail': str(e)})
                else:
                    failed.append({'shipment': shipment.id, 'error': 'no_items_reserved'})
            else:
                failed.append({'shipment': shipment.id, 'error': 'empty_shipment'})
        else:
            failed.append({'shipment': shipment.id, 'error': 'invalid_status'})

    return {'processed': processed, 'failed': failed}

