    total_disbursed = 0

    if loan_application.status == 'approved':
        if loan_application.applicant.credit_score >= 600:
            if loan_application.collateral_items:
                for collateral in loan_application.collateral_items:
                    try:
                        valuation = credit_bureau.appraise(collateral.asset_id)
                    except ConnectionError as e:
                        return {'status': 'error', 'stage': 'appraisal', 'message': str(e)}
                    except TimeoutError:
                        try:
                            valuation = credit_bureau.appraise(collateral.asset_id, retry=True)
                        except Exception as e2:
                            return {'status': 'error', 'stage': 'appraisal_retry', 'message': str(e2)}

                    if valuation.value > 0:
                        if valuation.value < collateral.declared_value * 0.8:
                            disbursement_log.append(('undervalued', collateral.asset_id))
                        else:
                            if collateral.lien_status == 'clear':
                                disbursement_log.append(('accepted', collateral.asset_id))
                            else:
                                try:
                                    ledger_service.flag_lien(collateral.asset_id)
                                except KeyError:
                                    pass
                                except Exception as e3:
                                    return {'status': 'error', 'stage': 'lien_flag', 'message': str(e3)}
                    else:
                        disbursement_log.append(('zero_value', collateral.asset_id))
            else:
                if loan_application.amount > 50000:
                    return {'status': 'rejected', 'reason': 'collateral_required'}
        else:
            if loan_application.co_signer:
                if loan_application.co_signer.credit_score < 650:
                    return {'status': 'rejected', 'reason': 'insufficient_cosigner_score'}
            else:
                return {'status': 'rejected', 'reason': 'low_credit_no_cosigner'}
    else:
        return {'status': 'rejected', 'reason': 'application_not_approved'}

    try:
        for tranche in loan_application.disbursement_schedule:
            try:
                result = bank_account_service.transfer(
                    loan_application.applicant.account_id, tranche.amount
                )
            except InsufficientFundsError:
                disbursement_log.append(('skipped_insufficient_funds', tranche.id))
                continue
            except PermissionError as pe:
                return {'status': 'error', 'stage': 'transfer_permission', 'message': str(pe)}

            if result.success:
                total_disbursed += tranche.amount
                disbursement_log.append(('disbursed', tranche.id, tranche.amount))
            else:
                disbursement_log.append(('failed', tranche.id, result.error))

