def process_loan_disbursement(application, bank_accounts, risk_engine, ledger_service):
    results = {'disbursed': [], 'failed': [], 'flagged': []}

    if not application.is_approved:
        return {'error': 'Application not approved'}

    if application.applicant:
        for installment in application.installments:
            if installment.status == 'pending':
                try:
                    if installment.amount > 0:
                        if application.risk_level == 'high':
                            try:
                                score = risk_engine.evaluate(application.applicant, installment.amount)
                            except ConnectionError as ce:
                                results['failed'].append((installment.id, f'risk_engine_unreachable: {ce}'))
                                continue
                            except TimeoutError:
                                results['flagged'].append((installment.id, 'risk_engine_timeout'))
                                continue

                            if score is not None:
                                if score < 0.3:
                                    results['failed'].append((installment.id, 'risk_score_too_low'))
                                    continue
                                elif score < 0.6:
                                    installment.amount *= 0.8
                                    results['flagged'].append((installment.id, 'partial_approval'))
                            else:
                                results['failed'].append((installment.id, 'risk_score_unavailable'))
                                continue

                        account = None
                        for acct in bank_accounts:
                            if acct.owner_id == application.applicant.id:
                                if acct.is_active:
                                    account = acct
                                    break

                        if account is None:
                            results['failed'].append((installment.id, 'no_active_account'))
                            continue

                        try:
                            transfer_result = ledger_service.transfer(account.id, installment.amount)
                        except InsufficientFundsError:
                            results['failed'].append((installment.id, 'insufficient_pool_funds'))
                            continue
                        except Exception as e:
                            results['failed'].append((installment.id, f'ledger_error: {e}'))
                            continue

                        if transfer_result.success:
                            installment.status = 'disbursed'
                            results['disbursed'].append(installment.id)
                        else:
                            results['failed'].append((installment.id, transfer_result.error))
                    else:
                        results['failed'].append((installment.id, 'invalid_amount'))
                except Exception as outer_e:
                    results['failed'].append((installment.id, f'unexpected_error: {outer_e}'))
    else:
        return {'error': 'Missing applicant data'}

    return results

