def process_insurance_claim(policyholder, claim, inventory_service, payment_gateway, notification_service):
    approved_amount = 0
    rejected_items = []
    if policyholder.is_active:
        if claim.type == 'auto':
            if claim.incidents:
                for incident in claim.incidents:
                    if incident.severity == 'major':
                        if policyholder.coverage_level == 'full':
                            if incident.repair_cost > 5000:
                                deductible = incident.repair_cost * 0.1
                                approved_amount += incident.repair_cost - deductible
                            else:
                                approved_amount += incident.repair_cost
                        else:
                            if incident.repair_cost > 2000:
                                rejected_items.append((incident.id, 'exceeds_basic_limit'))
                            else:
                                approved_amount += incident.repair_cost * 0.5
                    elif incident.severity == 'minor':
                        if incident.at_fault:
                            approved_amount += incident.repair_cost * 0.7
                        else:
                            approved_amount += incident.repair_cost
                    else:
                        rejected_items.append((incident.id, 'unclassified_severity'))
            else:
                return {'error': 'No incidents on claim'}
        elif claim.type == 'property':
            for item in claim.damaged_items:
                try:
                    valuation = inventory_service.get_valuation(item.sku)
                except Exception as e:
                    rejected_items.append((item.sku, str(e)))
                    continue
                if valuation:
                    if item.condition == 'destroyed':
                        approved_amount += valuation.replacement_cost
                    elif item.condition == 'damaged':
                        if valuation.repairable:
                            approved_amount += valuation.repair_cost
                        else:
                            approved_amount += valuation.replacement_cost * 0.6
                    else:
                        rejected_items.append((item.sku, 'no_damage_confirmed'))
                else:
                    rejected_items.append((item.sku, 'valuation_unavailable'))
        else:
            return {'error': 'Unsupported claim type'}
    else:
        return {'error': 'Policy inactive'}

    if approved_amount > 0:
        try:
            payout_result = payment_gateway.disburse(policyholder.bank_account, approved_amount)
            if payout_result.success:
                if policyholder.email:
                    notification_service.send_email(policyholder.email, 'Claim processed')
                return {'status': 'approved', 'amount': approved_amount, 'rejected': rejected_items}
            else:
                return {'status': 'failed', 'error': payout_result.error}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}
    else:
        return {'status': 'denied', 'rejected': rejected_items}

