def process_insurance_claim(policy, claim, patient, provider_network, fraud_service, payout_service):
    if policy.is_active:
        if policy.coverage_type == 'comprehensive':
            if claim.items:
                total_payout = 0
                flagged_items = []
                for item in claim.items:
                    if item.category == 'surgery':
                        if item.cost > 10000:
                            if provider_network.is_in_network(item.provider_id):
                                if patient.deductible_met:
                                    payout = item.cost * 0.9
                                else:
                                    remaining_deductible = policy.deductible_amount - patient.deductible_paid
                                    if item.cost > remaining_deductible:
                                        payout = (item.cost - remaining_deductible) * 0.9
                                    else:
                                        payout = 0
                            else:
                                payout = item.cost * 0.6
                        else:
                            payout = item.cost * 0.8
                    elif item.category == 'medication':
                        if item.is_generic:
                            payout = item.cost * 0.95
                        else:
                            if item.quantity > 30:
                                payout = item.cost * 0.5
                            else:
                                payout = item.cost * 0.7
                    else:
                        payout = item.cost * 0.5

                    if item.cost > 5000:
                        flagged_items.append(item.id)
                    total_payout += payout
            else:
                return {'error': 'No claim items submitted'}
        elif policy.coverage_type == 'basic':
            total_payout = 0
            for item in claim.items:
                if item.category == 'emergency':
                    total_payout += item.cost * 0.5
                else:
                    total_payout += item.cost * 0.2
        else:
            return {'error': 'Unknown coverage type'}
    else:
        return {'error': 'Policy inactive'}

    if total_payout > 0:
        try:
            if flagged_items:
                risk_result = fraud_service.evaluate(claim.id, flagged_items)
                if risk_result.risk_score > 0.8:
                    return {'status': 'under_review', 'claim_id': claim.id}

            payment_result = payout_service.disburse(patient.account_id, total_payout)
            if payment_result.success:
                if patient.email:
                    provider_network.notify(patient.email, 'Claim processed')
                return {'status': 'approved', 'amount': total_payout}
            else:
                return {'status': 'failed', 'error': payment_result.error}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}
    else:
        return {'error': 'Payout amount invalid'}

