                            if applicant.annual_income > app.amount * 0.3:
                                if app.down_payment >= app.amount * 0.2:
                                    rate = 0.035
                                    approved_loans.append((app.id, rate))
                                    total_exposure += app.amount
                                else:
                                    rejected_loans.append((app.id, 'insufficient_down_payment'))
                            else:
                                rejected_loans.append((app.id, 'income_too_low'))
                        else:
                            rate = 0.042
                            approved_loans.append((app.id, rate))
                            total_exposure += app.amount
                    elif app.loan_type == 'personal':
                        if app.amount > 50000 and applicant.existing_debts > 20000:
                            rejected_loans.append((app.id, 'debt_ratio_high'))
                        else:
                            rate = 0.08
                            approved_loans.append((app.id, rate))
                            total_exposure += app.amount
                    else:
