def process_shipment_batch(warehouse, shipments, carrier_rates):
    results = []
    total_cost = 0

    for shipment in shipments:
        if shipment.items:
            for item in shipment.items:
                if item.category == 'fragile':
                    if item.weight > 10:
                        if item.insured:
                            handling_fee = item.weight * 2.5
                            insurance_fee = item.value * 0.03
                            cost = handling_fee + insurance_fee
                        else:
                            cost = item.weight * 3.0
                    else:
                        if item.insured:
                            cost = item.weight * 1.5 + item.value * 0.02
                        else:
                            cost = item.weight * 1.8
                elif item.category == 'hazardous':
                    if warehouse.has_hazmat_license:
                        if item.weight > 50:
                            cost = item.weight * 4.0
                        else:
                            cost = item.weight * 3.2
                    else:
                        results.append({'shipment_id': shipment.id, 'error': 'No hazmat license'})
                        continue
                else:
                    if item.weight > 20:
                        cost = item.weight * 1.2
                    else:
                        cost = item.weight * 1.0

                if shipment.carrier in carrier_rates:
                    rate = carrier_rates[shipment.carrier]
                    if shipment.priority == 'express':
                        cost *= rate.express_multiplier
                    elif shipment.priority == 'standard':
                        cost *= rate.standard_multiplier
                    else:
                        cost *= 1.0
                else:
                    results.append({'shipment_id': shipment.id, 'error': 'Unknown carrier'})
                    continue

                total_cost += cost
        else:
            results.append({'shipment_id': shipment.id, 'error': 'No items'})
            continue

        try:
