        except Exception as e:
            results.append({'shipment_id': shipment.id, 'status': 'error', 'message': str(e)})

    if total_cost > 0:
        return {'status': 'completed', 'total_cost': total_cost, 'details': results}
    else:
        return {'status': 'no_valid_shipments', 'details': results}

