        id_ = payload.get("id")
        if id_ is None:
            raise ValueError("id required for update")
        return {"status": "updated", "id": id_, "fields": payload.get("fields", {})}

    elif action == "delete":
        id_ = payload.get("id")
        if id_ is None:
            raise ValueError("id required for delete")
        return {"status": "deleted", "id": id_}

    elif action == "list":
        filters = payload.get("filters", {})
