        if fmt not in ("json", "csv", "xml"):
            raise ValueError(f"unsupported format: {fmt}")
        return {"status": "exported", "format": fmt}

    elif action == "import":
        source = payload.get("source")
        if not source:
            raise ValueError("source required for import")
        return {"status": "imported", "source": source}

    elif action == "validate":
        data = payload.get("data")
        if data is None:
            raise ValueError("data required for validate")
        return {"status": "validated", "ok": True}

