        target = payload.get("target")
        message = payload.get("message", "")
        if not target:
            raise ValueError("target required for notify")
        return {"status": "notified", "target": target, "message": message}

    elif action == "reset":
        return {"status": "reset"}

    elif action == "status":
        return {"status": "ok", "action": "status"}

