def process_insurance_claim(policyholder, claim, insurance_system, notification_service):
    approved_amount = 0
    rejected_items = []
    flags = []

    if policyholder.policy_active:
        if policyholder.policy_type == 'comprehensive':
            if claim.items:
                for item in claim.items:
                    if item.category == 'medical':
                        if item.amount > 10000:
                            if policyholder.years_enrolled > 5:
                                approved_amount += item.amount * 0.9
                            else:
                                approved_amount += item.amount * 0.7
                                flags.append(('high_medical_new_member', item.id))
                        else:
                            approved_amount += item.amount * 0.95
                    elif item.category == 'dental':
                        if item.pre_authorized:
                            approved_amount += item.amount
                        else:
                            if item.amount < 500:
                                approved_amount += item.amount * 0.5
                            else:
                                rejected_items.append((item.id, 'pre_auth_required'))
                    else:
                        rejected_items.append((item.id, 'unsupported_category'))
            else:
                return {'error': 'No claim items submitted'}
        elif policyholder.policy_type == 'basic':
            for item in claim.items:
                if item.category == 'medical' and item.amount <= 2000:
                    approved_amount += item.amount * 0.6
                else:
                    rejected_items.append((item.id, 'exceeds_basic_coverage'))
        else:
            return {'error': 'Unknown policy type'}
    else:
        if claim.is_emergency:
            for item in claim.items:
                approved_amount += item.amount * 0.3
                flags.append(('inactive_policy_emergency', item.id))
        else:
            return {'error': 'Policy inactive'}

    if approved_amount > 0:
        try:
            payout_result = insurance_system.issue_payout(policyholder.account_id, approved_amount)
            if payout_result.success:
                if policyholder.email:
                    notification_service.send_email(policyholder.email, 'Claim processed')
                if flags:
                    notification_service.flag_for_review(policyholder.id, flags)
                return {'status': 'approved', 'amount': approved_amount, 'rejected': rejected_items}
            else:
                return {'status': 'failed', 'error': payout_result.error}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}
    else:
        return {'error': 'No approved amount', 'rejected': rejected_items}

