def find_large_functions(source_code, max_lines=50, max_branches=10):
    """
    Analyze Python source code and return a list of functions that are
    too large or too complex (likely violating single-responsibility).

    Each result dict contains: name, lineno, end_lineno, num_lines,
    num_branches, num_calls, reasons.
    """
    tree = ast.parse(source_code)
    results = []

    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue

        start = node.lineno
        end = getattr(node, "end_lineno", start)
        num_lines = end - start + 1

        num_branches = sum(
            1 for n in ast.walk(node)
            if isinstance(n, (ast.If, ast.For, ast.While, ast.Try, ast.With))
        )

        num_calls = sum(1 for n in ast.walk(node) if isinstance(n, ast.Call))

        num_returns = sum(1 for n in ast.walk(node) if isinstance(n, ast.Return))

        nested_funcs = sum(
            1 for n in ast.walk(node)
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n is not node
        )

        reasons = []
        if num_lines > max_lines:
            reasons.append(f"too long ({num_lines} lines > {max_lines})")
        if num_branches > max_branches:
            reasons.append(f"too many branches ({num_branches} > {max_branches})")
        if num_calls > 20:
            reasons.append(f"too many calls ({num_calls})")
        if num_returns > 5:
            reasons.append(f"too many return points ({num_returns})")
        if nested_funcs > 2:
            reasons.append(f"too many nested functions ({nested_funcs})")

        if reasons:
            results.append({
                "name": node.name,
                "lineno": start,
                "end_lineno": end,
                "num_lines": num_lines,
                "num_branches": num_branches,
                "num_calls": num_calls,
                "num_returns": num_returns,
                "nested_funcs": nested_funcs,
                "reasons": reasons,
            })

    return results


