def process_shipment_batch(warehouse, shipments, carrier_service, inventory_db):
    processed = []
    failed = []
    for shipment in shipments:
        if shipment.items:
            for item in shipment.items:
                if item.sku in inventory_db.stock:
                    stock = inventory_db.stock[item.sku]
                    if stock.quantity >= item.requested_qty:
                        if item.is_fragile:
                            if shipment.destination.is_international:
                                if shipment.weight_kg > 20:
                                    item.packaging = 'reinforced_crate'
                                    item.shipping_cost = item.weight_kg * 4.5
                                else:
                                    item.packaging = 'bubble_wrap'
                                    item.shipping_cost = item.weight_kg * 3.0
                            else:
                                item.packaging = 'standard_fragile'
                                item.shipping_cost = item.weight_kg * 1.5
                        else:
                            if shipment.priority == 'express':
                                item.shipping_cost = item.weight_kg * 2.0
                            else:
                                item.shipping_cost = item.weight_kg * 1.0
                        stock.quantity -= item.requested_qty
                    else:
                        failed.append({'sku': item.sku, 'reason': 'insufficient_stock'})
                        continue
                else:
                    failed.append({'sku': item.sku, 'reason': 'sku_not_found'})
                    continue
        else:
            failed.append({'shipment_id': shipment.id, 'reason': 'no_items'})
            continue

        try:
            label = carrier_service.generate_label(shipment)
            if label.success:
                if shipment.insurance_requested:
                    if shipment.declared_value > 500:
                        carrier_service.add_insurance(shipment.id, shipment.declared_value * 0.02)
                    else:
                        carrier_service.add_insurance(shipment.id, 5.0)
                processed.append({'shipment_id': shipment.id, 'tracking': label.tracking_number})
            else:
                failed.append({'shipment_id': shipment.id, 'reason': label.error})
        except ConnectionError as e:
            failed.append({'shipment_id': shipment.id, 'reason': f'carrier_timeout: {e}'})
        except Exception as e:
            failed.append({'shipment_id': shipment.id, 'reason': f'unexpected: {e}'})

    return {'processed': processed, 'failed': failed}

