import ast

def find_deep_indentation_functions(source_code, max_depth=4):
    tree = ast.parse(source_code)
    results = []

    def get_depth(node, current_depth=0):
        max_d = current_depth
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.If, ast.For, ast.While, ast.Try,
                                   ast.With, ast.FunctionDef, ast.AsyncFunctionDef,
                                   ast.ClassDef, ast.ExceptHandler)):
                child_depth = get_depth(child, current_depth + 1)
            else:
                child_depth = get_depth(child, current_depth)
            if child_depth > max_d:
                max_d = child_depth
        return max_d

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            depth = get_depth(node)
            if depth >= max_depth:
                results.append({
                    "name": node.name,
                    "lineno": node.lineno,
                    "max_depth": depth
                })

    return sorted(results, key=lambda x: x["max_depth"], reverse=True)


def find_deep_indentation_in_file(filepath, max_depth=4):
    with open(filepath, "r", encoding="utf-8") as f:
        source_code = f.read()
    return find_deep_indentation_functions(source_code, max_depth)


