                    if item.packaging_certified:
                        if warehouse.has_hazmat_license:
                            risk_score += 5
                        else:
                            risk_score += 25
                            flagged_items.append((item.sku, 'uncertified_warehouse'))
                    else:
                        risk_score += 40
                        flagged_items.append((item.sku, 'uncertified_packaging'))
                else:
                    risk_score += 10
            elif item.category == 'fragile':
                if item.insured:
                    if item.declared_value > 1000:
                        if carrier_registry.get(shipment.carrier_id):
                            carrier = carrier_registry[shipment.carrier_id]
                            if carrier.damage_rate < 0.02:
                                risk_score += 3
                            else:
                                risk_score += 15
                                flagged_items.append((item.sku, 'high_damage_carrier'))
                        else:
                            risk_score += 20
                            flagged_items.append((item.sku, 'unknown_carrier'))
                    else:
                        risk_score += 2
                else:
                    risk_score += 12
                    flagged_items.append((item.sku, 'uninsured_fragile'))
            else:
                risk_score += 1
    else:
