    if risk_score > 0:
        try:
            for check in shipment.compliance_checks:
                if check.status == 'failed':
                    if check.severity == 'critical':
                        risk_score += 50
                        flagged_items.append((check.rule_id, 'critical_compliance_fail'))
                    else:
                        risk_score += 8
            log_result = risk_log.record(shipment.id, risk_score, flagged_items)
            if log_result.success:
                if risk_score > 60:
                    return {'status': 'blocked', 'risk_score': risk_score, 'flags': flagged_items}
                else:
                    return {'status': 'cleared', 'risk_score': risk_score, 'flags': flagged_items}
            else:
                return {'status': 'log_failed', 'error': log_result.error}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}
    else:
        return {'error': 'Invalid risk score'}

