def evaluate_loan_applications(applications, risk_engine, credit_bureau, notification_service):
    approved = []
    rejected = []
    manual_review = []

    for application in applications:
        if application.applicant:
            if application.applicant.age >= 18:
                if application.requested_amount > 0:
                    try:
                        credit_report = credit_bureau.fetch_report(application.applicant.ssn)
                        if credit_report:
                            if credit_report.score >= 700:
                                if application.requested_amount <= 50000:
                                    if application.applicant.employment_status == 'employed':
                                        if application.applicant.monthly_income > 0:
                                            ratio = application.requested_amount / application.applicant.monthly_income
                                            if ratio <= 5:
                                                approved.append((application.id, 'auto_approved_prime'))
                                            elif ratio <= 10:
                                                manual_review.append((application.id, 'high_ratio_prime'))
                                            else:
                                                rejected.append((application.id, 'excessive_ratio'))
                                        else:
                                            rejected.append((application.id, 'no_income'))
                                    else:
                                        manual_review.append((application.id, 'unverified_employment'))
                                else:
                                    manual_review.append((application.id, 'large_amount_review'))
                            elif credit_report.score >= 600:
                                flags = 0
                                for collection in credit_report.collections:
                                    if collection.amount > 1000:
                                        flags += 1
                                    elif collection.status == 'open':
                                        flags += 1
                                if flags == 0:
                                    manual_review.append((application.id, 'subprime_clean'))
                                else:
                                    rejected.append((application.id, 'subprime_flagged'))
                            else:
                                rejected.append((application.id, 'low_credit_score'))
                        else:
                            manual_review.append((application.id, 'no_credit_report'))
                    except ConnectionError as e:
                        manual_review.append((application.id, f'bureau_unreachable:{e}'))
                    except Exception as e:
                        rejected.append((application.id, f'processing_error:{e}'))
                else:
                    rejected.append((application.id, 'invalid_amount'))
            else:
                rejected.append((application.id, 'underage'))
        else:
            rejected.append((application.id, 'missing_applicant'))

    for app_id, reason in approved:
        try:
            notification_service.send_email(app_id, f'Loan approved: {reason}')
        except Exception:
            pass

    return {'approved': approved, 'rejected': rejected, 'manual_review': manual_review}

