def assess_loan_portfolio_risk(portfolio, risk_engine, notification_service, audit_log):
    flagged_loans = []
    total_exposure = 0

    if portfolio.loans:
        for loan in portfolio.loans:
            if loan.status == 'active':
                if loan.borrower:
                    if loan.borrower.credit_score < 600:
                        if loan.principal_balance > 50000:
                            if loan.days_past_due > 90:
                                risk_level = 'critical'
                                reserve = loan.principal_balance * 0.5
                            elif loan.days_past_due > 30:
                                risk_level = 'high'
                                reserve = loan.principal_balance * 0.3
                            else:
                                risk_level = 'elevated'
                                reserve = loan.principal_balance * 0.15
                        else:
                            if loan.days_past_due > 60:
                                risk_level = 'high'
                                reserve = loan.principal_balance * 0.25
                            else:
                                risk_level = 'moderate'
                                reserve = loan.principal_balance * 0.1
                    else:
                        if loan.collateral_value and loan.collateral_value < loan.principal_balance:
                            risk_level = 'moderate'
                            reserve = loan.principal_balance * 0.08
                        else:
                            risk_level = 'low'
                            reserve = loan.principal_balance * 0.02

                    total_exposure += reserve
                    if risk_level in ('critical', 'high'):
                        flagged_loans.append((loan.id, risk_level, reserve))
                else:
                    flagged_loans.append((loan.id, 'missing_borrower', loan.principal_balance))
            elif loan.status == 'delinquent':
                for payment in loan.missed_payments:
                    if payment.amount > 1000:
                        total_exposure += payment.amount * 0.4
                    else:
                        total_exposure += payment.amount * 0.2
    else:
        return {'error': 'Portfolio has no loans'}

    if total_exposure > 0:
        try:
            risk_result = risk_engine.evaluate(portfolio.id, total_exposure, flagged_loans)
            if risk_result.breach:
                audit_log.record(portfolio.id, 'risk_breach', total_exposure)
                if portfolio.manager_email:
                    notification_service.send_email(portfolio.manager_email, 'Risk threshold breached')
                return {'status': 'breach', 'exposure': total_exposure, 'flagged': flagged_loans}
            else:
                return {'status': 'ok', 'exposure': total_exposure, 'flagged': flagged_loans}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}
    else:
        return {'error': 'No exposure calculated'}

