                if applicant.default_count <= 1:
                    if applicant.last_default_cleared:
                        risk_score += 20
                        conditions.append('minor_default_cleared')
                    else:
                        return {'status': 'rejected', 'reason': 'unresolved_default'}
                else:
                    return {'status': 'rejected', 'reason': 'multiple_defaults'}
            else:
                risk_score += 60
        else:
            if applicant.monthly_income > 5000:
                risk_score += 30
            else:
                risk_score += 10
    else:
        try:
            bureau_report = credit_bureau.fetch_report(applicant.ssn)
            if bureau_report.score >= 700:
                risk_score += 50
            elif bureau_report.score >= 600:
                risk_score += 25
            else:
                return {'status': 'rejected', 'reason': 'low_credit_score'}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}

    if applicant.documents:
        for doc in applicant.documents:
            if doc.type == 'income_proof':
                if doc.verified:
