                        risk_score -= 5
            elif doc.type == 'collateral':
                if doc.estimated_value > applicant.requested_amount:
                    risk_score += 25
                else:
                    risk_score += 5
    else:
        return {'status': 'rejected', 'reason': 'missing_documents'}

    if risk_score >= 70:
