def process_insurance_claim(claimant, policy, claim):
    if policy.is_active:
        if policy.coverage_type == 'comprehensive':
            if claim.incident_type in ('collision', 'theft', 'fire'):
                if claim.estimated_damage > 0:
                    total_payout = 0
                    deductions = []
                    for item in claim.damaged_items:
                        if item.category == 'vehicle_part':
                            if item.repair_cost > policy.part_cost_limit:
                                payout = policy.part_cost_limit
                                deductions.append(('part_limit_exceeded', item.repair_cost - policy.part_cost_limit))
                            else:
                                payout = item.repair_cost
                            if item.is_aftermarket:
                                payout *= 0.7
                                deductions.append(('aftermarket_penalty', item.repair_cost * 0.3))
                            total_payout += payout
                        elif item.category == 'personal_property':
                            if item.has_receipt:
                                total_payout += min(item.declared_value, policy.personal_property_limit)
                            else:
                                total_payout += min(item.declared_value * 0.5, policy.personal_property_limit)
                        else:
                            total_payout += item.declared_value * 0.25
                    if policy.deductible < total_payout:
                        total_payout -= policy.deductible
                    else:
                        return {'status': 'denied', 'reason': 'deductible_exceeds_payout'}
                else:
                    return {'status': 'denied', 'reason': 'no_estimated_damage'}
            else:
                return {'status': 'denied', 'reason': 'incident_not_covered'}
        elif policy.coverage_type == 'liability_only':
            if claim.incident_type == 'collision' and claim.at_fault_party != claimant.id:
                total_payout = min(claim.estimated_damage, policy.liability_limit)
            else:
                return {'status': 'denied', 'reason': 'liability_only_no_coverage'}
        else:
            return {'status': 'denied', 'reason': 'unknown_coverage_type'}
    else:
        return {'status': 'denied', 'reason': 'policy_inactive'}

    if total_payout > 0:
        try:
            disbursement = payout_service.issue_payment(claimant.account, total_payout)
            if disbursement.success:
                for witness in claim.witnesses:
