import ast
from collections import defaultdict


def find_complexity_hotspots(source_paths, branch_threshold=10):
    """
    Analyze Python source files to find functions with high branching
    complexity (potential technical debt hotspots).

    Args:
        source_paths: list of file paths to analyze.
        branch_threshold: minimum cyclomatic complexity to flag as hotspot.

    Returns:
        List of dicts sorted by complexity descending:
        {file, function, line, complexity}
    """
    hotspots = []

    for path in source_paths:
        try:
            with open(path, "r", encoding="utf-8") as f:
                source = f.read()
        except (OSError, UnicodeDecodeError):
            continue

        try:
            tree = ast.parse(source, filename=path)
        except SyntaxError:
            continue

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                complexity = _calculate_cyclomatic_complexity(node)
                if complexity >= branch_threshold:
                    hotspots.append({
                        "file": path,
                        "function": node.name,
                        "line": node.lineno,
                        "complexity": complexity,
                    })

    hotspots.sort(key=lambda h: h["complexity"], reverse=True)
    return hotspots


def _calculate_cyclomatic_complexity(func_node):
    """
    Compute cyclomatic complexity for a function AST node by counting
    decision points (branches, loops, exception handlers, boolean ops).
    """
    complexity = 1

    for node in ast.walk(func_node):
        if isinstance(node, (ast.If, ast.For, ast.AsyncFor, ast.While,
                              ast.ExceptHandler, ast.With, ast.AsyncWith)):
            complexity += 1
        elif isinstance(node, ast.BoolOp):
            complexity += len(node.values) - 1
        elif isinstance(node, ast.comprehension):
            complexity += 1 + len(node.ifs)
        elif isinstance(node, ast.Match):
            complexity += len(node.cases)
        elif isinstance(node, ast.Try):
            complexity += len(node.handlers)

    return complexity


def summarize_hotspots_by_file(hotspots):
    """
    Aggregate hotspot complexity totals and counts per file.

    Returns:
        dict mapping file -> {"total_complexity": int, "count": int}
    """
    summary = defaultdict(lambda: {"total_complexity": 0, "count": 0})

    for hotspot in hotspots:
        entry = summary[hotspot["file"]]
        entry["total_complexity"] += hotspot["complexity"]
        entry["count"] += 1

    return dict(summary)

