def _cyclomatic_complexity(node):
    """Count decision points in a function AST node to approximate
    McCabe cyclomatic complexity."""
    complexity = 1
    for child in ast.walk(node):
        if isinstance(child, (ast.If, ast.For, ast.While, ast.Try,
                               ast.With, ast.Assert)):
            complexity += 1
        elif isinstance(child, ast.BoolOp):
            complexity += len(child.values) - 1
        elif isinstance(child, ast.ExceptHandler):
            complexity += 1
        elif isinstance(child, (ast.comprehension,)):
            complexity += 1 + len(getattr(child, "ifs", []))
    return complexity


def find_complexity_hotspots(root_dir, threshold=10):
    """
    Scan a directory tree of Python files and return functions whose
    cyclomatic complexity exceeds the given threshold, flagging them
    as potential technical debt hotspots due to high branching logic.

    :param root_dir: path to the root directory to scan
    :param threshold: minimum complexity score to be reported
    :return: list of Hotspot namedtuples sorted by complexity (desc)
    """
    hotspots = []

    for path in Path(root_dir).rglob("*.py"):
        try:
            source = path.read_text(encoding="utf-8")
            tree = ast.parse(source, filename=str(path))
        except (SyntaxError, UnicodeDecodeError, OSError):
