import ast
from pathlib import Path


def find_complexity_hotspots(root_dir, threshold=10, top_n=20):
    """
    Scan a Python codebase and identify functions/methods with high
    cyclomatic complexity, flagging them as technical debt hotspots.

    Args:
        root_dir: path to the directory to scan.
        threshold: minimum complexity score to be considered a hotspot.
        top_n: maximum number of hotspots to return, sorted by complexity.

    Returns:
        List of dicts: {file, function, line, complexity}
    """

    def compute_complexity(node):
        complexity = 1
        for child in ast.walk(node):
            if isinstance(child, (ast.If, ast.For, ast.While, ast.Try,
                                   ast.ExceptHandler, ast.With,
                                   ast.Assert, ast.IfExp)):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                complexity += len(child.values) - 1
            elif isinstance(child, (ast.comprehension,)):
                complexity += 1
        return complexity

    hotspots = []

    for file_path in Path(root_dir).rglob("*.py"):
        try:
            source = file_path.read_text(encoding="utf-8")
            tree = ast.parse(source, filename=str(file_path))
        except (SyntaxError, UnicodeDecodeError, OSError):
            continue

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                score = compute_complexity(node)
                if score >= threshold:
                    hotspots.append({
                        "file": str(file_path),
                        "function": node.name,
                        "line": node.lineno,
                        "complexity": score,
                    })

    hotspots.sort(key=lambda h: h["complexity"], reverse=True)
    return hotspots[:top_n]
